-- 0228 Monumentos PDF (inventario_monumentos_pdf) parte 4
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08054','iglesia','La Iglesia de San Vicente de Castellbisbal','La Iglesia de San Vicente de Castellbisbal (siglo XVI) es un templo de transición gótico-renacentista edificado en cantería de granito y arenisca con una nave única de amplias proporciones y capillas entre contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08054','monumento','El Puente del Diablo','El Puente del Diablo (Pont del Diable) (siglo XIII) es una infraestructura gótica construida sobre cimientos romanos que conecta con Martorell, alzada en sillería de arenisca con un gran arco apuntado central y perfil de lomo de asno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08056','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08056','monumento','El Castillo de Fels','El Castillo de Fels (siglo X-XVI) es un conjunto fortificado militar alzado sobre una colina con sillería de arenisca rojiza de Garraf que integra la antigua iglesia románica de Santa Maria dentro de su recinto amurallado con torreones defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08056','monumento','Las Torres de Vigía Costeras','Las Torres de Vigía Costeras (Torre Barona, Torre de Antoni) (siglo XVI) son estructuras defensivas cilíndricas levantadas con mampostería de piedra caliza para vigilar el litoral y avisar a la población ante los ataques de piratas berberiscos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08058','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08058','monumento','El Castillo de Castellet','El Castillo de Castellet (siglo X-XII) es una fortaleza medieval de frontera alzada sobre un espolón rocoso que domina el río Foix, edificada en sillería caliza regular y restaurada con una gran torre de homenaje circular y murallas almenadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08058','iglesia','La Iglesia de San Pedro de Castellet','La Iglesia de San Pedro de Castellet (siglo XII) es un templo románico edificado en sillería de piedra calcárea fina que presenta una única nave cubierta con bóveda de cañón y un ábside semicircular exento de ornamentación compleja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08058','monumento','El Acueducto de las dehesas','El Acueducto de las dehesas (siglo XIX) es una infraestructura logística de conducción hidráulica preindustrial construida con arquerías de mampostería caliza y ladrillo para el riego de las llanuras agrícolas del Penedès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08059','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08059','iglesia','La Iglesia de San Pedro de Castellfollit','La Iglesia de San Pedro de Castellfollit (siglo XI-XII) es un edificio de tipología románica lombarda construido en sillarejo calizo regular con un ábside semicircular decorado con arcuaciones ciegas y lesenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08059','monumento','El Castillo de Grevalosa','El Castillo de Grevalosa (siglo X) representa las ruinas consolidadas de una fortificación militar de frontera levantada en aparejo tosco y argamasa sobre un peñasco inaccesible de la comarca del Bages.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08059','iglesia','La Iglesia de San Miguel de Grevalosa','La Iglesia de San Miguel de Grevalosa (siglo XII) es un templo románico rural de planta basilical edificado con muros de mampostería caliza y losas de piedra calavera en su cubierta exterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08060','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08060','monumento','El Castillo de San Esteban','El Castillo de San Esteban (Castell de Riubregós) (siglo XI-XIV) es una imponente fortaleza del Condado de Cardona construida en sillería de arenisca que conserva varias torres cuadrangulares, un foso excavado en la roca y lienzos de muralla jalonados de saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08060','monumento','La Prioral de Santa María del Priorato','La Prioral de Santa María del Priorato (siglo XI) es una iglesia románica que perteneció a un monasterio benedictino, edificada en perfecto sillarejo calizo con planta de cruz latina, tres ábsides semicirculares y bóveda de cañón apuntada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08061','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08061','monumento','El Castillo de Castellgalí','El Castillo de Castellgalí (siglo X-XIV) son los restos de una fortificación señorial que controlaba el paso estratégico de los ríos Cardener y Llobregat, edificada en sillarejo de piedra caliza y arenisca sobre un cerro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08061','iglesia','La Iglesia de San Miguel de Castellgalí','La Iglesia de San Miguel de Castellgalí (siglo XVII) es un templo de traza gótica tardía arcaizante con reformas barrocas, edificado en mampostería de piedra gris con una portalada de sillería labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08062','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08062','iglesia','La Iglesia de San Andrés de Castellnou','La Iglesia de San Andrés de Castellnou (siglo XI) es una de las obras más homogéneas del románico lombardo de la zona, construida en sillarejo de piedra caliza con una torre campanario cuadrangular adosada y ábside con friso de arquillos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08062','monumento','La Torre dels Moros','La Torre dels Moros (siglo X-XI) es una torre de vigilancia militar de planta circular levantada con aparejo rústico calizo y argamasa de cal que formaba parte del sistema defensivo primitivo de la Cataluña central.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08063','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08063','monumento','El Castillo de Castellolí','El Castillo de Castellolí (siglo X) representa las ruinas de una fortaleza de la Marca de la Anoia alzada sobre un crestón calcáreo utilizando muros de mampostería basta y piedra conglomerada que conserva restos de una torre y la capilla de San Vicente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08063','iglesia','La Iglesia Vieja de San Vicente','La Iglesia Vieja de San Vicente (siglo XVIII) es un templo barroco en ruinas de proporciones monumentales, edificado en mampostería encintada y ladrillo visto con una fachada que todavía conserva su portalada clasicista de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08064','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08064','monumento','El Castillo de Castellterçol','El Castillo de Castellterçol (siglo XII-XIV) es un conjunto fortificado señorial que conserva una torre de homenaje de planta rectangular y un palacio gótico rodeados por una muralla defensiva hecha en sillería de piedra caliza y arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08064','iglesia','La Iglesia Parroquial de San Fructuoso','La Iglesia Parroquial de San Fructuoso (siglo XVII) es un edificio de tipología barroca clasicista construido en cantería caliza que destaca por su portalada esculpida y un esbelto campanario octogonal con remate de piedra labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08064','monumento','La Casa Natal de Enric Prat de la Riba','La Casa Natal de Enric Prat de la Riba (siglo XVII-XIX) es una gran casa solariega de la burguesía rural que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08065','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08065','monumento','El Castillo de la Marca','El Castillo de la Marca (Castellot) (siglo X-XII) son las ruinas de una fortaleza fronteriza colgada sobre un risco calizo del Penedès, levantada con aparejo de sillarejo rústico que conserva una torre de homenaje cilíndrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08065','iglesia','La Iglesia de San Miguel del Castillo','La Iglesia de San Miguel del Castillo (siglo XII) es una edificación románica de una sola nave construida con sillería irregular de piedra calcárea local que servía como capilla castrense del complejo militar adyacente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08066','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08066','monumento','El Castillo de Rosanes','El Castillo de Rosanes (siglo X-XII) representa las ruinas de la fortaleza que daba nombre al término señorial, edificada con gruesos paramentos de mampostería de pizarra y caliza sobre una colina escarpada del bajo Llobregat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08066','iglesia','El Antiguo Monasterio de Miralles','El Antiguo Monasterio de Miralles (siglo XIII-XV) conserva las estructuras de una cartuja gótica levantada con muros de tapial y sillería caliza en los arcos triunfales de su iglesia conventual.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08067','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08067','palacio','El Palacio de los Condes de Centelles','El Palacio de los Condes de Centelles (siglo XVI) es un imponente edificio renacentista de planta cuadrada y tipología palaciega italiana, levantado en sillería de piedra arenisca local con un patio central de dos pisos jalonado por columnas jónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08067','iglesia','La Iglesia de Santa Coloma de Centelles','La Iglesia de Santa Coloma de Centelles (siglo XVIII) es un gran templo barroco clasicista diseñado por el arquitecto Josep Morató, construido en cantería de la comarca con una fachada monumental y un campanario de torre octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08067','monumento','El Portal de Centelles','El Portal de Centelles (siglo XVII) constituye una infraestructura de acceso logístico a la villa amurallada preindustrial, edificado con un gran arco de medio punto','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90573','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90573','iglesia','La Iglesia de Sant Quirze de Pedret','La Iglesia de Sant Quirze de Pedret (siglos IX-X) es una joya capital del arte prerrománico y mozárabe situada en el término histórico, construida con sillarejo rústico calcáreo, arcos de herradura y tres ábsides que alojaban frescos románicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90573','monumento','El Pont de Pedret','El Pont de Pedret (siglo XIII) es un puente monumental gótico de cuatro arcos apuntados de diferentes luces que salva el río Llobregat, edificado en sillería regular de piedra caliza con perfil de lomo de asno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08266','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08266','monumento','El Castillo de Sant Marçal','El Castillo de Sant Marçal (siglo XII-XIX) es una fortaleza medieval reformada en estilo historicista ecléctico por el arquitecto Gaietà Buïgas, estructurada con fosos, muros almenados y torres mediante el uso de ladrillo visto y piedra labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08266','monumento','El Poblado Ibérico de Ca n''Oliver','El Poblado Ibérico de Ca n''Oliver (siglos VI-I a.C.) constituye un asentamiento arqueológico clave de la tribu de los layetanos que conserva defensas, fosos y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08266','iglesia','La Iglesia de Sant Iscle i Santa Victòria de les Feixes','La Iglesia de Sant Iscle i Santa Victòria de les Feixes (siglo XII) es una construcción de tipología románica rural edificada en sillarejo regular de arenisca con un ábside semicircular y reformas barrocas posteriores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08068','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08068','iglesia','La Iglesia de Sant Ponç de Corbera','La Iglesia de Sant Ponç de Corbera (siglo XI) es una de las obras cumbres del románico lombardo pleno en la comarca, edificada en perfecto sillarejo calizo con una nave única, cimborrio octogonal y decoración de arcuaciones ciegas y lesenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08068','monumento','Las Ruinas del Castillo de Cervelló','Las Ruinas del Castillo de Cervelló (siglo X-XIII) representan la base militar de la baronía de Cervelló alzada sobre un espolón de arenisca roja con potentes lienzos de muralla de mampostería basta y la capilla de Santa Maria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08069','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08069','iglesia','La Iglesia de Sant Corneli','La Iglesia de Sant Corneli (siglo XVI-XVIII) es un edificio religioso renacentista y barroco edificado en mampostería caliza de Montserrat con esquinales de sillería y una torre campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08069','palacio','El Casco Urbano y Casonas de Collbató','El Casco Urbano y Casonas de Collbató (siglos XVIIXIX) constituye un conjunto etnográfico serrano caracterizado por sus portales dovelados de sillería de piedra calavera y dependencias logísticas vinculadas a los arrieros de Montserrat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08070','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08070','iglesia','La Iglesia de Santa Maria de Collsuspina','La Iglesia de Santa Maria de Collsuspina (siglo XIIXVIII) presenta restos de su fábrica románica en los paramentos inferiores de sillarejo, modificada en estilo barroco rural con muros de mampostería de piedra gris.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08071','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08071','monumento','El Núcleo Histórico de los Negociantes de Copons','El Núcleo Histórico de los Negociantes de Copons (siglo XVIII) es un conjunto urbano preindustrial único, caracterizado por palacetes de comerciantes construidos con fachadas de sillería caliza, portales dovelados y patios porticados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08071','iglesia','La Iglesia de Santa Maria','La Iglesia de Santa Maria (siglo XVIII) es un edificio de tipología barroco-neoclásica levantado en cantería fina de la Anoia que destaca por su ábside poligonal y su retablo mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08072','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08072','monumento','El Casal de los Barones de Corbera','El Casal de los Barones de Corbera (siglo XVI) es una residencia nobiliaria de tipología gótico-renacentista construida con muros de sillería de arenisca roja de Garraf y ventanas geminadas labradas con modillones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08072','iglesia','La Iglesia de Santa Maria de Corbera de Dalt','La Iglesia de Santa Maria de Corbera de Dalt (siglo XIV-XVIII) es un templo gótico ampliado en el período barroco, levantado sobre los cimientos de la antigua fortaleza señorial en mampostería mixta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08073','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08073','monumento','El Castillo de Cornellà','El Castillo de Cornellà (siglo XIV-XV) es una fortaleza señorial de planta cuadrada estructurada en torno a un patio central con arquerías ojivales, edificada en sillería de piedra de Montjuïc y mampostería de cantos rodados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08073','monumento','El Palau Mercader','El Palau Mercader (siglo XIX) es un palacio residencial de estilo ecléctico historicista rodeado de jardines románticos, construido con muros portantes de ladrillo macizo, estucos decorativos y maderas nobles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08073','monumento','La Central de Bombeo de Aguas de Barcelona','La Central de Bombeo de Aguas de Barcelona (Can Boixeres) (año 1909) es un hito de la ingeniería hidráulica industrial modernista diseñado por Josep Amargós empleando naves de ladrillo visto rojo y grandes calderas de vapor de fundición.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08074','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08074','palacio','El Castillo de Cubelles o Palacio de los Marqueses de Alfarràs','El Castillo de Cubelles o Palacio de los Marqueses de Alfarràs (siglo XVII) es una edificación civil fortificada de planta rectangular erigida sobre el núcleo medieval en mampostería encintada y esquinales de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08074','iglesia','La Iglesia de Santa Maria de Cubelles','La Iglesia de Santa Maria de Cubelles (siglo XVIII) es un templo barroco clasicista de nave única con capillas laterales, levantado en cantería con una fachada sobria esgrafiada y un campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08075','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08075','iglesia','La Iglesia de Sant Esteve de Dosrius','La Iglesia de Sant Esteve de Dosrius (siglo XVI) es un templo de tipología gótica tardía edificado en cantería de granito que destaca por su ábside poligonal con contrafuertes exteriores y sus bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08075','iglesia','La Iglesia de Sant Esteve de Canyamars','La Iglesia de Sant Esteve de Canyamars (siglo X-XVI) es un edificio de origen románico reformado en el período gótico mediante paramentos de mampostería basta y piedra tallada en las ventanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08075','iglesia','El Santuario del Far','El Santuario del Far (siglo XVII) es un complejo religioso barroco edificado sobre una colina con sillería de piedra','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08075','monumento','El Pou de Glaç de Canyamars','El Pou de Glaç de Canyamars (siglo XVII-XVIII) constituye una infraestructura logística preindustrial subterránea de planta cilíndrica construida con muros gruesos de mampostería de piedra sin pulir y cúpula de media esfera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08076','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08076','iglesia','La Iglesia de Santa Eulàlia d''Esparreguera','La Iglesia de Santa Eulàlia d''Esparreguera (siglo XVIXVII) es un gran edificio de transición renacentista y barroca edificado en sillería caliza de Montserrat que cuenta con un campanario octogonal de más de sesenta metros de altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08076','iglesia','Las Ruinas de la Iglesia de Santa Maria del Puig','Las Ruinas de la Iglesia de Santa Maria del Puig (siglo XII) representan un templo románico de planta de cruz latina levantado en aparejo regular de piedra caliza con un ábside semicircular decorado con arcuaciones lombardas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08077','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08077','monumento','El Casco Antiguo y Can Cortada','El Casco Antiguo y Can Cortada (siglos XIV-XVIII) es un conjunto que conserva calles empedradas y masías señoriales fortificadas edificadas con muros de mampostería mixta y portones dovelados de piedra de Montjuïc.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08077','iglesia','La Iglesia de Santa Magdalena','La Iglesia de Santa Magdalena (siglo XI-XIX) presenta un origen románico muy reformado en estilo historicista con paramentos de mampostería encintada, ladrillo visto y una esbelta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08078','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08078','monumento','El Castillo de l''Espunyola','El Castillo de l''Espunyola (siglos XIII-XIV) es una tipología de casa fuerte señorial gótica construida en sillería caliza regular del Berguedà con una torre de planta rectangular y ventanas geminadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08078','iglesia','La Iglesia de Sants Metges','La Iglesia de Sants Metges (siglo XII) es una ermita románica rural levantada en sillarejo regular de piedra caliza que destaca por su ábside semicircular exento de decoración compleja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08078','iglesia','La Iglesia de Sant Climent del Cint','La Iglesia de Sant Climent del Cint (siglo XII) presenta una fábrica románica de montaña edificada en aparejo tosco calcáreo con bóveda de cañón apuntada y tejado de losas planas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08011','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08011','iglesia','El Monasterio de Santa Maria de l''Estany','El Monasterio de Santa Maria de l''Estany (siglos XIIXIV) es una de las obras cumbres del románico catalán, edificado en sillería regular caliza con un claustro','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08011','iglesia','La Iglesia del Monasterio de Santa Maria','La Iglesia del Monasterio de Santa Maria (siglo XII) es un templo de planta de cruz latina con tres ábsides semicirculares levantado en piedra labrada fina con un cimborrio octogonal sobre el crucero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08011','monumento','El Pont de la Mina','El Pont de la Mina (siglo XVIII) es una monumental infraestructura de ingeniería hidráulica preindustrial construida en piedra caliza para drenar el antiguo estanque de la villa mediante una galería subterránea de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08134','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08134','iglesia','La Iglesia de Sant Pau de Montmany','La Iglesia de Sant Pau de Montmany (siglo XII) representa las ruinas de un templo románico tardío edificado en sillarejo de piedra caliza y arenisca del Montseny con un ábside semicircular y bóveda de cañón colapsada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08134','monumento','El Castell de Montmany o dels Moros','El Castell de Montmany o dels Moros (siglo XI) son los restos de una fortificación militar de frontera alzada en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08134','monumento','La Torre de Telegrafía Óptica de Figaró','La Torre de Telegrafía Óptica de Figaró (año 1849) es una infraestructura militar y logística de planta cuadrada construida con muros de mampostería y ladrillo para la línea de comunicación civil de Madrid a la frontera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08080','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08080','iglesia','La Iglesia de Santa Cecilia de Fígols','La Iglesia de Santa Cecilia de Fígols (siglo XII) es una construcción de tipología románica de montaña levantada en sillarejo de piedra caliza gris del Berguedà con un ábside semicircular y una sobria portada de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08080','monumento','El Yacimiento Paleontológico de Fumanya','El Yacimiento Paleontológico de Fumanya (Cretácico Superior) constituye un hito arqueológico-geológico al aire libre con miles de icnitas de dinosaurio impresas sobre una pared vertical calcárea derivada de antiguas explotaciones de lignito a cielo abierto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90574','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90574','iglesia','La Iglesia de Sant Cebrià de Fogars','La Iglesia de Sant Cebrià de Fogars (siglo XVI-XVIII) es un edificio de origen medieval reformado en estilo barroco rural con muros de mampostería de granito y esquinales de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90574','ermita','La Ermita de la Mare de Déu de la Serra','La Ermita de la Mare de Déu de la Serra (siglo XII) es un pequeño templo románico edificado en sillarejo irregular que presenta una sola nave y un tejado de teja árabe sobre vigas de pino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08081','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08081','iglesia','La Iglesia de Sant Martí de Mosqueroles','La Iglesia de Sant Martí de Mosqueroles (siglo XVIXVIII) es un templo barroco edificado en mampostería basta de piedra granítica del Montseny que conserva un porche tradicional y un campanario de torre con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08081','ermita','La Ermita de Santa Magdalena de Mosqueroles','La Ermita de Santa Magdalena de Mosqueroles (siglo XI) presenta una fábrica de tipología románica lombarda construida en sillarejo con un ábside semicircular decorado con un friso de arcuaciones ciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08085','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08085','monumento','El Castillo de Font-rubí','El Castillo de Font-rubí (siglo X-XII) representa las ruinas de una fortaleza fronteriza de la Marca del Penedès alzada sobre una peña calcárea escarpada, conservando lienzos de muralla de mampostería basta y la base de una torre circular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08085','iglesia','La Iglesia de Sant Feliu de Font-rubí','La Iglesia de Sant Feliu de Font-rubí (siglo XII-XVIII) es un templo de origen románico transformado en época barroca con sillería de piedra caliza fina, situado al pie de los restos del castillo señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90575','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90575','iglesia','La Iglesia de Santa Maria de Gaià','La Iglesia de Santa Maria de Gaià (siglo XVII-XVIII) es un templo de tipología barroca clasicista edificado en cantería de piedra caliza con una nave única de grandes proporciones y capillas entre los contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90575','monumento','Las Ruinas del Castillo de Gaià','Las Ruinas del Castillo de Gaià (siglo X) constituyen los vestigios de una edificación defensiva de frontera construida con aparejo rústico calizo y argamasa sobre un montículo que controla el valle del río Llobregat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08087','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08087','monumento','El Castillo de Gallifa','El Castillo de Gallifa (siglo XI-XIV) es un conjunto fortificado medieval alzado sobre un risco que integra la iglesia románica de Santa Maria del Castell dentro de su recinto amurallado hecho en sillería caliza regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08087','iglesia','La Iglesia de Sant Pere de Gallifa','La Iglesia de Sant Pere de Gallifa (siglo XI) es una obra maestra del románico lombardo, edificada en sillarejo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08087','ermita','La Ermita de la Mare de Déu del Grau','La Ermita de la Mare de Déu del Grau (siglo XII) es un templo románico rural de una sola nave con ábside semicircular, construido en mampuesto irregular con esquinales de sillería de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08088','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08088','monumento','La Villa Romana de Can Terrers','La Villa Romana de Can Terrers (siglo I a.C.-IV d.C.) constituye un complejo arqueológico de gran relevancia que conserva las estructuras de los baños públicos, el atrium y estancias edificadas en opus caementicium y piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08088','iglesia','La Iglesia de la Doma','La Iglesia de la Doma (siglos XIV-XVI) es un edificio de transición gótica con un retablo mayor gótico de la Virgen del Rosario, levantado en sillería de piedra arenisca con un cementerio histórico adosado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08088','monumento','El Conjunto Residencial Modernista','El Conjunto Residencial Modernista (Manzana Raspall) (siglo XX) agrupa palacetes burgueses diseñados por el arquitecto Manuel Joaquim Raspall mediante el uso de estucos esgrafiados, ladrillo visto, cerámica y forja artística.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08088','monumento','El Refugio Antiaéreo de la Estación','El Refugio Antiaéreo de la Estación (año 1938) es un hito de ingeniería logística y militar excavado en el subsuelo durante la contienda civil, reforzado con galerías de ladrillo macizo y hormigón armado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08089','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08089','monumento','Las Minas Prehistóricas de Gavà','Las Minas Prehistóricas de Gavà (Neolítico, IV milenio a.C.) constituyen el complejo minero en galería más','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08089','monumento','El Castillo de Eramprunyà','El Castillo de Eramprunyà (siglo X-XIV) representa las ruinas de una fortaleza defensiva medieval alzada sobre un precipicio de arenisca rojiza de Garraf, conservando la capilla románica de Sant Miquel y lienzos de muralla de mampostería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08089','iglesia','La Iglesia de Sant Pere de Gavà','La Iglesia de Sant Pere de Gavà (siglo XX) es un templo de dimensiones monumentales de estilo historicista neorrománico, edificado en ladrillo prensado y piedra caliza con una gran fachada flanqueada por dos torres campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08091','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08091','monumento','El Castillo de Gelida','El Castillo de Gelida (siglo X-XV) es un conjunto fortificado alzado sobre un espolón rocoso que domina el valle del Penedès, edificado con muros de mampostería caliza y arenisca que integran la antigua iglesia románica de Sant Pere.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08091','iglesia','La Iglesia de Sant Pere del Castell','La Iglesia de Sant Pere del Castell (siglo XII-XVIII) presenta un origen románico modificado con elementos barrocos y un campanario exento, construida en sillería de piedra calcárea de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08091','monumento','El Funicular de Gelida','El Funicular de Gelida (año 1924) es una infraestructura logística de transporte preindustrial e industrial que conecta la estación de ferrocarril con el núcleo urbano utilizando vehículos de madera noble y raíles de acero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08092','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08092','iglesia','La Iglesia de Santa Eulàlia de Gironella','La Iglesia de Santa Eulàlia de Gironella (siglo XIV) es un templo de tipología gótica meridional catalana edificado en sillería regular caliza con una amplia nave única y capillas laterales absidiales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08092','monumento','El Castillo de Gironella','El Castillo de Gironella (siglo XII-XIV) conserva los restos de la muralla perimetral y una gran torre de defensa de planta rectangular construida en aparejo de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08092','monumento','La Torre del Amo de Viladomiu Nou','La Torre del Amo de Viladomiu Nou (año 1902) es un palacete residencial modernista situado en el núcleo de la colonia textil, construido por el arquitecto Valentí Carulla empleando fachadas de piedra labrada, estucos y carpinterías de roble noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08092','monumento','El Puente Viejo de Gironella','El Puente Viejo de Gironella (siglo XIV) es una infraestructura logística de origen gótico con arcos apuntados levantada en sillería de piedra caliza para salvar el cauce fluvial y conectar los barrios tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08095','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08095','monumento','El Castillo de Granera','El Castillo de Granera (siglo X-XIV) representa una fortaleza defensiva alzada de forma estratégica sobre una peña rocosa, edificada con potentes paramentos de sillería irregular caliza y una torre de planta poligonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08095','iglesia','La Iglesia de Sant Martí de Granera','La Iglesia de Sant Martí de Granera (siglo XII-XVII) presenta restos de su fábrica románica en los muros','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08096','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08096','monumento','La Porxada de Granollers','La Porxada de Granollers (siglo XVI) es un monumento renacentista y antiguo mercado de grano preindustrial concebido por Bartomeu Brufalt, sustentado por quince columnas de sillería de piedra caliza fina de Montjuïc con techumbre de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08096','iglesia','La Iglesia de Sant Esteve','La Iglesia de Sant Esteve (siglo XV-XX) conserva la gran torre del campanario gótico de sillería regular de arenisca con ventanas apuntadas, integrada en el nuevo templo historicista levantado tras la contienda civil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08096','monumento','Las Murallas de Granollers','Las Murallas de Granollers (siglo XIV) constituyen los restos del recinto fortificado medieval de la villa, conservando lienzos de mampostería mixta y torres defensivas de planta circular reformadas en época moderna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08096','monumento','El Refugio Antiaéreo de la Plaza de la Porxada','El Refugio Antiaéreo de la Plaza de la Porxada (año 1938) es un hito de la ingeniería militar subterránea construido con galerías de hormigón armado y ladrillo macizo para salvaguardar a la población civil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08097','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08097','iglesia','La Iglesia de Sant Vicenç de Gualba','La Iglesia de Sant Vicenç de Gualba (siglos XI-XVI) es un edificio de traza románica con ampliaciones góticas, edificado con paramentos de mampostería de granito y esquinales de sillería caliza del macizo del Montseny.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08097','monumento','El Conjunto de Can Cambó','El Conjunto de Can Cambó (siglo XVI-XVIII) es una masía señorial de interés etnográfico que conserva portones dovelados de sillería caliza y ventanas góticas con dinteles esculpidos en piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08099','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08099','iglesia','El Monasterio de Sant Llorenç prop Bagà','El Monasterio de Sant Llorenç prop Bagà (siglo XI-XII) es un antiguo cenobio benedictino edificado en sillería regular caliza que destaca por su iglesia románica de planta basilical estructurada en dos niveles superpuestos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08099','iglesia','La Iglesia de Sant Genís de Gavarrós','La Iglesia de Sant Genís de Gavarrós (siglo XII) es una construcción románica aislada en el valle, levantada en sillarejo tosco de piedra caliza pirenaica con un ábside semicircular y tejado de losas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08099','monumento','El Castillo de Guardiola','El Castillo de Guardiola (siglo XII) representa las ruinas consolidadas de una torre de vigilancia y fortificación que controlaba el paso del río Llobregat, construida con muros de mampostería y argamasa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08100','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08100','iglesia','La Iglesia de Sant Julià de Sassorba','La Iglesia de Sant Julià de Sassorba (siglo XI-XVIII) conserva una esbelta torre campanario románica con ventanas geminadas y decoración lombarda de ladrillo, integrada en una nave barroca de sillería de la Plana de Vic.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08100','iglesia','La Iglesia de Sant Christopher de Vespella','La Iglesia de Sant Christopher de Vespella (siglo XII) es un templo románico rural de una sola nave con ábside','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08100','monumento','Las Ruinas del Castillo de Gurb','Las Ruinas del Castillo de Gurb (siglo X) constituyen los restos arqueológicos de una fortaleza de la Marca Hispánica emplazada sobre un cerro conoide calcáreo con basamentos de piedra basta sin argamasa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08100','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Gisclareny La Granada Nombre en castellano Gisclareny La Granada Pob...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08101','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08101','monumento','La Atalaya de l''Hospitalet','La Atalaya de l''Hospitalet (Torre Barrina) (siglo XVI) es una estructura defensiva de planta cuadrangular edificada en mampostería de ladrillo y cantos rodados para alertar sobre incursiones mercenarias desde el río Llobregat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08101','iglesia','La Iglesia de Santa Eulàlia de Provençana','La Iglesia de Santa Eulàlia de Provençana (siglo XII) es un templo de tipología románica tardía levantado en sillería de piedra caliza con una cabecera de triple ábside y una portada restaurada de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08101','monumento','La Casa de la Vila','La Casa de la Vila (año 1894) es un palacio civil de corte ecléctico e historicista diseñado por el arquitecto Fransesc de Paula del Villar utilizando ladrillo macizo prensado, estucos y ménsulas de piedra tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08102','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08102','iglesia','La Basílica de Santa Maria de Igualada','La Basílica de Santa Maria de Igualada (siglo XVII) es una monumental obra de transición renacentista y barroca construida en sillería regular caliza con una gran nave única y un impresionante retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08102','monumento','El Barrio de las Curtidurías','El Barrio de las Curtidurías (Barri del Rec) (siglos XVIII-XIX) constituye el conjunto preindustrial e industrial de curtido de pieles más importante de Cataluña, caracterizado por sus fábricas de mampostería y canales hidráulicos de caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08102','monumento','Las Murallas de Igualada','Las Murallas de Igualada (Portal d''en Vives y Portal de la Font) (siglo XV) son los restos del recinto fortificado gótico de la villa, levantados con paños de mampostería encintada y arcos dovelados de sillería de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08102','monumento','El Asilo de Santo Cristo','El Asilo de Santo Cristo (año 1931) es una joya modernista y gaudiniana proyectada por Joan Rubió i Bellver empleando muros de piedra basta sin pulir, arcos parabólicos de ladrillo visto y cubiertas de azulejo polícromo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08103','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08103','monumento','El Castillo de Jorba','El Castillo de Jorba (siglo X-XV) representa las ruinas consolidadas de una imponente fortaleza de la baronía de Jorba, alzada en un cerro con sillería caliza irregular y potentes muros defensivos de planta circular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08103','iglesia','La Iglesia Parroquial de Sant Pere','La Iglesia Parroquial de Sant Pere (siglo XVI) es un templo de tipología gótica tardía edificado en cantería fina de la Alta Anoia con una portada de arquivoltas lisas y bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08103','monumento','El Hospital de Peregrinos de Jorba','El Hospital de Peregrinos de Jorba (siglo XIV-XV) es una infraestructura logística medieval vinculada al Camino de Santiago y las rutas de la Corona, levantada con muros portantes de mampostería y ventanas góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08104','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08104','iglesia','La Iglesia de Santa Maria de la Llacuna','La Iglesia de Santa Maria de la Llacuna (siglo XVII) es un templo gótico-renacentista tardío edificado en sillería caliza que destaca por su ábside poligonal, capillas entre contrafuertes y portalada con hornacina barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08104','monumento','Las Murallas y Portales de la Llacuna','Las Murallas y Portales de la Llacuna (Portal d''en Garreta, Portal de Bover) (siglo XIV) forman parte del conjunto urbano amurallado preindustrial, conservando arcos apuntados hechos con bloques de sillería caliza pulida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08104','monumento','El Castillo de Vilademàger','El Castillo de Vilademàger (siglo X-XII) son las ruinas de una gran fortificación señorial situada sobre un crestón escarpado, edificada con aparejo regular y mampuesto que conserva la iglesia románica de Sant Pere.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90576','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90576','iglesia','La Iglesia de Sant Julià de Lliçà d''Amunt','La Iglesia de Sant Julià de Lliçà d''Amunt (siglos XIXVII) es un edificio de origen románico lombardo ampliado en el barroco, levantado en sillería arenisca con un campanario defensivo y arcuaciones ciegas en el ábside.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90576','monumento','La Masía de Ca l''Amell','La Masía de Ca l''Amell (siglo XVI-XVIII) es un conjunto etnográfico de grandes dimensiones que conserva portones de medio punto de sillería y ventanas con dinteles labrados en piedra caliza fina del Vallès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08108','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08108','iglesia','La Iglesia de Sant Cristófol','La Iglesia de Sant Cristófol (siglo XVI-XVIII) es un templo de traza barroca rural con una fachada sencilla y esquinales de sillería arenisca, edificado sobre la base de una antigua capilla gótica medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08106','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08106','monumento','El Castell Nou de Llinars','El Castell Nou de Llinars (siglo XVI) es un imponente palacio fortificado renacentista de planta cuadrada mandado construir por la familia Corbera-Santcliment utilizando perfecta sillería de piedra granítica y arenisca local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08106','monumento','El Castell Vell o de Far','El Castell Vell o de Far (siglo XII-XIV) representa las ruinas arqueológicas de un enclave militar medieval rodeado de fosos excavados en el granito, del cual restan basamentos de gruesos muros de piedra basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08106','iglesia','La Iglesia de San Christopher de Collsabadell','La Iglesia de San Christopher de Collsabadell (siglo XII) es una construcción de tipología románica rural edificada en sillarejo regular calizo con un ábside semicircular decorado con un friso de dientes de sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90577','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90577','iglesia','El Monasterio de Santa Maria de Lluçà','El Monasterio de Santa Maria de Lluçà (siglos XII-XIV) es un conjunto monástico agustiniano medieval edificado en sillería de piedra caliza que conserva un claustro románico de reducidas dimensiones con capiteles esculpidos con aves y motivos vegetales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90577','iglesia','La Iglesia de Santa Maria','La Iglesia de Santa Maria (siglo XII) es un templo de planta de cruz latina levantado en piedra labrada fina con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90577','monumento','El Castillo de Lluçà','El Castillo de Lluçà (siglo X-XII) representa las ruinas de una fortificación de la frontera del condado de Besalú situada sobre una peña cónica, edificada con sillarejo tosco que conserva la iglesia redonda románica de Sant Vicenç.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08111','iglesia','Iglesia de San Vicente de Malla','Templo de origen románico del siglo XI profundamente transformado en época barroca que conserva de su fábrica primitiva el ábside semicircular decorado con arquillos ciegos de estilo lombardo y un imponente campanario de torre de planta cuadrada con ventanas geminadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08111','monumento','Yacimiento Arqueológico de El Clascar','Asentamiento de época ibérica y romana tardía donde las excavaciones han sacado a la luz muros de contención de mampostería seca, silos de almacenaje de grano y abundantes fragmentos de cerámica terra sigillata que atestiguan el temprano poblamiento de la plana de Vic.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08111','monumento','Masía de El Clascar','Gran explotación agrícola tradicional catalana construida a partir del siglo XVII con aparejo de mampostería basta y sillares de arenisca en los vanos, la cual integra en su estructura restos de una antigua torre de defensa medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08013','iglesia','Iglesia de Santa María','Templo de base románica reconstruido en estilo barroco en el siglo XVIII y posteriormente restaurado tras la Guerra Civil, el cual destaca por su claustro gótico del siglo XV con capiteles historiados tallados en piedra caliza y su monumental ábside exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08013','monumento','Museo del Ter e Instalaciones de Can Sanglas','Antiguo complejo hilandero decimonónico que constituye una muestra primordial de la arqueología industrial catalana al conservar la turbina Fontaine original, el canal de derivación de aguas del río Ter y las naves de ladrillo visto dispuestas para el hilado de algodón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08013','ermita','Ermita de San Jaime de Vilamontá','Pequeño santuario rural románico del siglo XII edificado con aparejo de sillería irregular que presenta una sola nave con bóveda de cañón apuntada, ábside semicircular orientado al este y una sencilla espadaña de un solo vano sobre el muro occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08013','monumento','Plaza de Fra Bernardí','Espacio público porticado de traza ochocentista configurado por edificios de fachadas clasicistas y modernistas que exhiben balconadas de hierro forjado, balaustradas de piedra y ornamentación de esgrafiados geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08113','iglesia','Basílica de Santa María de la Aurora (La Seu)','Magna colegiata gótica proyectada en el siglo XIV por el arquitecto Berenguer de Montagut que destaca por su imponente nave única de gran anchura, su corona de siete ábsides poligonales con arbotantes calados y un soberbio frente de vidrieras góticas que inundan de luz el espacio interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08113','monumento','Cueva de San Ignacio (Cova de Sant Ignasi)','Conjunto monumental barroco edificado sobre la balma natural donde San Ignacio de Loyola redactó sus Ejercicios Espirituales, integrado por una fastuosa iglesia del siglo XVIII con fachada de sillería labrada y un colegio jesuita contiguo de decoración ecléctica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08113','monumento','Puente Viejo (Pont Vell)','Viaducto de origen romano reconstruido fielmente en el siglo XIV mediante ocho arcos de medio punto sobre el cauce del río Cardener, ejecutado en sillería de piedra arenisca local con tajamares apuntados para resistir las avenidas fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08113','monumento','Calle del Balç','Vía urbana medieval de trazado subterráneo y cubierto mediante arcadas y viguerías de madera que conserva intacta la atmósfera del siglo XIV con sus muros de mampostería rústica, portales adintelados y pavimentación de losas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08113','monumento','Casino de Manresa','Edificio modernista obra del arquitecto Ignasi Oms i Ponsa construido a principios del siglo XX que funciona como centro cultural, caracterizado por sus tres fachadas exentas con rica ornamentación escultórica, vitrales polícromos y perfiles sinuosos de inspiración floral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08242','monumento','Núcleos de población de Marganell','El término municipal incluye los siguientes núcleos de población: Santa Cecília de Montserrat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08242','iglesia','Monasterio de San Benito de Montserrat','Abadía benedictina femenina emplazada en la falda de la montaña que fusiona naves contemporáneas con restos medievales y una notable producción artística interior de orfebrería y pintura sacra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08242','iglesia','Iglesia de San Vicente de Marganell','Templo parroquial románico del siglo XII edificado en sillería regular que consta de una nave única cubierta por bóveda de cañón, ábside semicircular con decoración de arcuaciones lombardas y una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08242','ermita','Ermita de Santa Cecília de Montserrat','Monasterio románico del siglo XI situado en su término municipal que presenta tres naves longitudinales rematadas por tres ábsides semicirculares perfectos con decoración exterior lombarda de frisos y lesenas, ejecutado enteramente en sillarejo de piedra calcárea de la propia montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','monumento','Puente del Diablo (Pont del Diable)','Monumental infraestructura de origen romano construida en la Vía Augusta en el año 10 a.C. y reconstruida en el gótico tardío que cruza el río Llobregat mediante un colosal arco apuntado central coronado por un arco de descarga menor, conservando en su estribo oriental un arco de triunfo romano original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','monumento','Enrejado de la Torre de las Horas','Torre defensiva medieval reconvertida en reloj público durante el siglo XVII que muestra muros de sillería granítica y un remate superior con armazón de forja barroca para albergar las campanas de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','iglesia','Santuario de Santa María de Montserrat de Les Bòbiles','Iglesia paleocristiana y visigótica datada entre los siglos VI y VII de la que se conservan los cimientos de su planta cruciforme, fragmentos de pavimentación polícroma y restos de una necrópolis de tumbas de cista excavadas en el terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','monumento','L''Enrajolada (Museo Santacana)','Antigua casa señorial del siglo XIX reformada para albergar una de las colecciones de cerámica más completas de Cataluña, destacando sus estancias revestidas con azulejos de los siglos XIV al XIX procedentes de alfares de Manises, Barcelona y Talavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','iglesia','Iglesia de San Joaquín','Templo parroquial de mediados del siglo XX edificado con un lenguaje racionalista que emplea muros portantes de ladrillo visto, una nave diáfana con cubiertas aligeradas y un esbelto campanario exento de líneas puras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','monumento','Masía de Can Carrencà','Gran casa solariega de origen medieval restaurada en los siglos XVIII y XIX que cuenta con portalada de medio punto con dovelas de arenisca, un gran patio de armas central y dependencias auxiliares destinadas a la producción vinícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08118','iglesia','Iglesia de San Pedro','Templo parroquial de estilo neoclásico construido en el siglo XIX que destaca por su monumental fachada flanqueada por pilastras, un gran frontón triangular','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08118','monumento','Casa de la Villa','Edificio consistorial modernista proyectado por el arquitecto Bonaventura Bassegoda i Amigó en 1901 que exhibe un balcón presidencial sostenido por ménsulas esculpidas, ventanales de arcos rebajados y una profusa decoración exterior a base de esgrafiados florales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08118','monumento','Museo Municipal Náutico','Centro cultural ubicado en un edificio modernista que custodia una valiosa colección de cartografía histórica, instrumental de navegación del siglo XIX y exvotos marineros que reflejan el pasado astillero de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08118','monumento','Casa Benéfica','Complejo asistencial de estética modernista inaugurado en 1901 que presenta pabellones de ladrillo visto combinados con mampostería regular, amplios ventanales apuntados de inspiración gótica y detalles de cerámica polícroma en las cornisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08119','monumento','Núcleos de población de Masquefa','El término municipal incluye los siguientes núcleos de población: La Beguda Alta, Can Parellada, El Maset y Can Valls.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08119','iglesia','Iglesia de San Pedro de Masquefa (Cementerio Viejo)','Templo románico de finales del siglo XII edificado en sillería caliza regular que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular decorado con arcuaciones ciegas y una robusta torre-campanario de planta cuadrangular añadida en época gótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08119','monumento','Fábrica Rogelio Rojo','Antiguo complejo industrial metalúrgico fundado en 1922 que representa un hito de la arquitectura del hierro y el ladrillo visto en la comarca de Anoia, caracterizado por sus amplias naves diáfanas con cubiertas de dientes de sierra para optimizar la iluminación natural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08119','iglesia','Iglesia Parroquial de San Pedro (Núcleo Urbano)','Edificio religioso tardobarroco finalizado a principios del siglo XX que muestra una sobria fachada de mampostería enfoscada, un portal adintelado moldurado y un campanario de torre octogonal que corona el perfil urbano de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08120','iglesia','Iglesia de San Juan de Matadepera','Templo parroquial levantado a principios del siglo XX sobre una base neorrománica que cuenta con una nave longitudinal, una fachada principal con rosetón moldurado y un campanario exento cuadrangular rematado por una estructura piramidal de hierro forjado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08120','iglesia','Monasterio de Sant Llorenç del Munt','Abadía románica del siglo XI situada en la cumbre de la Mola dentro de su término municipal que constituye un ejemplo excepcional de arquitectura religiosa lombarda con su planta de cruz latina, tres naves cubiertas por bóvedas de cañón y un cimborrio octogonal alzado sobre trompas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08120','monumento','Masía de Can Torras','Gran explotación agrícola tradicional documentada desde el siglo XIV que presenta muros de mampostería basta con sillares de piedra arenisca roja en los ángulos, un gran portal dovelado de medio punto y ventanas con dinteles góticos esculpidos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08121','monumento','Núcleos de población de Mataró','El término municipal incluye los siguientes núcleos de población: Mata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08121','iglesia','Basílica de Santa María de Mataró','Monumental templo edificado entre los siglos XVII y XVIII que fusiona elementos barrocos y neoclásicos, albergando en su interior la fastuosa Capilla de los Dolores que está considerada una de las obras','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08121','monumento','Villa Romana de Torre Llauder','Yacimiento arqueológico del siglo I a.C. musealizado de primer orden que conserva las estancias residenciales de una gran explotación agrícola imperial con espectaculares pavimentos de mosaico polícromo de opus tessellatum y las estructuras de sus termas privadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08121','monumento','Nave Gaudí (Kilómetro Cero de Antoni Gaudí)','Antigua nave de blanqueo de algodón de la Sociedad Cooperativa Obrera Mataronense construida en 1883 que destaca mundialmente por ser la primera obra proyectada por Antoni Gaudí, donde empleó por primera vez trece arcos parabólicos de madera ensamblada con pernos metálicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08121','monumento','Casa Coll i Regàs','Residencia señorial modernista diseñada por el arquitecto Josep Puig i Cadafalch en 1898 que exhibe una fachada ricamente ornamentada con esculturas de Eusebi Arnau, esgrafiados platerescos y una audaz tribuna de piedra caliza calada que corona la entrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08121','monumento','Ayuntamiento de Mataró','Palacio municipal de origen medieval reformado en el siglo XVII por Jordi filenames y posteriormente en el XIX por Miquel Garriga i Roca, quien diseñó la actual fachada neoclásica con grandes pilastras jónicas, frontón superior y un patio interior de arcadas góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08122','monumento','Núcleos de población de Mediona','El término municipal incluye los siguientes núcleos de población: San Juan de Mediona, Santa María de Mediona, Cases Noves de Can Pardo y El Marquesat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08122','monumento','Castillo de Mediona','Fortaleza medieval originaria del siglo X emplazada sobre un risco estratégico que conserva su torre del homenaje cilíndrica de mampostería regular, tramos de cortina defensiva almenada y la capilla románica de Santa María con ábside semicircular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08122','iglesia','Iglesia de San Juan de Conilles','Pequeño templo románico del siglo XII que presenta una sola nave cubierta por bóveda de cañón apuntada, ábside semicircular decorado exteriormente con un friso de dientes de sierra y una espadaña de dos vanos sobre la fachada de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08122','monumento','Masía de Can Verstraeten','Gran complejo agrícola e industrial del siglo XIX integrado por una vivienda residencial de estética ecléctica con galerías porticadas, un frondoso jardín romántico y dependencias anexas destinadas a la crianza vinícola tradicional del Penedès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90578','iglesia','Iglesia de Santa María','Monumental templo barroco construido entre los siglos XVII y XVIII que destaca por su imponente fachada clasicista de sillería caliza, un campanario octogonal de gran envergadura y un majestuoso retablo mayor de madera tallada y dorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90578','monumento','Cuevas del Toll (Coves del Toll)','Complejo kárstico y yacimiento arqueológico prehistórico de relevancia europea que ha proporcionado una de las colecciones más ricas de fauna del Cuaternario y restos humanos del Paleolítico y Neolítico medio, musealizados en el casco urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90578','monumento','Casa Natal de Rafael Casanova','Palacio urbano del siglo XVI con reformas barrocas que presenta una fachada con ventanas góticas geminadas, portadas doveladas de medio','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90578','iglesia','Monasterio de San Pedro de la Nou','Antiguo cenobio agustiniano de origen románico del que subsiste su austera iglesia de nave única con bóveda de cañón y restos de muros perimetrales integrados en dependencias agrícolas de mampostería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08123','palacio','Palacio de Requesens','Residencia señorial de origen gótico construida en el siglo XV y reformada en centurias posteriores que destaca por su patio de armas central con arcadas rebajadas, ventanas geminadas de tracería calada y amplias estancias con techumbres de viguería noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08123','monumento','Castillo de Castellciuró','Ruinas de una fortaleza medieval datada en el siglo X situadas en la sierra de Collserola que conservan una imponente torre de planta cuadrangular ejecutada con aparejo de espiga (opus spicatum) y tramos de muros de defensa perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08123','monumento','Fábrica Can Terris','Chimenea y restos arquitectónicos de una antigua tejería del siglo XIX que constituye un exponente de la primera industrialización del Baix Llobregat gracias a su esbelta estructura helicoidal de ladrillo macizo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08123','ermita','Ermita de San Pedro de Romaní','Pequeño santuario románico del siglo XI edificado en piedra caliza local que muestra una planta de nave única con ábside semicircular liso y una robusta torre-campanario de base cuadrada adosada al muro norte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08124','iglesia','Iglesia de San Vicente de Mollet','Templo parroquial reedificado tras la Guerra Civil en estilo neorrománico que conserva de su fábrica anterior una base del campanario gótico del siglo XV construida en cantería regular con ventanales apuntados moldurados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08124','monumento','Masía de Can Borrell','Gran heredad rural documentada desde el siglo XIV que exhibe una estructura tradicional de tres cuerpos con tejado a dos aguas, un portal de arco de medio punto con grandes dovelas de arenisca y un reloj de sol esgrafiado en la fachada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08124','monumento','Menhir de Mollet','Monumento megalítico del Neolítico final descubierto en 2009 que está considerado uno de los menhires más grandes de la península ibérica al superar los cinco metros de altura, tallado en un bloque de arcosa con grabados serpentiformes y relieves antropomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08124','monumento','Can Mulà','Antiguo palacete residencial de la familia textil Rosés construido en el siglo XIX dentro de un frondoso parque urbano que muestra una fachada ecléctica con balaustradas románticas, cornisas molduradas y grandes ventanales de aire palaciego.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08128','iglesia','Iglesia de San Feliu de Monistrol','Templo de origen románico transformado íntegramente en el siglo XVIII bajo los','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08128','monumento','Dolmen de Plan de la Crisis','Sepulcro megalítico de la Edad del Bronce que conserva su cámara funeraria de planta rectangular delimitada por grandes losas de piedra caliza hincadas en el terreno y restos del túmulo perimetral de tierra y guijarros que lo cubría primigeniamente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08128','monumento','Masía de Mura','Gran explotación agropecuaria tradicional documentada desde el siglo XII que presenta una planta fortificada con muros de sillería basta, un portal de arco de medio punto adovela de gran envergadura y ventanas con alféizares moldurados de época renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08127','iglesia','Monasterio de Santa María de Montserrat','Magno santuario benedictino emplazado en el macizo rocoso cuyos orígenes se remontan al siglo XI que destaca por su basílica renacentista con reformas decimonónicas, su fachada monumental esculpida por Agapit Vallmitjana y el imponente claustro gótico proyectado por el arquitecto barroco Jaume Busquets.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08127','monumento','Puente de la Bauma','Viaducto gótico del siglo XIV construido en cantería regular para salvar el cauce del río Llobregat mediante cuatro arcadas apuntadas de luces desiguales sustentadas sobre pilares provistos de potentes tajamares para resistir las grandes avenidas fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08127','palacio','Palacio del Prior','Residencia fortificada tardogótica del siglo XVI construida en sillería caliza que muestra un patio de armas interior con galerías porticadas de arcos rebajados, ventanas geminadas de tracería flamígera y portaladas doveladas de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08127','iglesia','Iglesia de San Antolín','Pequeña capilla románica del siglo XII edificada con aparejo regular de piedra caliza de la montaña que consta de una sola nave con bóveda de cañón, un ábside semicircular liso y una espadaña de un vano centrada en el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08125','iglesia','Iglesia de Santa Engracia','Templo parroquial reedificado a mediados del siglo XX en un estilo historicista que incorpora de su fábrica barroca original los cimientos de la torrecampanario y una portada de cantería moldurada con hornacina superior flanqueada por volutas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08125','monumento','Yacimiento Arqueológico de Les Maleses','Asentamiento layetano de la Edad del Hierro situado en la cordillera de Marina que conserva las plantas de viviendas rectangulares de mampostería seca, hogares centrales para la metalurgia y calles pavimentadas que atestiguan la ocupación ibérica del siglo IV a.C.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08125','monumento','Casa de las Aguas (Casa de les Aigües)','Complejo modernista de bombeo de agua diseñado por el arquitecto Antoni Rovira i Trias en 1878 que constituye una joya de la arqueología industrial catalana con sus naves de ladrillo visto, chimenea helicoidal y espectaculares salas de máquinas de vapor decimonónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08130','iglesia','Iglesia de San Martín de Montclar','Templo románico del siglo XII construido con un aparejo regular de sillares calizos que consta de una nave única con bóveda de cañón apuntada, un ábside semicircular orientado al este con cornisa','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08130','monumento','Castillo de Montclar','Mansión señorial fortificada del siglo XVII levantada sobre los restos de la fortaleza medieval original que presenta muros de cantería con aspilleras de defensa, un gran portal dovelado de medio punto y ventanas rectangulares de piedra moldurada conopial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08130','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Monistrol de Calders Monistrol...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08131','monumento','Castillo de Montesquiu','Caserón fortificado de origen medieval reformado profundamente en el siglo XVII y a principios del XX que destaca por su imponente torre del homenaje de planta cuadrada, sus matacanes de mampostería regular de piedra arenisca y sus interiores nobles con techumbres de viguería y colecciones de armaduras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08131','ermita','Ermita de San Roque','Pequeño oratorio de planta de cajón construido en el siglo XVIII que presenta una arquitectura popular muy sobria con muros de mampostería basta, un portal adintelado de piedra local y una sencilla espadaña de un solo vano que remata el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08126','iglesia','Iglesia de San Juan de Montgat','Templo parroquial finalizado a principios del siglo XIX que muestra una fachada de líneas neoclásicas sencillas con un frontón triangular, muros exteriores enlucidos con sillares de granito en los ángulos y un campanario de torre cuadrangular con vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08126','monumento','Túnel de Montgat','Infraestructura ferroviaria inaugurada en 1848 para la primera línea de tren de la península ibérica (Barcelona-Mataró) que constituye un hito de la ingeniería civil decimonónica al estar excavado directamente sobre el promontorio rocoso mediante arcos de descarga de ladrillo macizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08126','monumento','Torre de Ca l''Alzina','Torre de defensa costera del siglo XVI de planta circular edificada con aparejo de mampostería y mortero de cal que conserva algunas saeteras y restos de los canecillos que sustentaban el desaparecido matacán superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08132','monumento','Núcleos de población de Montmajor','El término municipal incluye los siguientes núcleos de población: Correà, Gargallà y Sorba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08132','iglesia','Iglesia de Santa María de Sorba','Templo parroquial de origen prerrománico reconstruido en el siglo XVII que destaca por albergar el Martirium de San Eudaldo, una estructura paleocristiana del siglo VI con planta absidial y restos de pavimentación arqueológica de gran valor litúrgico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08132','iglesia','Iglesia de San Saturnino de Correà','Edificio religioso románico del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular decorado exteriormente con motivos lombardos y un esbelto campanario de torre exento erigido en centurias posteriores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08132','monumento','Castillo de Montmajor','Restos de una fortaleza medieval del siglo XI emplazada sobre una mole rocosa de los que subsisten tramos dispersos de la muralla perimetral y la base de una torre cilíndrica de mampostería basta cementada con cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08133','monumento','Núcleos de población de Montmaneu','El término municipal incluye los siguientes núcleos de población: La Panadella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08133','iglesia','Iglesia de Santa María de Montmaneu','Templo parroquial de estilo gótico tardío construido en el siglo XIV que presenta una amplia nave única con capillas laterales entre los contrafuertes, una portada con arquivoltas apuntadas molduradas y una recia torre-campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08133','monumento','Torre de la Panadella','Antigua torre de vigía y defensa del siglo de planta circular erigida en sillería regular que servía para el control del estratégico paso de montaña entre la cuenca de Ódena y la meseta de la Segarra durante los conflictos bélicos medievales y carlistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08133','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Montesquiu Montesquíu 1059 Mon...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08135','iglesia','Iglesia de Santa María de Montmeló','Templo de base románica del siglo XI reformado en épocas posteriores que conserva en su ábside semicircular un excepcional conjunto de pinturas murales del románico temprano que representan a la Maiestas Domini y el colegio apostólico, ejecutadas con la técnica del fresco sobre mortero de cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08135','monumento','Yacimiento Arqueológico de Mons Observans','Asentamiento romano de época republicana tardía (siglo II','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08137','iglesia','Iglesia de San Julián de Montseny','Templo de origen románico profundamente reformado en el siglo XVIII que exhibe muros de mampostería rústica con piedra caliza del macizo del Montseny, una fachada con porche cubierto','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08137','ermita','Ermita de San Martín de Montseny (o de Montseny d''Amunt)','Pequeño santuario rural prerrománico del siglo X modificado en el XII que se halla integrado en el paisaje del parque natural, caracterizado por su austera planta de nave única con ábside trapezoidal y una espadaña de dos ojos construida con aparejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08137','monumento','Masía de Can Riera de la Torre','Antigua heredad de montaña fortificada y documentada desde el Medievo que destaca por integrar en su estructura residencial una esbelta torre de defensa cilíndrica de mampostería basta destinada a la protección de los colonos contra el bandolerismo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08129','monumento','Núcleos de población de Muntanyola','El término municipal incluye los siguientes núcleos de población: Múnter y El Vilar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08129','iglesia','Iglesia de San Quirico de Muntanyola','Templo de origen románico reedificado en estilo barroco durante el siglo XVIII que conserva de su fábrica primitiva una nave longitudinal y destaca por albergar en su interior un valioso retablo de madera tallada y un conjunto de altares neoclásicos moldurados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08129','iglesia','Iglesia de San Esteban de Múnter','Edificio religioso románico del siglo XII modificado en la época barroca que presenta un ábside semicircular con decoración lombarda en sus muros exteriores, un portal con dovelas de piedra arenisca y un campanario cuadrangular que corona el término.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08129','monumento','Castillo de Múnter','Ruinas de una antigua fortaleza militar de la Plana de Vic documentada desde el siglo X de las cuales solo perviven vestigios dispersos de los muros de contención perimetrales y los cimientos de la torre de vigía original cubiertos por la vegetación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08139','iglesia','Iglesia de San Martín de Mura','Monumental templo románico que destaca por su evolución constructiva entre los siglos XI y XII, el cual exhibe una impresionante portada de tres arquivoltas de medio punto sobre columnas con capiteles profusamente historiados y un tímpano esculpido del siglo XII que representa la Adoración de los Reyes Magos en piedra caliza local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08139','ermita','Ermita de San Antonio','Pequeño santuario de origen medieval reformado en el siglo XVII que presenta una tipología de planta de cajón con muros de mampostería basta de piedra arenisca, un porche delantero techado a dos aguas y una sencilla espadaña de un solo vano que corona la fachada occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08139','monumento','Tina del Pou de la Riba','Singular estructura hidráulica y vinícola exenta construida a pie de viña durante el siglo XVIII mediante muros circulares de mampostería basta revestidos interiormente con baldosas cerámicas vidriadas para el fermentado del mosto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08140','iglesia','Iglesia de Santa María de Navarcles','Templo parroquial de estética barroca construido en el siglo XVIII sobre un asentamiento medieval anterior que presenta una imponente fachada de sillería regular con portada clasicista moldurada, capillas laterales entre los contrafuertes y un esbelto campanario octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08140','ermita','Ermita de San Vicente de Navarcles','Pequeño edificio religioso románico del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante sin ornamentación exterior y un campanario de espadaña de dos vanos ejecutado con aparejo rústico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08140','monumento','El Pont Vell (Puente Viejo)','Infraestructura civil del siglo XVIII que salva el cauce del río Llobregat mediante cinco arcadas de medio punto de luces decrecientes, construida enteramente en cantería y mampostería caliza con tajamares apuntados para desviar las corrientes fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08141','monumento','Núcleos de población de Navàs','El término municipal incluye los siguientes núcleos de población: Castelladral, El Mujal, Palà de Torroella, Valldeperes, Sant Cugat del Racó y Sant Salvador de Torroella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08141','iglesia','Iglesia de San Cugat del Racó','Excepcional joya del románico lombardo del siglo XI que presenta una planta de cruz griega única en la comarca con tres ábsides semicirculares decorados exteriormente con dobles arquillos ciegos y lesenas, coronada sobre el crucero por un cimborrio cilíndrico de gran pureza geométrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08141','iglesia','Iglesia de San Miguel de Castelladral','Templo de origen medieval reedificado en el siglo XVII que destaca por su emplazamiento fortificado sobre un cerro y su sólida fábrica de sillería granítica con portada tardorrenacentista y un recio campanario de torre de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08141','monumento','Colonia Palà de Torroella','Complejo urbanístico e industrial textil de finales del siglo XIX que constituye un exponente de la arqueología industrial catalana al conservar las naves de ladrillo visto, la turbina hidráulica, la iglesia neogótica y el palacio residencial de los propietarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90579','monumento','Núcleos de población de La Nou de Berguedà','El término municipal incluye los siguientes núcleos de población: Malanyeu.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90579','iglesia','Iglesia de San Martín de la Nou','Templo parroquial románico consagrado en el año 1119 que conserva una estructura de nave única cubierta por bóveda de cañón, un ábside semicircular decorado con un friso de dientes de sierra y una majestuosa portada meridional de tres arquivoltas en degradación con herrajes medievales originales en la puerta de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90579','iglesia','Santuario de Nuestra Señora de Lurda','Complejo neoclásico edificado a finales del siglo XIX que destaca por ser el primer santuario dedicado a la Virgen de Lourdes en España, integrado por una iglesia de tres naves con fachada monumental rematada por una gran escalinata de piedra caliza y una hospedería anexa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90579','iglesia','Iglesia de San Sadurní de Malanyeu','Pequeña iglesia románica del siglo XII que presenta un aparejo regular de sillarejo calizo, una nave longitudinal rematada por un ábside semicircular liso y un campanario de espadaña transformado posteriormente en torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90579','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Òdena Ódena 3728 Olèrdola Olér...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08143','monumento','Núcleos de población de Òdena','El término municipal incluye los siguientes núcleos de población: L''Espelt, El Raval d''Òdena, Samuntà y Sant Pere d''Òdena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08143','monumento','Castillo de Òdena','Fortaleza medieval originaria del siglo X de la que subsiste una imponente torre de defensa de planta decagonal construida con un aparejo regular de sillería caliza cementada con mortero, la cual corona el cerro calcáreo que domina toda la cuenca de Igualada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08143','iglesia','Iglesia de San Miguel de Òdena','Templo de base románica del siglo XII que presenta una sola nave cubierta por bóveda de cañón apuntada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una fachada occidental reformada que sostiene un campanario de espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08143','monumento','Villa Romana de L''Espelt','Yacimiento arqueológico musealizado datado entre los siglos I a.C. y IV d.C. que conserva los cimientos de piedra de la zona residencial (pars urbana) con restos de almacenes agrícolas, silos para grano y un complejo sistema de canalización de aguas termales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08145','monumento','Núcleos de población de Olèrdola','El término municipal incluye los siguientes núcleos de población: Sant Miquel d''Olèrdola, Moja, Viladellops y Can Trabal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08145','monumento','Conjunto Arqueológico de la Selva de Olèrdola','Recinto fortificado estratégico de primer orden ocupado desde la Edad del Bronce que conserva una monumental muralla romana del','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08145','iglesia','Iglesia de San Jaime de Moja','Templo románico de finales del siglo XII edificado en sillería regular que destaca por su ábside semicircular decorado exteriormente con arcuaciones ciegas y lesenas lombardas, además de poseer una portalada meridional con arquivoltas molduradas sobre columnas con capiteles vegetales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08145','monumento','Torre de Viladellops','Estructura defensiva medieval de planta circular construida en el siglo XI con aparejo de mampostería basta que se encuentra integrada en un conjunto vitivinícola tradicional del Penedès, conservando sus saeteras originales y restos del remate almenado superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08146','monumento','Núcleos de población de Olesa de Bonesvalls','El término municipal incluye los siguientes núcleos de población: Hospital de Cervelló.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08146','monumento','Antiguo Hospital de Cervelló','Hospital de peregrinos fundado en el siglo XIII que constituye uno de los ejemplos más puros y mejor conservados de la arquitectura civil gótica catalana, caracterizado por su recinto fortificado perimetral con torre de defensa cuadrada, portal dovelado de medio punto y una gran sala de arcos diafragmáticos apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08146','iglesia','Iglesia de San Juan de Olesa de Bonesvalls','Templo parroquial de origen medieval reformado íntegramente en el siglo XVIII bajo las directrices del estilo barroco que exhibe una fachada de sillería caliza con portada moldurada, capillas laterales entre contrafuertes y un esbelto campanario de torre octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08147','iglesia','Iglesia de Santa María de Olesa','Templo parroquial reedificado en el siglo XX tras su destrucción que conserva de su fábrica anterior una monumental torre-campanario del siglo XVI de planta cuadrangular ejecutada en sillería de piedra arenisca con remate de balaustrada renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08147','monumento','Torre del Reloj','Antigua torre de vigía perteneciente al desaparecido castillo medieval de la villa del siglo XII que presenta una estructura cuadrangular de mampostería regular, modificada en épocas posteriores para albergar el mecanismo del reloj público y una estructura de forja artística para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08147','ermita','Ermita de San Pedro Sacama','Pequeño santuario románico del siglo X emplazado sobre un cresterío rocoso que consta de una sola nave con bóveda de cañón, un ábside semicircular decorado con arcuaciones lombardas y restos de los muros perimetrales de una fortificación carolingia contigua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08148','monumento','Núcleos de población de Olivella','El término municipal incluye los siguientes núcleos de población: Can Surià, Las Colinas, Mas Mestre y Plana Novella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08148','palacio','Palacio de la Plana Novella (Palacio Novella)','Suntuosa mansión residencial ecléctica construida en 1890 por indianos adinerados que combina elementos neogóticos e historicistas con un lavadero de inspiración mudéjar, convertida actualmente en monasterio budista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08148','iglesia','Iglesia de San Pedro de Olivella','Templo parroquial del siglo XVII edificado sobre el núcleo antiguo que presenta una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08148','monumento','Castillo de Olivella','Ruinas de una fortaleza medieval del siglo X emplazada sobre un cerro calcáreo del parque natural de las que subsisten los cimientos de una torre cilíndrica de mampostería y vestigios de la cortina defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08149','monumento','Núcleos de población de Olost','El término municipal incluye los siguientes núcleos de población: Santa Cruz de Joglars.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08149','iglesia','Iglesia de Santa María de Olost','Monumental templo barroco tardío del siglo XVIII conocido popularmente como la "Catedral del Lluçanès" debido a sus grandes dimensiones, el cual destaca por su imponente fachada neoclásica flanqueada por dos torres-campanario idénticas de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08149','monumento','Castillo de Perafita','Caserón fortificado de origen medieval reconstruido a principios del siglo XX en un estilo historicista que incorpora elementos del gótico civil catalán como ventanas geminadas de tracería calada, torres esquineras con almenas y un gran patio de armas perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08150','monumento','Núcleos de población de Orís','El término municipal incluye los siguientes núcleos de población: Can Bondia, Saderra y El Pelut.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08150','monumento','Castillo de Orís','Ruinas de una estratégica fortaleza medieval documentada desde el siglo X y desmantelada durante las guerras carlistas que conservan tramos notables de sus muros de sillería de piedra caliza, los arcos góticos de la sala noble y la base de la capilla de San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08150','iglesia','Iglesia de San Saturnino de Saderra','Templo de base románica del siglo XI profundamente transformado en época','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08164','monumento','Núcleos de población de Pacs del Penedès','El término municipal incluye los siguientes núcleos de población: La Xarcú, Barri de la Rectoria y Els Moja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08164','iglesia','Iglesia de San Ginés de Pacs','Templo parroquial reedificado en el siglo XVII en estilo barroco rural que presenta una planta de nave única con capillas laterales, una fachada sencilla enlucida con portal de cantería moldurada y una torrecampanario cuadrangular de remate piramidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08164','monumento','Masía de Can Mayol','Gran heredad vitivinícola tradicional construida a partir del siglo XVI que exhibe una fachada asimétrica de tres cuerpos con portal de medio punto dovelado, ventanas con dinteles de piedra caliza labrada y un patio interior porticado de carácter señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08155','monumento','Núcleos de población de Palafolls','El término municipal incluye los siguientes núcleos de población: Sant Genís de Palafolls, Ciutat Jardí y Mas Carbó.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08155','monumento','Castillo de Palafolls','Ruinas de una monumental fortaleza militar medieval del siglo X emplazada sobre una cresta rocosa que conserva gran parte de su recinto soberano con muros de mampostería regular, la torre del homenaje de planta rectangular y los restos de la capilla gótica de San Miguel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08155','iglesia','Iglesia de San Ginés de Palafolls','Edificio religioso de origen románico profundamente reformado en el siglo XVI que destaca por su portalada gótico-renacentista de sillería granítica y por albergar un valioso retablo mayor pictórico de época renacentista atribuido al maestro de Els Solsona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08155','monumento','Pabellón Polideportivo "El Palauet"','Obra vanguardista de la arquitectura contemporánea diseñada por el arquitecto japonés Arata Isozaki en 1996 que destaca por su innovadora cubierta de estructura metálica espacial y su integración orgánica con la topografía del terreno mediante paramentos acristalados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08156','monumento','Monumentos d Descripciones','Monumentos d Descripciones','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08156','monumento','Castillo de Plegamans','Casa fuerte señorial de origen medieval reconstruida en los siglos XIV y XV bajo los parámetros del gótico civil catalán que presenta una estructura cuadrangular fortificada con una torre de defensa angular, portaladas doveladas de medio punto y amplias salas cubiertas con techumbres de viguería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08156','iglesia','Iglesia de Santa María de Palau-solità','Templo parroquial de origen románico transformado en el siglo XVI en estilo gótico tardío que muestra una sola nave con capillas entre los contrafuertes, una portalada de cantería moldurada y una recia torre-campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08156','monumento','Masía de Can Cortès','Gran explotación agrícola documentada desde el siglo XVII que funciona como centro cultural, caracterizada por su fachada principal de líneas simétricas con un gran reloj de sol esgrafiado y portal adintelado de piedra arenisca local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08157','monumento','Núcleos de población de Pallejà','El término municipal incluye los siguientes núcleos de población: Fontpineda y La Magina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08157','palacio','Castillo-Palacio de Pallejà','Gran caserón señorial de estilo renacentista construido a finales del siglo XVI sobre las bases de una torre de defensa medieval que exhibe muros de mampostería regular con sillares escuadrados en los ángulos, ventanas con molduras clasicistas y portales de medio punto dovelados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08157','iglesia','Iglesia de Santa Eulalia de Pallejà','Templo parroquial levantado a principios del siglo XX en estilo neoclásicohistoricista que cuenta con una amplia nave longitudinal, un frontón triangular superior en su fachada principal y una esbelta torre-campanario de planta ochocentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08159','iglesia','Iglesia de San Esteban de Parets','Templo parroquial reedificado en estilo neogótico tras la Guerra Civil que aprovecha en su estructura los cimientos y elementos de sillería de la antigua fábrica románica del siglo XIII, destacando su fachada con un gran rosetón de tracería calada y una esbelta torre-campanario apuntada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08159','monumento','Torre de Malla','Masía fortificada de origen medieval reformada a finales del siglo XIX bajo una estética historicista que imita un castillo gótico, caracterizada por sus almenas perimetrales, ventanas geminadas con arcos conopiales labrados en piedra caliza y una torre de defensa exenta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08159','monumento','Masía de Can Serra','Gran explotación agrícola tradicional del siglo XVI construida en mampostería basta que presenta un monumental portal dovelado de medio punto, ventanas con alféizares de arenisca moldurada y un gran pozo exento en el patio de armas delantero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08160','iglesia','Iglesia de San Pedro de Perafita','Monumental templo barroco edificado en el siglo XVIII sobre un oratorio anterior que presenta una imponente fachada de sillería vista con portada clásica moldurada, un gran óculo central y un robusto campanario octogonal que domina el núcleo urbano del Lluçanès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08160','monumento','Masía de Can Heures','Casa solariega de relevancia arquitectónica construida a partir del siglo XVI que muestra una volumetría de tres cuerpos con tejado a dos aguas, portales de medio punto dovelados y una galería solana con arcadas de ladrillo visto en el piso superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08161','monumento','Núcleos de población de Piera','El término municipal incluye los siguientes núcleos de población: El Bedorc, Can Claramunt, Can Bonastre y La Venta i l''Smar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08161','monumento','Castillo de Jaume I (Castillo de Piera)','Magna fortaleza medieval documentada desde el siglo X y restaurada con rigor histórico que destaca por su imponente recinto amurallado de sillería regular, su torre del homenaje de planta cuadrada y sus amplios salones góticos con arcos diafragmáticos apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08161','iglesia','Iglesia de Santa María de Piera','Templo de origen románico modificado en época gótica y barroca que presenta una nave longitudinal con capillas laterales, conservando una notable portada de tres arquivoltas en degradación y fragmentos de pinturas murales medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08161','ermita','Ermita de la Virgen de la Guardia','Pequeño santuario rural del siglo XII edificado con aparejo tosco de piedra calcárea que consta de una sola nave con ábside semicircular orientado a levante y una espadaña de dos vanos sobre la fachada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08161','monumento','Casa Sastre (Cal Sanahuja)','Edificio residencial modernista del casco urbano que destaca por su fachada ornamentada con esgrafiados geométricos y florales, barandillas de hierro','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08164','iglesia','Iglesia de Santa María del Pla','Templo parroquial de origen románico profundamente reformado en el siglo XVIII bajo el influjo del barroco tardío que conserva de su fábrica medieval un ábside semicircular liso ejecutado en sillería caliza y una portada septentrional con arquivolta moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08164','monumento','Masía de Can Cerdà de la獨','Gran complejo agropecuario e indiano estructurado a partir del siglo XVI que presenta un cuerpo residencial con galerías porticadas de aire clasicista, ventanas con dinteles de cantería labrada y bodegas subterráneas destinadas a la crianza vinícola tradicional del Penedès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08165','monumento','Castillo de Claramunt','Monumental fortaleza medieval erigida en el siglo X que constituye uno de los conjuntos fortificados más excelsos y mejor conservados de Cataluña, caracterizado por su impresionante recinto amurallado con torreones cilíndricos exentos, una torre del homenaje de planta cuadrada de cantería regular y la iglesia románica de Santa María con planta de tres naves absidiales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08165','iglesia','Iglesia de Santa María de la Pobla','Templo parroquial de estilo barroco construido en el siglo XVIII que exhibe una fachada monumental de sillería vista con portalada clasicista flanqueada por pilastras, un gran óculo superior moldurado y un campanario octogonal con remate cupulado de azulejería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08165','monumento','Antiguo Hospital de Pobres','Complejo asistencial de traza gótica del siglo XIV edificado con aparejo rústico que mantiene su portal de entrada de arco de medio punto dovelado y una sala institucional con arcos diafragmáticos apuntados sobre pilares de mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08166','monumento','Núcleos de población de La Pobla de Lillet','El término municipal incluye los siguientes núcleos de población: Las Llosas y San Antonio de la Aliseda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08166','iglesia','Monasterio de San Lorenzo de Bagá (Sant Llorenç prop Bagà)','Cenobio benedictino del siglo X situado en su ámbito geográfico que destaca por su iglesia románica de planta basilical y una cripta subterránea excepcional de tres naves con bóvedas de arista soportadas por columnas monolíticas con capiteles toscos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08166','monumento','Jardines Artigas','Espectacular parque natural y arquitectónico diseñado por Antoni Gaudí a principios del siglo XX que fusiona la vegetación de la alta montaña con estructuras orgánicas de piedra calcárea, cemento armado, arcos catenarios de rocalla y fuentes monumentales integradas sobre el cauce del río Llobregat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08166','monumento','Chalet de Catllaràs','Refugio de montaña proyectado por Antoni Gaudí en 1902 para los ingenieros de las minas de carbón que presenta una audaz estructura parabólica inclinada revestida de pizarra rústica y una escalera exterior de caracol integrada en la fachada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08166','monumento','Puente Viejo (Pont Vell)','Infraestructura civil de origen gótico construida en el siglo XIV sobre el río Llobregat mediante un único arco apuntado de gran luz, edificado con un aparejo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08182','monumento','Núcleos de población de El Pont de Vilomara i Rocafort','El término municipal incluye los siguientes núcleos de población: Rocafort de Bages.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08182','monumento','Puente de Vilomara','Monumental infraestructura civil de origen romano reconstruida en el siglo XIV mediante nueve arcadas de medio punto de luces decrecientes que salvan el','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08182','iglesia','Iglesia de Santa María de Rocafort','Templo de traza gótica tardía edificado en el siglo XIV que presenta una amplia nave única con capillas laterales entre los contrafuertes, un portal de arquivoltas apuntadas y una robusta torre-campanario de planta cuadrangular que domina el núcleo fortificado de Rocafort.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08182','ermita','Ermita de Santa Magdalena del Mar','Pequeño santuario románico del siglo XI que consta de una sola nave cubierta por bóveda de cañón, un ábside semicircular decorado exteriormente con arcuaciones ciegas y lesenas de estilo lombardo, construido con un aparejo regular de sillarejo calizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08168','iglesia','Iglesia de Santa Magdalena de Pontons','Templo de origen románico profundamente reformado en el siglo XVIII que destaca por su emplazamiento escarpado sobre un risco y por conservar de su fábrica primitiva una portalada de tres arquivoltas en degradación esculpidas en piedra caliza local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08168','monumento','Castillo de Pontons','Ruinas de una fortaleza medieval del siglo XI de las que subsisten tramos dispersos de la muralla perimetral de mampostería basta y los cimientos de una gran torre de vigía cilíndrica asentada sobre la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08168','iglesia','Santuario de San Juan de la Montaña','Capilla rural románica del siglo XII que presenta una planta de nave única con ábside semicircular orientado a levante, muros de sillería basta cementada con cal y un campanario de espadaña de dos vanos sobre el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08017','iglesia','Santuario de la Virgen de Lurda','Templo de estilo historicista neogótico construido a finales del siglo XIX que presenta una fachada monumental con portal apuntado, un gran rosetón de tracería calada y una esbelta torre-campanario rematada por una aguja piramidal que domina el paisaje de la meseta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08017','iglesia','Iglesia de San Vicente de Prats','Edificio religioso de época barroca (siglo XVII) edificado en sillería regular que cuenta con una amplia nave longitudinal, capillas laterales intercomunicadas, una portada clasicista moldurada con hornacina superior y un recio campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08017','ermita','Ermita de San Sebastián','Pequeño oratorio rural barroco levantado en el siglo XVIII con aparejo rústico de piedra arenisca que muestra una planta de cajón muy sobria, un portal adintelado bajo un reloj de sol pintado y una espadaña de un solo ojo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08230','iglesia','Iglesia de San Pedro de Premià de Dalt','Templo parroquial de estilo gótico tardío construido en el siglo XVI que presenta una amplia nave única con capillas laterales entre los contrafuertes, una portada renacentista de sillería granítica y una robusta torre-campanario de planta cuadrangular rematada por un antepecho balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08230','iglesia','Santuario de la Virgen de la Cisa','Complejo religioso edificado en el siglo XVIII bajo los cánones del barroco clasicista que muestra una sobria fachada de sillería enlucida con portal adintelado moldurado, un interior cubierto con bóvedas de lunetos y una hospedería anexa destinada tradicionalmente al hospedaje de peregrinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08230','monumento','Yacimiento Arqueológico de la Cadira del Bisbe','Asentamiento layetano de la Edad del Hierro (siglos V al III a.C.) situado en una estribación de la cordillera Litoral que conserva las plantas de piedra de sus viviendas adosadas a la muralla y silos para el almacenamiento de cereal excavados en el terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08172','iglesia','Iglesia de San Cristóbal','Templo parroquial levantado a principios del siglo XIX en estilo neoclásico que exhibe una fachada monumental flanqueada por pilastras, un gran frontón triangular superior y una esbelta torre-campanario de planta cuadrada coronada por una cúpula de cerámica vidriada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08172','monumento','Masía de Can Manent','Gran casa solariega de origen medieval profundamente reformada en el siglo XVII que funciona como biblioteca municipal, caracterizada por su portal de arco de medio punto con grandes dovelas de cantería y ventanas de repisa moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08172','monumento','Fábrica de Gas (Museo de la Estampación)','Antiguo complejo industrial modernista de principios del siglo XX que constituye el único exponente de fábrica de gas de hulla conservado en Cataluña, destacando sus naves de ladrillo visto y sus grandes estructuras de fundición de hierro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90580','iglesia','Iglesia de San Andrés de Puigdàlber','Templo parroquial reedificado en el siglo XVIII en estilo barroco rural sobre una estructura medieval anterior que presenta una planta de nave única con capillas laterales, muros exteriores de mampostería enlucida y una sencilla torre-campanario cuadrangular de remate piramidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90580','monumento','Masía de Can Llavería','Antigua explotación agrícola tradicional del Penedès estructurada a partir del siglo XVI que muestra un portal de arco de medio punto dovelado, ventanas con dinteles de piedra caliza labrada y dependencias auxiliares destinadas a la crianza vinícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','monumento','Núcleos de población de Puig-reig','El término municipal incluye los siguientes núcleos de población: Cal Casas, Cal Marçal, Cal Vidal, Cal Pons, Graugés y Per領ol.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','monumento','Castillo y Núcleo Medieval de Puig-reig','Fortaleza e iglesia románica de San Martín construidas por los caballeros templarios en el siglo XII sobre un imponente risco que domina el río Llobregat, conservando tramos de muralla de sillería regular, la torre del homenaje y pinturas murales románicas al fresco de gran valor litúrgico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','iglesia','Colonia Pons (Iglesia de San José y Torre del Amo)','Espectacular conjunto urbanístico e industrial textil fundado en 1875 que destaca por su iglesia neogótica proyectada por Josep Torres i Argullol, sus naves de hilatura de ladrillo visto y el palacio residencial de los propietarios rodeado de un frondoso jardín romántico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','monumento','Colonia Vidal (Museo de la Colonia Vidal)','Complejo industrial decimonónico musealizado de primer orden que permite comprender la vida obrera junto al río Llobregat al conservar intactas las turbinas hidráulicas, la fábrica de tejidos, las viviendas de los trabajadores, el teatro y la escuela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','monumento','Puente de Per領ol','Infraestructura civil de origen gótico construida en el siglo XIV mediante un gran arco apuntado central que salva el cauce fluvial, ejecutada con aparejo regular de bloques de piedra arenisca y tajamares para desviar la corriente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','monumento','Premiá de Dalt Premiá de Dalt [1] (oficialmente en catalán','Premià de Dalt ) es un municipio de la provincia de Barcelona, Cataluña, España, situ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Puigdàlber Puigdalba 555 Puig-','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08176','monumento','Núcleos de población de Pujalt','El término municipal incluye los siguientes núcleos de población: Aston, Conill, La Guàrdia Pilosa y Vilamajor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08176','iglesia','Iglesia de San Andrés de Pujalt','Templo de base románica del siglo XII profundamente transformado en época barroca que conserva de su fábrica original muros de sillería caliza regular y una portada meridional moldurada, destacando en el perfil urbano su recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08176','monumento','Base del Campo de Entrenamiento del XVIII Cuerpo de Ejército','Complejo militar musealizado de la Guerra Civil Española erigido en 1938 que conserva refugios antiaéreos excavados en el terreno, barracones de mampostería basta, letrinas y las instalaciones del campamento republicano destinadas a la instrucción de reclutas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08176','iglesia','Iglesia de San Vicente de Conill','Pequeño templo románico del siglo XI edificado con aparejo de sillarejo regular que consta de una sola nave con bóveda de cañón, un ábside semicircular decorado exteriormente con motivos lombardos de arquillos ciegos y una espadaña de dos vanos sobre el hastial de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08178','monumento','Núcleos de población de Rajadell','El término municipal incluye los siguientes núcleos de población: Monistrolet y Els Molins.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08178','monumento','Castillo de Rajadell','Monumental fortaleza medieval documentada desde el siglo X y reedificada en estilo góticorenacentista en el siglo XV que domina la villa desde un promontorio rocoso, caracterizada por sus imponentes muros de sillería de piedra arenisca local, ventanas góticas de tracería calada y un gran patio de armas perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08178','iglesia','Iglesia de San Iscle y Santa Victoria','Templo parroquial de traza gótica tardía adosado a la estructura del castillo que presenta una amplia nave única con capillas laterales entre contrafuertes, un portal de arquivoltas apuntadas molduradas y una torre-campanario cuadrangular de remate almenado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08178','monumento','Yacimiento de la Villa Romana de San Amanzo (Sant Amanç)','Asentamiento agrícola de época imperial romana que conserva las trazas de piedra de sus estancias residenciales y productivas, donde las excavaciones arqueológicas sacaron a la luz silos para el almacenamiento de cereal y restos de balsas destinadas a la producción vinícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08179','iglesia','Iglesia Vieja de San Pedro de Rellinars','Ruinas de un templo parroquial de origen románico y prerrománico modificado en el siglo XVII que conservan muros perimetrales de mampostería basta y la base del antiguo ábside, integrados de forma pintoresca en el paisaje boscoso de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08179','monumento','Las Tinas de las Vilas (Les Tines de les Valls)','Singular conjunto de construcciones vinícolas exentas del siglo XVIII edificadas a pie de viña con muros circulares de mampostería y mortero de cal, revestidas interiormente con baldosas cerámicas vidriadas para fermentar el mosto de forma remota.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08180','iglesia','Iglesia de San Esteban de Ripollet','Templo de origen románico reconstruido en estilo gótico tardío y transformado en las centurias XVII y XVIII que destaca por su monumental portalada renacentista de sillería granítica con hornacina','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08180','monumento','Molino de Alán (Molí d''en Rata)','Antiguo complejo hidráulico harinero edificado a principios del siglo XIX que constituye uno de los últimos testimonios preindustriales del río Ripoll, convertido en centro de interpretación con su maquinaria de madera y muelas de piedra totalmente restauradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08183','monumento','Yacimiento Arqueológico de L''Esquerda','Asentamiento fortificado con ocupación continuada desde la Edad del Bronce hasta el periodo medieval que destaca por su monumental muralla ibérica del siglo IV a.C. construida con grandes bloques de piedra caliza, sus talleres metalúrgicos y las trazas de una iglesia románica rodeada por una necrópolis de tumbas antropomorfas excavadas en la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08183','iglesia','Iglesia de San Pedro de Roda','Templo parroquial de estética barroca clasicista edificado a principios del siglo XVIII que presenta una fachada monumental de sillería caliza vista con portal moldurado bajo hornacina, un interior de nave única cubierta por bóvedas de lunetos y una recia torre-campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08183','monumento','Puente Viejo (Pont Vell)','Infraestructura civil de origen medieval reconstruida en los siglos XVII y XVIII que salva el cauce del río Ter mediante tres grandes arcadas de medio','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08185','monumento','Núcleos de población de Rubió','El término municipal incluye los siguientes núcleos de población: Els Segurles y El Pla de Rubió.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08185','iglesia','Iglesia de Santa María de Rubió','Templo fortificado de estilo gótico catalán construido en el siglo XIV adosado a los restos del antiguo castillo medieval que presenta una robusta nave única sin capillas laterales, muros de cantería caliza provistos de aspilleras defensivas y un extraordinario retablo pictórico del siglo XIV atribuido al maestro de Rubió.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08185','monumento','Castillo de Rubió','Ruinas de una estratégica fortaleza militar del siglo XI emplazada sobre una cresta rocosa de las que subsisten los potentes cimientos de la torre del homenaje de planta circular, tramos dispersos de la muralla perimetral y restos de estancias de almacenamiento ejecutadas con aparejo rústico cementado con cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08185','monumento','Dolmen de los Tres Reyes (Dolmen dels Tres Reis)','Sepulcro megalítico del Neolítico final que conserva su cámara funeraria de planta rectangular delimitada por grandes losas de piedra local hincadas verticalmente en el terreno y vestigios del túmulo circular exterior que servía de enterramiento colectivo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08187','monumento','Núcleos de población de Sabadell','El término municipal incluye los siguientes núcleos de población: Togores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08187','ermita','Ermita de San Nicolás (Sant Nicolau de Salut)','Pequeña capilla románica del siglo XI emplazada en su término municipal que presenta una singular planta absidial con tres lóbulos y decoración exterior lombarda de arquillos ciegos, ejecutada enteramente con hiladas regulares de sillarejo calizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08187','monumento','Vapor Buxeda Vell','Fábrica textil decimonónica reconvertida en museo que constituye uno de los exponentes más completos de la arqueología industrial catalana al conservar intacta su imponente sala de máquinas de vapor, la chimenea troncocónica de ladrillo macizo visto y las naves de hilatura de grandes luces estructurales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08187','monumento','Campanario de San Félix','Torre exenta de estilo barroco clasicista proyectada en el siglo XVIII por el arquitecto Joan Garrido que domina la plaza mayor de la ciudad, caracterizada por sus tres cuerpos decrecientes de planta cuadrada y ochocavada rematados por un pináculo cupulado de azulejería vidriada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08187','monumento','Edificio de la Caja de Ahorros de Sabadell (Caixa Sabadell)','Obra cumbre de la arquitectura modernista institucional diseñada por Jeroni Martorell a principios del siglo XX que destaca por su fachada ornamentada con esculturas alegóricas de Josep Limona, vidrieras polícrómas, columnas de piedra caliza tallada y un espectacular patio columnado interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08188','monumento','Núcleos de población de Sagàs','El término municipal incluye los siguientes núcleos de población: La Guàrdia de Sagàs y Biure.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08188','iglesia','Iglesia de San Andrés de Sagàs','Monumental templo románico del siglo XI de planta basilical que presenta tres naves separadas por pilares cuadrangulares con cubiertas de madera a dos aguas, tres ábsides semicirculares perfectos provistos de decoración exterior de estilo lombardo y una robusta torre-campanario añadida en época barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08188','iglesia','Santuario de la Virgen de la Guardia','Edificio religioso barroco edificado en el siglo XVIII con aparejo rústico de piedra caliza que muestra una estructura de nave única con capillas laterales entre contrafuertes, un portal de líneas neoclásicas sencillas y una esbelta torre-campanario de planta cuadrada con vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08188','iglesia','Iglesia de San Martín de Biure','Pequeño santuario románico del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90581','monumento','Núcleos de población de Sallent','El término municipal incluye los siguientes núcleos de población: Cabrianes y Cornet.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90581','monumento','Castillo y Rotonda de San Sebastián de Sallent','Conjunto monumental medieval emplazado sobre una colina que destaca por albergar la iglesia románica circular más grande de Cataluña (siglo XI), caracterizada por su planta de rotonda cubierta con cúpula hemisférica y muros de sillería caliza regular decorados con arquillos lombardos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90581','iglesia','Iglesia de Santa María de Cornet','Joya del románico del siglo XII que consta de una sola nave con bóveda de cañón, un ábside semicircular con un bellísimo friso esculpido con motivos vegetales y geométricos y una portada meridional de tres arquivoltas en degradación soportadas por capiteles historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90581','monumento','Casa Natal de San Antonio María Claret','Casa solariega tradicional de tejedores del siglo XVIII restaurada como espacio de memoria que conserva la estructura original de muros de mampostería y viguería de madera, las estancias residenciales y el taller de telares manuales de la época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90581','monumento','Fábrica de Cal Torrents','Antiguo complejo textil decimonónico situado junto al río Llobregat que constituye un testimonio clave de la arqueología industrial de la comarca con sus naves diáfanas de ladrillo visto, su chimenea troncocónica y el canal de derivación de aguas con compuertas de fundición.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08194','monumento','Central Térmica de San Adrián (Las Tres Chimeneas)','Monumental e imponente estructura de la arqueología industrial del siglo XX (inaugurada en la década de 1970) constituida por tres colosales torres de evacuación de humos de hormigón armado de 200 metros de altura que se alzan sobre los bloques de las calderas de fundición a orillas del mar Mediterráneo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08194','iglesia','Iglesia parroquial de San Adrián','Templo levantado a mediados del siglo XX en estilo historicista neorrománico que presenta una amplia nave longitudinal con arcos fajones, una fachada principal con tres portales de medio punto rematados por hornacinas y una esbelta torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08194','monumento','Refugio Antiaéreo de la Plaza de la Villa','Galería subterránea de defensa pasiva construida en 1938 durante la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08194','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Sagàs Sagás 157 Saldes Saldes ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08195','monumento','Núcleos de población de Sant Agustí de Lluçanès','El término municipal incluye los siguientes núcleos de población: L''Alou y Sant Boi de Lluçanès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08195','iglesia','Santuario de la Virgen de los Cinglos (Mare de Déu dels Cingles)','Templo románico del siglo XII emplazado sobre un espectacular acantilado de roca calcárea que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular liso orientado a levante y una espadaña de dos vanos sobre el hastial de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08195','iglesia','Iglesia de San Agustín','Edificio religioso de origen medieval reconstruido íntegramente en el siglo XVIII bajo las directrices del estilo barroco rural que exhibe una fachada de sillería enlucida con portal de cantería moldurada, una torrecampanario cuadrangular de remate piramidal y un entorno de masías tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08196','iglesia','Iglesia de San Andrés','Templo parroquial de origen medieval reedificado en el siglo XVIII en estilo barroco clasicista y ampliado en el XIX que presenta una fachada monumental de sillería vista con portalada moldurada entre pilastras, un gran óculo central y un robusto campanario octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08196','monumento','Masía de Can Archs','Gran heredad agrícola documentada desde el siglo XV que muestra la estructura tradicional catalana de tres cuerpos con tejado a dos aguas, un monumental portal dovelado de arco de medio punto en piedra caliza local y ventanas con alféizares renacentistas labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08197','iglesia','Iglesia Vieja de San Andrés','Templo gótico tardío del siglo XVI edificado con aparejo de mampostería regular y sillares de granito berroqueño en los ángulos que destaca por su portalada renacentista con frontón triangular y por conservar la estructura de su campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08197','monumento','Torre del Conde de San Joaquín (Ca l''Almirall)','Suntuoso palacete residencial de estética modernista e historicista construido a principios del siglo XX que exhibe fachadas con profusa decoración exterior de esgrafiados florales, grandes tribunas de piedra caliza calada, ventanas de arco conopial y un frondoso jardín romántico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08197','monumento','Masía de Can Caralt','Gran complejo agropecuario e indiano del siglo XVIII reconvertido en museo municipal que cuenta con un portal de arco de medio punto con grandes dovelas de cantería, ventanas de repisa moldurada y salones nobles decorados con mobiliario de época y colecciones de arte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08198','monumento','Núcleos de población de Sant Antoni de Vilamajor','El término municipal incluye los siguientes núcleos de población: Sant Julià d''Alfou y Pineda de Vilamajor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08198','iglesia','Iglesia de San Antonio de Padua','Templo parroquial levantado a mediados del siglo XX en un estilo historicista de inspiración neogótica que incorpora elementos decorativos tradicionales, caracterizado por su fachada principal con portal apuntado bajo un gran rosetón de tracería geométrica y una esbelta torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08198','monumento','Masía de Can Vila','Antigua explotación agrícola tradicional estructurada a partir del siglo XVI en mampostería basta que presenta un portal de arco de medio punto dovelado de gran envergadura, ventanas con dinteles de piedra arenisca labrada y un gran reloj de sol esgrafiado en su paramento exterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08198','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Sant Agustí de Lluçanès San Ag...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08199','monumento','Núcleos de población de Sant Bartomeu del Grau','El término municipal incluye los siguientes núcleos de población: Alboquers y Sant Per領ol.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08199','iglesia','Iglesia de Sant Bartomeu del Grau','Templo parroquial del siglo XVIII de estilo barroco clasicista que muestra una amplia nave con capillas laterales, una fachada de líneas severas con portalada moldurada de piedra local y un esbelto campanario de torre de sección cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08199','iglesia','Iglesia de San Jaime de Alboquers','Pequeño edificio religioso románico del siglo XII que consta de una sola nave cubierta por bóveda de cañón, un ábside semicircular','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90582','iglesia','Iglesia de San Baudilio de Lluçanès','Monumental edificio religioso construido en el siglo XVIII bajo trazas barrocas de aire clasicista que destaca por su fachada de sillería de piedra','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90582','iglesia','Santuario de la Virgen de los Trabajos (Mare de Déu dels Munts)','Templo mariano situado en una cumbre estratégica del término municipal que presenta una estructura del siglo XVIII de nave única con hospedería anexa y muros de mampostería basta adaptados al clima de alta montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08203','iglesia','Iglesia de San Cipriano de Vallalta','Templo parroquial de origen románico profundamente reformado en el siglo XVI en estilo gótico tardío que exhibe una fachada con portal renacentista de sillería granítica, contrafuertes exteriores y una recia torre-campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08203','monumento','Masía de Can Mates','Gran heredad rural del siglo XVI edificada con aparejo rústico que muestra un portal de arco de medio punto con grandes dovelas de granito berroqueño, ventanas de repisa moldurada de inspiración renacentista y un pozo cilíndrico exento en el patio delantero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08202','monumento','Núcleos de población de Sant Celoni','El término municipal incluye los siguientes núcleos de población: La Batllòria, Vilardell y Olzinelles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08202','iglesia','Iglesia de San Martín de Sant Celoni','Monumental templo barroco del siglo XVIII que destaca por albergar una de las fachadas esgrafiadas más grandes y complejas de Cataluña, decorada con virtuosísticas figuras alegóricas de las virtudes y arcángeles en tonos ocres y blancos sobre paramentos de mampostería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08202','monumento','Fuerza de San Celoni (La Força)','Restos del recinto amurallado medieval del siglo XII del que subsisten tramos notables de cortina defensiva integrados en viviendas del casco urbano y la Torre de la Fuerza, una maciza estructura cilíndrica ejecutada en sillería y piedra granítica local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08202','iglesia','Iglesia de San Martín de Vilardell','Templo románico del siglo XII edificado con aparejo de sillarejo tosco que consta de una sola nave con bóveda de cañón, un ábside semicircular orientado a levante y una espadaña de dos vanos sobre el muro occidental que evoca la sobriedad rural medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08204','iglesia','Iglesia de San Clemente de Llobregat','Templo parroquial de origen medieval profundamente reformado en el siglo XVIII y a principios del XX que destaca por su esbelto campanario románico de torre cuadrangular con ventanales de medio punto y por albergar un interior neoclásico de tres naves de gran altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08204','monumento','Masía de Can Colomer','Gran heredad agrícola tradicional estructurada a partir del siglo XVI mediante muros de mampostería basta enfoscada, la cual presenta un gran portal dovelado de arco de medio punto y ventanas con dinteles de cantería caliza moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','monumento','Núcleos de población de Sant Cugat del Vallès','El término municipal incluye los siguientes núcleos de población: Valldoreix, Mira-sol, La Floresta y Les Planes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','iglesia','Monasterio de San Cugat','Magno cenobio benedictino medieval que constituye uno de los conjuntos románicos más excelsos de España, célebre por su impresionante claustro del siglo XII con 144 capiteles historiados tallados por el maestro Arnau Cadell y una imponente iglesia gótica con un descomunal rosetón de tracería calada en su fachada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','monumento','Castillo de Canals','Ruinas consolidadas de una torre de defensa y palacio residencial fortificado del siglo XII que conservan los alzados de sillería caliza regular de su torre cuadrangular y tramos de muros perimetrales que atestiguan el poder feudal en la comarca del Vallès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','monumento','Bodega Cooperativa de Sant Cugat','Joya de la arquitectura agraria modernista proyectada por Cèsar Martinell en 1921 que destaca por su fachada de ladrillo visto combinada con mampostería, sus arcos parabólicos interiores que optimizan el espacio diáfano y sus depósitos cilíndricos exentos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','ermita','Ermita de San Medín (Sant Medir)','Iglesia de origen románico situada en pleno parque natural de Collserola que presenta una planta de nave única con bóveda de cañón apuntada, un portal adintelado reformado en el siglo XIX y un campanario de espadaña de un solo ojo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08206','iglesia','Iglesia de San Cugat Sesgarrigues','Templo de base románica profundamente transformado en épocas barroca y neoclásica que conserva de su fábrica del siglo XII una notable portada meridional con arquivoltas molduradas sobre capiteles esculpidos y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08206','monumento','Masía de Can Canyes','Antigua explotación vitivinícola tradicional del Penedès estructurada a partir del siglo XVII que exhibe una fachada simétrica de tres cuerpos con portal de medio punto adintelado, ventanas de repisa moldurada de piedra local y un reloj de sol esgrafiado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08206','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Sant Boi de Lluçanès San Baudi...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08207','monumento','Núcleos de población de Sant Esteve de Palautordera','El término municipal incluye los siguientes núcleos de población: Santa Maria de Palautordera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08207','monumento','Castillo de Montclús','Ruinas consolidadas de una monumental fortaleza medieval del siglo XI erigida sobre un cerro estratégico que conservan la gran torre del homenaje de planta circular, tramos de la muralla exterior con saeteras y los muros perimetrales de la antigua capilla castrense.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08207','iglesia','Iglesia de San Esteban de Palautordera','Templo de origen románico profundamente reformado en el siglo XVI en estilo gótico tardío que destaca por su robusta fachada de sillería granítica con portalada esculpida, sus potentes contrafuertes y un campanario de torre cuadrada rematado por gárgolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08207','monumento','Masía de Can Record','Gran caserón solariego tradicional documentado desde el Medievo que muestra una volumetría de tres cuerpos con tejado a dos aguas, un gran portal dovelado de arco de medio punto en piedra local y ventanales con dinteles renacentistas labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90583','monumento','Núcleos de población de Sant Esteve Sesrovires','El término municipal incluye los siguientes núcleos de población: Ca n''Amat, Vallserrat y Can Bargalló.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90583','iglesia','Iglesia de San Esteban Sesrovires','Templo parroquial reedificado a finales del siglo XIX bajo parámetros historicistas que presenta una amplia nave única de aire neogótico, una fachada principal enlucida con un gran rosetón moldurado y un esbelto campanario exento de planta octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90583','monumento','Masía de Can Canals','Antigua explotación agropecuaria tradicional estructurada a partir del siglo XVII mediante aparejo de mampostería basta, la cual conserva un gran portal de arco de medio punto con dovelas de piedra arenisca y estancias auxiliares destinadas a la producción de vino y aceite.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08210','iglesia','Iglesia de San Feliu de Codines','Monumental templo edificado en el siglo XVIII que fusiona elementos del barroco tardío y el neoclásico, destacando su imponente fachada de sillería vista con portalada flanqueada por pilastras y un recio campanario de torre octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08210','iglesia','Santuario de la Virgen del Ecce Homo','Pequeño centro de peregrinación de traza barroca rural que presenta una planta de cajón con muros de mampostería y mortero de cal, un porche delantero techado a dos aguas para refugio de fieles y una sencilla espadaña de un vano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08210','monumento','Can Casas','Casa señorial del casco urbano de estética modernista que exhibe una fachada ricamente decorada con esgrafiados de motivos vegetales, balconadas con barandillas de hierro forjado ondulante y grandes ventanales con molduras de inspiración floral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08211','catedral','Catedral de San Lorenzo','Templo parroquial elevado a rango de catedral en 2004 que fue reedificado tras la Guerra Civil en un estilo historicista de inspiración neomedieval, destacando su monumental fachada con un gran rosetón de tracería calada y un interior basilical de tres naves de gran altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08211','palacio','Palacio Falguera','Gran residencia señorial fortificada originaria del siglo XVII rodeada por un frondoso jardín histórico que cuenta con una fachada de líneas clasicistas, un gran patio de armas interior porticado con arcos rebajados y salas nobles decoradas con pinturas de época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08211','monumento','Torre de la Cárcel (Torre del Gall)','Estructura defensiva medieval de planta cuadrangular construida en sillería regular que formaba parte del antiguo recinto fortificado de la villa, reconvertida posteriormente en prisión municipal conservando saeteras y rejas de forja rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08211','monumento','Casas Modernistas de la Calle Bertrand','Conjunto residencial de principios del siglo XX diseñado por arquitectos locales que destaca por sus fachadas con profusa ornamentación exterior a base de esgrafiados geométricos, azulejería vidriada polícroma y barandillas de líneas sinuosas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08211','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Sant Esteve de Palautordera Sa...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08212','iglesia','Iglesia de San Feliu de Sasserra','Templo de base románica del siglo XII reedificado en estilo gótico tardío en el siglo XVI que conserva de su fábrica primitiva una excepcional portada occidental de tres arquivoltas talladas con relieves figurativos y un imponente campanario de torre de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08212','monumento','Casa del Consejo (Consell Municipal)','Palacio civil de estilo renacentista construido a principios del siglo XVII que destaca por su simétrica fachada de sillería caliza vista, sus ventanas con molduras clasicistas y un dintel esculpido con el escudo tradicional de la subcomarca del Lluçanès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08212','monumento','Centro de Interpretación de la Brujería','Espacio museístico ubicado en un caserón tradicional que documenta los procesos judiciales por brujería del siglo XVII mediante textos históricos, instrumental de la época y recreaciones escenográficas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90584','iglesia','Iglesia de San Fost de Campsentelles','Templo parroquial reedificado a mediados del siglo XX en estilo historicista de corte clásico que incorpora elementos de la antigua estructura barroca rural como la cimentación de la torre y algunos sillares de cantería granítica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90584','monumento','Masía de Can Torrents Vell','Gran explotación agrícola documentada desde el Medievo que presenta una volumetría de tres cuerpos con tejado a dos aguas, un monumental portal dovelado de arco de medio punto en piedra local y ventanas con dinteles rectangulares moldurados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08213','iglesia','Monasterio de San Benito de Bages (Sant Benet de Bages)','Magna abadía benedictina medieval que constituye un conjunto histórico-artístico excepcional, célebre por su claustro románico del siglo XII con más de sesenta capiteles profusamente esculpidos con motivos zoomorfos e historiados, su monumental iglesia de nave única con bóveda de cañón y su palacio abacial gótico de sillería caliza regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08213','iglesia','Iglesia de San Fruitós','Templo parroquial de origen románico transformado en los siglos XVII y XVIII bajo las directrices del estilo barroco que exhibe una fachada de sillería vista con portalada clasicista, contrafuertes exteriores exentos y una robusta torre-campanario que domina la plaza mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08213','monumento','Masía de San Iscle','Gran heredad agrícola fortificada vinculada históricamente al monasterio que cuenta con una pequeña ermita románica del siglo XII de planta de nave única con ábside semicircular liso y un portal dovelado de arco de medio punto en el cuerpo residencial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08020','iglesia','Iglesia de San Hipólito de Voltregà','Monumental templo barroco edificado en el siglo XVIII bajo los planos del arquitecto Josep Morató que destaca por su imponente fachada neoclásica de sillería caliza, su gran nave central con capillas intercomunicadas y una esbelta torre-campanario octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08020','monumento','Malloles (Casa Fuerte)','Ruinas de una antigua residencia señorial fortificada del siglo XII de la que subsisten tramos notables de muros de mampostería basta con aspilleras','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08020','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Sant Feliu Sasserra San Felíu ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08193','iglesia','Iglesia de San Iscle y Santa Victoria','Templo parroquial de origen románico profundamente transformado en el siglo XVIII en estilo barroco rural que exhibe una fachada de sillería enlucida con portalada de cantería moldurada, un interior de nave única y una robusta torre-campanario de planta cuadrada con vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08193','monumento','Masía de Ca l''Aranyó','Gran complejo agropecuario e indiano estructurado a partir del siglo XVI que presenta un cuerpo residencial tradicional con un monumental portal dovelado de arco de medio punto en piedra granítica, ventanas de repisa moldurada y dependencias anexas para la producción agrícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08216','iglesia','Iglesia del Monasterio de San Jaime de Frontanyà','Joya cumbre y paradigma del románico lombardo catalán del siglo XI que destaca por su perfecta planta de cruz latina con tres ábsides semicirculares decorados exteriormente con un friso de arcuaciones ciegas y lesenas, coronada sobre el crucero por un soberbio cimborrio octogonal único en su tipología por su pureza geométrica y constructiva de sillería calcárea regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08216','ermita','Ermita de San Esteban de Tubau','Pequeño santuario de origen prerrománico modificado en el siglo XII que presenta una sola nave con ábside trapezoidal, muros de sillería tosca combinada con mampostería basta y una espadaña de un solo ojo que se integra orgánicamente en el agreste paisaje de la alta montaña del Berguedà.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90585','monumento','Núcleos de población de Sant Joan de Vilatorrada','El término municipal incluye los siguientes núcleos de población: Joncadella y Sant Martí de Torroella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90585','iglesia','Santuario de Santa María de Joncadella','Centro de peregrinación edificado en el siglo XVIII sobre una base medieval anterior que muestra una sobria arquitectura barroca clasicista con fachada de sillería vista, un interior de nave única cubierto con bóvedas de lunetos y una hospedería anexa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90585','monumento','Fábrica de Can Gallifa','Antiguo complejo textil decimonónico situado junto al río Cardener que constituye un hito de la arqueología industrial de la comarca del Bages al conservar sus amplias naves diáfanas de ladrillo visto, grandes ventanales de fundición de hierro y la chimenea troncocónica original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90585','iglesia','Iglesia de San Martín de Torroella','Templo románico del siglo XII edificado con un aparejo regular de bloques de piedra arenisca que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante y una espadaña de dos ojos transformada posteriormente en torrecampanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08217','monumento','Torre de la Creu (Torre de los Huevos)','Obra cumbre del modernismo residencial proyectada por el arquitecto Josep Maria Jujol en 1913 que destaca mundialmente por su audaz diseño de cinco cilindros entrelazados con cubiertas cupuladas parabólicas revestidas de mosaico cerámico de gres polícromo (trencadís) y sinuosas barandillas de hierro forjado artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08217','monumento','Can Negre','Masía del siglo XVII transformada íntegramente por Josep Maria Jujol entre 1915 y 1930 en una explosión de plasticidad modernista barroca, caracterizada por su fachada principal con un carruaje-oratorio central flanqueado por ventanas de perfiles ondulantes, esgrafiados florales y un espectacular interior de techos ondulados y escaleras sinuosas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08217','ermita','Ermita de la Virgen del Buen Viaje','Pequeño santuario de origen gótico tardío del siglo XVI que presenta una planta de nave única con bóveda de crucería, una portada adintelada de cantería y un pozo de mampostería regular en su patio delantero que servía tradicionalmente de parada a los viajeros de la vía real.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08903','iglesia','Iglesia de San Julián de Cerdanyola','Templo parroquial de origen medieval reedificado en el siglo XVIII bajo los parámetros del barroco rural que presenta una fachada enlucida muy sobria con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torrecampanario de planta cuadrangular ejecutada en piedra caliza de alta montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08903','monumento','Antigua Fábrica de Cemento de Clot del Moro','Monumental complejo industrial de principios del siglo XX situado en su entorno geográfico que destaca por sus naves escalonadas de ladrillo visto y hormigón armado adaptadas a la pendiente del terreno, constituyendo un hito primordial de la arqueología industrial catalana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08220','monumento','Núcleos de población de Sant Julià de Vilatorta','El término municipal incluye los siguientes núcleos de población: Vilalleons.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08220','monumento','Casal de Espila (Casal d''Altari)','Gran casa fuerte señorial del siglo XIV de estilo gótico civil que conserva sus muros perimetrales de sillería caliza regular, ventanas geminadas con arcos conopiales labrados y una magnífica torre de defensa angular de planta cuadrada con aspilleras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08220','iglesia','Iglesia de Santa María de Vilalleons','Templo románico del siglo XII que destaca por su ábside semicircular decorado exteriormente con arcuaciones ciegas y lesenas lombardas, albergando en su interior un valioso retablo de madera tallada del gótico tardío y una portada meridional de tres arquivoltas en degradación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08220','monumento','Colegio del Rosario','Edificio de estética modernista construido a principios del siglo XX que exhibe una fachada ricamente decorada con esgrafiados geométricos, ventanales de arco rebajado con molduras de ladrillo visto y cornisas rematadas con azulejería cerámica polícroma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08220','ermita','Ermita de San Roque','Pequeño santuario rural del siglo XVIII edificado en mampostería basta que presenta una planta de cajón con un porche delantero techado a dos aguas sostenido por pilares de piedra y una sencilla espadaña de un solo ojo sobre el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08221','monumento','Walden 7','Monumental y vanguardista complejo residencial diseñado por el arquitecto Ricardo Bofill en 1974 que constituye un hito mundial de la arquitectura brutalista y posmoderna, caracterizado por su estructura modular de catorce pisos organizados en torno a grandes patios interiores revestidos de azulejos azules y una fachada exterior de arcilla roja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08221','iglesia','Iglesia de San Justo y Pastor','Templo parroquial de origen medieval profundamente reformado en el siglo XVI en estilo gótico tardío que exhibe una fachada con portal renacentista de sillería granítica, un interior de nave única con capillas entre los contrafuertes y un recio campanario de torre cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08221','monumento','Can Ginestar','Masía fortificada del siglo XV transformada a principios del siglo XX en estilo modernista e historicista por el','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08223','monumento','Núcleos de población de Sant Llorenç Savall','El término municipal incluye los siguientes núcleos de población: Marata y La Castanya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08223','monumento','Castillo de Pera','Ruinas consolidadas de una estratégica fortaleza medieval del siglo X emplazada sobre una aguja rocosa de las que subsisten potentes muros de sillería basta, la base de la torre del homenaje y la capilla románica de Santa María con su ábside semicircular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08223','iglesia','Iglesia de San Lorenzo Savall','Templo parroquial de factura barroca del siglo XVIII que presenta una fachada neoclásica de paramentos enlucidos con portalada de cantería moldurada, una amplia nave con capillas laterales y una recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08223','monumento','Masía de Oliver (Cal Oliver)','Gran heredad fortificada documentada desde el siglo XIV que exhibe una estructura tradicional de tres cuerpos con muros de mampostería regular, ventanas de dintel gótico labrado en arenisca y un portal dovelado de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90586','monumento','Núcleos de población de Sant Martí d''Albars','El término municipal incluye los siguientes núcleos de población: Beulaigua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90586','iglesia','Iglesia de San Martín d''Albars','Templo parroquial de estilo barroco rural construido en el siglo XVIII que destaca por su fachada simétrica de sillería vista con portalada clasicista moldurada, un gran óculo central y un esbelto campanario de torre cuadrangular con remate piramidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90586','monumento','Puente de San Martín (Pont de Sant Martí)','Viaducto gótico del siglo XIV ejecutado en cantería regular que salva el cauce de la riera de Gavarresa mediante dos arcadas de medio','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08226','monumento','Núcleos de población de Sant Martí de Tous','El término municipal incluye los siguientes núcleos de población: Fillol y Sentfores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08226','monumento','Castillo de Tous','Fortaleza medieval del siglo X reconstruida como palacio residencial fortificado en el siglo XV que destaca por su imponente torre del homenaje de planta cuadrada ejecutada en sillería caliza, sus almenas perimetrales y un gran patio de armas interior con arcos góticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08226','iglesia','Iglesia de San Martín de Tous','Templo de origen medieval reedificado a finales del siglo XIX en estilo historicista neorrománico que presenta una amplia nave única con capillas laterales, una fachada con portal en degradación bajo rosetón y una esbelta torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08226','ermita','Ermita de la Virgen de la Roqueta','Pequeño santuario rural del siglo XII que consta de una sola nave con bóveda de cañón, un ábside semicircular decorado exteriormente con motivos lombardos de arquillos ciegos y una espadaña de un solo vano sobre el hastial de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08226','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Sant Martí de Tous San Martín ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08227','iglesia','Iglesia de Santa María de la Bleda','Monumental templo románico del siglo XII que constituye uno de los ejemplos más ricos del arte románico del Penedès gracias a su majestuoso ábside semicircular decorado con lesenas lombardas, sus frisos esculpidos con gran virtuosismo y una fastuosa portada meridional de arquivoltas talladas con motivos geométricos y zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08227','monumento','Castillo de San Martín Sarroca (Conjunto Monumental de la Roca)','Fortaleza medieval del siglo X reconstruida como palacio residencial gótico en el siglo XIV que se alza sobre un cerro estratégico, destacando sus murallas perimetrales de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08229','iglesia','Iglesia y Torre de San Julián de Coaner','Excepcional conjunto medieval integrado por un templo del románico lombardo del siglo XI de tres naves con bóvedas de arista y decoración exterior de arquillos ciegos, flanqueado por una imponente torre de defensa románica exenta de planta circular y sillería perfecta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08229','monumento','Observatorio Astronómico y Castillo de Castelltallat','Ruinas de una estratégica fortaleza militar medieval del siglo X erigida sobre una cresta rocosa de la que perviven los cimientos de la torre del homenaje y tramos de muros,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08229','iglesia','Iglesia de San Mateo de Bages','Edificio religioso románico profundamente reformado en el siglo XVIII bajo cánones barrocos que mantiene su planta original, destacando su portada clasicista moldurada de cantería y una robusta torrecampanario que corona el núcleo fortificado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','monumento','Castillo de Ribes (Torre de Bell-lloc)','Fortaleza medieval documentada desde el siglo X de la que destaca su imponente y esbelta torre del homenaje cilíndrica ejecutada con un aparejo regular de sillería calcárea, la cual conserva saeteras defensivas y un arco de medio punto en su acceso original elevado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','iglesia','Iglesia Vieja de San Pedro','Templo de base medieval con reformas góticas y barrocas que presenta una estructura fortificada con muros de mampostería basta y contrafuertes robustos, hoy convertida en un espacio cultural singular tras la edificación del nuevo templo parroquial modernista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','monumento','Masía de Can Marcer de la Penya','Gran explotación vitivinícola tradicional e indiana estructurada a partir del siglo XVII que presenta un cuerpo residencial con galerías solanas de aire clásico, portales dovelados de piedra caliza y amplias dependencias destinadas a la crianza de vinos del Garraf.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','monumento','Red de Casas de Americanos (Casas de Indianos)','Conjunto de palacetes residenciales de finales del siglo XIX repartidos por el casco urbano que exhiben fachadas historicistas y eclécticas con barandillas de hierro forjado ondulantes, esgrafiados florales y frondosos jardines con palmeras tropicales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Sant Martí de Tous San Martín ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','monumento','Pueblos en Barcelona Sant Mateu de Bages Sant Mateu de Bages','Pueblos en Barcelona Sant Mateu de Bages Sant Mateu de Bages es el municipio más grande de la comarca del Bages. Se sitúa al este del río Cardener y se...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','monumento','Pueblos en Barcelona Es una villa que comparte llanuras y imponentes montañas que','Pueblos en Barcelona Es una villa que comparte llanuras y imponentes montañas que se levantan vertiginosamente como son los Cingles de Bertí. También t...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08232','palacio','Palacio de los Marqueses de Llió','Residencia señorial de origen gótico construida en el siglo XIV que destaca por su fachada de sillería caliza regular, sus ventanas geminadas con arcos conopiales finamente labrados y un patio de armas central con galerías de arcos apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08232','iglesia','Iglesia de San Pedro de Riudebitlles','Templo de base románica profundamente reformado en el siglo XVII en estilo barroco que exhibe una portada clasicista con pilastras molduradas, una nave única con capillas laterales y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08232','monumento','Molino de la Villa (Molí de la Vila)','Antiguo complejo papelero preindustrial del siglo XVIII situado junto a la riera de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08234','monumento','Núcleos de población de Sant Pere de Vilamajor','El término municipal incluye los siguientes núcleos de población: Bruguers, Cànoves y Santa Susanna de Vilamajor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08234','palacio','Torre Roja (Campanario del Palacio Condal)','Monumental torre románica de planta cuadrangular y veinticinco metros de altura construida en el siglo XI con sillares de piedra arenisca rojiza local que constituía la estructura de defensa principal del desaparecido palacio de los condes de Barcelona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08234','iglesia','Iglesia de San Pedro de Vilamajor','Templo parroquial gótico tardío del siglo XVI levantado sobre los restos del recinto condal que presenta una amplia nave con bóvedas de crucería estrellada, un portal renacentista clasicista y recios contrafuertes exteriores exentos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08234','ermita','Ermita de Santa Susana de Vilamajor','Pequeña capilla románica del siglo XII situada en pleno macizo del Montseny que muestra una sola nave con bóveda de cañón apuntada, un ábside semicircular liso orientado a levante y una espadaña de un solo vano ejecutada con aparejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08235','iglesia','Iglesia de San Pablo (Sant Pau)','Templo románico del siglo XI profundamente transformado en épocas gótica y barroca que destaca por conservar una cripta paleocristiana del siglo VI de planta absidial y muros de mampostería con hiladas de ladrillo plano de tradición romana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08235','iglesia','Iglesia Parroquial de San Jaime','Edificio religioso de estilo gótico tardío construido a finales del siglo XVI que presenta una estructura fortificada con muros de sillería granítica provistos de aspilleras para la defensa costera y una robusta torre-campanario de base circular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08235','monumento','Escuelas Públicas (Scolapias)','Edificio modernista proyectado por el arquitecto Ignasi Mas i Morell en 1910 que exhibe una fachada con profusa ornamentación de ladrillo visto, azulejería cerámica vidriada polícroma y grandes ventanales de arcos parabólicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08235','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Sant Pere Sallavinera Salavine...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08236','iglesia','Iglesia de San Quintín de Mediona','Templo parroquial de origen románico profundamente reformado en el siglo XVII bajo la estética barroca clasicista que exhibe una fachada de sillería caliza vista con portada moldurada, una nave única con capillas laterales y una robusta torre-campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08236','monumento','Castillo de Sant Quintí','Caserón señorial fortificado del siglo XIII reconstruido en época gótica que conserva notables tramos de sus murallas de mampostería regular, portales dovelados de arco de medio punto y ventanas conopiales talladas en piedra arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08236','monumento','Las Fuentes del Mach (Les Fonts del Mach)','Entorno natural e hidráulico protegido que cuenta con antiguas canalizaciones de riego medievales, azudes de piedra basta y balsas de decantación que atestiguan el aprovechamiento tradicional del agua en el Penedès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08237','iglesia','Iglesia de San Quirico de Besora','Templo edificado en el siglo XVIII por la saga de arquitectos Morató en estilo barroco con líneas neoclásicas que presenta una amplia nave longitudinal con capillas intercomunicadas, una fachada sobria','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08237','monumento','Puente de Hierro (Pont de Ferro)','Estructura civil e industrial construida a principios del siglo XX sobre el río Ter que constituye un notable ejemplo de la arquitectura del hierro remachado al salvar el cauce mediante un audaz arco metálico rebajado sustentado sobre potentes estribos de hormigón y sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08238','monumento','Núcleos de población de Sant Quirze del Vallès','El término municipal incluye los siguientes núcleos de población: Les Fonts.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08238','iglesia','Iglesia de San Quirico y Santa Julita','Templo parroquial de base románica profundamente modificado en el siglo XVII bajo los cánones del barroco tardío que conserva de su fábrica medieval un ábside semicircular de sillería basta y presenta una fachada con portada moldurada flanqueada por una recia torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08238','monumento','Masía de Can Barra','Gran explotación agropecuaria tradicional documentada desde el siglo XVII que funciona como equipamiento municipal, caracterizada por su volumetría de tres cuerpos con tejado a dos aguas, un gran portal dovelado de arco de medio punto y ventanales con dinteles de cantería labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08238','ermita','Ermita de San Feliu de Canovelles','Pequeño santuario románico del siglo XI emplazado en su entorno que muestra una sola nave con bóveda de cañón, un ábside semicircular liso orientado a levante y una espadaña de dos vanos ejecutada en sillarejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08240','monumento','Núcleos de población de Sant Sadurní d''Anoia','El término municipal incluye los siguientes núcleos de población: Monistrol d''Anoia, Can Benet de la Coma y Can Catassús.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08240','monumento','Cavas Codorníu','Monumental conjunto industrial modernista diseñado por el arquitecto Josep Puig i Cadafalch entre finales del siglo XIX y principios del XX que destaca mundialmente por su fastuoso porche de expedición con arcos parabólicos de ladrillo visto, sus bóvedas de estilo catalán y sus kilómetros de galerías subterráneas excavadas en sillería calcárea para la crianza del cava.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08240','monumento','Cavas Freixenet','Complejo arquitectónico edificado en 1927 por el arquitecto Josep Ros i Ros que combina una fachada de estética barroca clasicista con ornamentaciones modernistas de azulejería polícroma, grandes ventanales de aire palaciego y majestuosos salones de recepción institucional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08240','iglesia','Iglesia de San Sadurní','Templo parroquial de origen medieval profundamente reformado en el siglo XVI en estilo gótico tardío que conserva una monumental torre-campanario de planta octogonal del siglo de piedra regular con ventanales calados y una portada modificada en el periodo barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08240','monumento','Casa de la Villa','Edificio consistorial de líneas eclécticas e historicistas inaugurado a finales del siglo XIX que exhibe un balcón presidencial sostenido por ménsulas ornamentadas, ventanales con molduras de inspiración clasicista y un remate perimetral con balaustrada pétrea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08241','iglesia','Iglesia de San Sadurní de Osormort','Templo románico del siglo XI edificado con un aparejo regular de sillarejo calizo que consta de una sola nave con bóveda de cañón, un ábside semicircular decorado exteriormente con arcuaciones ciegas y lesenas de estilo lombardo, y una recia torre-campanario exenta levantada en centurias posteriores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08241','monumento','Masía de Masferrer','Gran caserón solariego tradicional de alta montaña estructurado a partir del siglo XVI mediante','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08262','ermita','Ermita de la Virgen de Castellet','Pequeño santuario románico del siglo XII emplazado de forma espectacular sobre una colina rocosa adosado a los restos del antiguo castillo medieval de la localidad, caracterizado por su austera planta de nave única con ábside semicircular liso y una espadaña de un solo vano construida con aparejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08262','iglesia','Iglesia de San Vicente de Castellet','Templo parroquial de factura contemporánea levantado tras la Guerra Civil que incorpora un esbelto campanario exento de líneas historicistas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08262','monumento','Can Soler','Antigua heredad rural e industrial construida a finales del siglo XIX que muestra una fachada de ladrillo visto combinada con mampostería regular, grandes ventanales de arcos rebajados y un conjunto de naves anexas destinadas originalmente a la producción textil de la comarca del Bages.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08262','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Sant Sadurní d''Anoia Sant Sadurní d''Osormort Nombre en castellano Sa...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08264','iglesia','Iglesia de San Vicente de Montalt','Templo parroquial de estilo gótico tardío del siglo XVI que presenta una amplia nave con bóveda de crucería, una fachada sobria con portalada renacentista de sillería granítica y una recia torre-campanario cuadrangular que hacía funciones de vigía costera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08264','monumento','Torre de Can Valls','Torre de defensa contra la piratería berberisca erigida en el siglo XVI de planta circular y sillería regular que conserva saeteras, ménsulas del desaparecido matacán y se integra en un frondoso parque urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08264','monumento','Casal de l''Alis','Mansión residencial modernista y ecléctica de principios del siglo XX que exhibe una fachada con ornamentación de esgrafiados geométricos, ventanales con molduras caladas y amplias balconadas con barandillas de hierro forjado artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08265','monumento','Núcleos de población de Sant Vicenç de Torelló','El término municipal incluye los siguientes núcleos de población: Vila-seca y Borgonyà.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08265','monumento','Colonia Industrial de Borgonyà (Colonia de los Ingleses)','Espectacular complejo urbanístico y textil fundado en 1895 por la empresa escocesa Coats Fabra que destaca por su trazado de casitas unifamiliares de ladrillo visto al estilo británico, su iglesia neogótica, sus naves diáfanas de grandes luces y su imponente chimenea industrial troncocónica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08265','monumento','Castillo de Torelló','Ruinas de una estratégica fortaleza medieval del siglo IX emplazada sobre una cresta rocosa de las que subsisten los potentes cimientos de una torre cilíndrica de mampostería basta y vestigios de muros perimetrales aglutinados por mortero de cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08265','iglesia','Iglesia de San Vicente','Templo de base románica profundamente transformado en época barroca que mantiene de su fábrica original del siglo XI un ábside semicircular con decoración de estilo lombardo y lesenas de piedra arenisca local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08263','iglesia','Iglesia de San Vicente','Templo parroquial de origen medieval reedificado a principios del siglo XVIII en estilo barroco clasicista que muestra una fachada de paramentos enlucidos con un portal moldurado de cantería, una amplia nave con capillas laterales y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08263','monumento','Can Comamala','Edificio consistorial de estética modernista construido a principios del siglo XX que exhibe una fachada ricamente ornamentada con azulejería cerámica vidriada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08263','monumento','Fornos Romanos de Can Pedrerol','Yacimiento arqueológico musealizado del siglo I d.C. que conserva las estructuras circulares de piedra y arcilla de dos grandes hornos destinados a la producción de ánforas y materiales cerámicos para las villas vitivinícolas imperiales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08244','monumento','Núcleos de población de Santa Coloma de Cervelló','El término municipal incluye los siguientes núcleos de población: Colonia Güell.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08244','monumento','Cripta de la Colonia Güell','Obra cumbre de la historia de la arquitectura universal proyectada por Antoni Gaudí en 1898 y declarada Patrimonio de la Humanidad por la UNESCO que destaca por sus audaces columnas de piedra basáltica inclinadas, sus muros de ladrillo recocido integrado orgánicamente en el pinar, sus bóvedas de aristas hiperbólicas y sus espectaculares vitrales polícromos con formas de alas de mariposa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08244','monumento','Colonia Güell (Conjunto Urbanístico Industrial)','Complejo industrial textil de finales del siglo XIX proyectado por arquitectos modernistas como Francesc Berenguer y Joan Rubió que constituye un conjunto histórico impecable con naves de hilatura de ladrillo visto, la escuela neogótica, el centro parroquial y las viviendas obreras de fachadas esgrafiadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08244','monumento','Torre Salbana','Torre de defensa medieval fortificada documentada desde el siglo X que presenta una estructura de planta circular ejecutada en sillería de piedra calcárea local con saeteras, almenas perimetrales y ventanas geminadas de traza gótica añadidas en centurias posteriores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08244','iglesia','Iglesia de Santa Coloma','Templo de base medieval profundamente reformado en el siglo XVIII bajo el influjo del barroco rural que exhibe una fachada de mampostería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08245','monumento','Torre Balldovina','Antigua torre de defensa medieval del siglo XI de planta circular y sillería regular que fue reformada e integrada en un palacete modernista a principios del siglo XX, sirviendo actualmente como museo municipal para custodiar los hallazgos arqueológicos de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08245','iglesia','Iglesia de Santa Coloma (Iglesia Mayor)','Monumental templo de estilo neogótico construido a principios del siglo XX por el arquitecto Francesc Berenguer i Mestres que destaca por su esbelto campanario de aguja piramidal, su fachada con un gran rosetón de tracería calada y sus ventanales apuntados con vitrales polícromos. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08245','monumento','Yacimiento Arqueológico del Puig Castellar','Asentamiento layetano de la Edad del Hierro (siglos VI al III a.C.) situado en la cumbre del cerro homónimo que conserva las plantas de piedra de sus viviendas estructuradas en terrazas, silos de almacenaje y tramos de la muralla defensiva perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08246','iglesia','Iglesia de Santa Eugenia de Berga','Excepcional joya del románico lombardo del siglo XI que presenta una planta de cruz latina con tres ábsides semicirculares decorados con dobles arquillos ciegos y lesenas, coronada sobre el crucero por un soberbio cimborrio octogonal y un campanario de torre de tres pisos con ventanas geminadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08246','monumento','Masía de Sala d''Heures','Gran complejo señorial e historicista de finales del siglo XIX edificado sobre una antigua casa fuerte medieval que exhibe un palacio de inspiración francesa con torres angulares de tejados apuntados de pizarra rústica, suntuosos salones nobles y un frondoso jardín romántico de diseño axial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08247','iglesia','Iglesia de Santa Eulalia de Riuprimer','Templo de origen románico profundamente transformado en el siglo XVIII bajo las directrices del estilo barroco clasicista que conserva de su fábrica primitiva una portada meridional moldurada y destaca por su imponente fachada con gran óculo central y un esbelto campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08247','monumento','Masía de Torrental (Mas Torrental)','Gran explotación agrícola tradicional documentada desde el Medievo que presenta una volumetría de tres cuerpos con muros de mampostería basta y sillares de arenisca en los ángulos, un monumental portal dovelado de arco de medio punto y un reloj de sol esgrafiado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08248','iglesia','Iglesia de Santa Eulalia de Ronçana','Templo parroquial reedificado en el siglo XVIII en estilo barroco rural con líneas neoclásicas que muestra una amplia nave longitudinal con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08248','monumento','Masía de Can Burguès','Antigua heredad agrícola tradicional estructurada a partir del siglo XVI que presenta un cuerpo residencial con portal de arco de medio punto con grandes dovelas de piedra caliza, ventanas con dinteles renacentistas protegidos por repisas molduradas y dependencias anexas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08248','iglesia','Santa Coloma de Gramanet El templo','Santa Coloma de Gramanet El templo fue proyectado y sus obras, en parte, dirigidas por Francesc d''Assís','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08248','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Santa Coloma de Gramenet Santa...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08249','iglesia','Iglesia de Santa Fe','Templo parroquial de factura barroca rural edificado en el siglo XVII sobre cimientos medievales que presenta una planta de nave única con capillas laterales, una fachada sencilla de paramentos enlucidos con portalada de piedra caliza moldurada y un campanario cuadrangular de remate piramidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08249','monumento','Masía de Can Puig','Gran heredad agrícola tradicional del Penedès estructurada a partir del siglo XVI mediante muros de mampostería basta que exhibe un portal de arco de medio punto dovelado, ventanas con repisas de arenisca labrada y bodegas anexas destinadas a la producción vinícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08250','monumento','Núcleos de población de Santa Margarida de Montbui','El término municipal incluye los siguientes núcleos de población: El Saió y Coll del Guix.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08250','iglesia','Iglesia de Santa María de la Tossa de Montbui','Excepcional templo prerrománico y románico inicial del siglo X situado en la cumbre de la montaña que destaca por su planta basilical de tres naves separadas por toscas arcadas de medio punto sobre pilares cilíndricos, tres ábsides semicirculares perfectos y muros de grueso sillarejo calizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08250','monumento','Castillo de Montbui (La Tossa)','Ruinas consolidadas de una estratégica fortaleza defensiva militar del siglo X adosadas a la iglesia de las que subsiste una imponente torre de defensa de planta rectangular con gruesos muros de mampostería basta asentados directamente sobre la roca viva de la cumbre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08250','iglesia','Iglesia Parroquial de Santa Margarida (Núcleo Urbano)','Edificio religioso de época barroca (siglo XVII) edificado con aparejo de mampostería regular que muestra una amplia nave longitudinal, una portada clasicista flanqueada por pilastras y una recia torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90588','monumento','Núcleos de población de Santa Margarida i els Monjos','El término municipal incluye los siguientes núcleos de población: La Ràpita y Els Monjos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90588','monumento','Castillo de Penyafel','Antigua fortaleza medieval documentada desde el siglo X y reformada en el siglo XVII como caserón residencial fortificado que destaca por su torre de defensa cilíndrica, sus murallas de sillería caliza y una capilla románica adosada dedicada a las Santas Algas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90588','monumento','Molino del Foix','Antiguo complejo hidráulico harinero de origen medieval reconstruido en el siglo XVIII que constituye un notable exponente preindustrial al conservar sus canales','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90588','iglesia','Iglesia de San Sadurní de Penyafel','Pequeño santuario románico del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante sin ornamentación exterior y un campanario de espadaña de dos vanos ejecutado en sillarejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90588','monumento','Refugio Antiaéreo del Aeródromo de la Ràpita','Estructura de defensa pasiva de la Guerra Civil Española construida en 1938 mediante galerías subterráneas de hormigón aligerado que conserva los accesos escalonados, los respiraderos de fundición de hierro y los pasillos de protección contra bombardeos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08253','monumento','Castillo de Besora','Ruinas de una monumental e histórica fortaleza medieval del siglo IX emplazada sobre un espectacular risco rocoso de las que subsisten tramos notables de muros de sillería de piedra caliza regular, los cimientos de la gran torre del homenaje y restos de la iglesia románica de Santa María.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08253','iglesia','Iglesia de Santa Maria de Besora (Núcleo Urbano)','Templo parroquial de estilo barroco clasicista construido en el siglo XVIII para sustituir a la iglesia del castillo que presenta una fachada simétrica de cantería vista con portalada moldurada, un gran óculo central y un esbelto campanario de torre de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08253','ermita','Ermita de San Miguel de Llagostera','Pequeño oratorio rural de origen románico modificado en el siglo XVII que presenta una planta de cajón con muros de mampostería basta, un porche delantero techado a dos aguas para refugio de los fieles y una espadaña de un solo ojo sobre el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08253','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Santa Maria de Besora Santa Ma...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08254','iglesia','Santuario de la Virgen de Cabrera','Templo mariano erigido en el siglo XVIII sobre los restos de un castillo medieval emplazado en la cumbre de un espectacular risco de la cordillera Transversal, caracterizado por su sólida fábrica de sillería de piedra calcárea adaptada a la alta montaña y una hospedería anexa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08254','iglesia','Iglesia de San Martín Sescorts','Edificio religioso románico del siglo XI que presenta una planta de nave única con un bellísimo ábside semicircular decorado exteriormente con arcuaciones ciegas y lesenas lombardas, ejecutado con hiladas regulares de sillarejo calizo cementado con cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08254','monumento','Puente de la Gorga (Pont de la Gorga)','Viaducto preindustrial construido en el siglo XVIII con aparejo regular de piedra arenisca local que salva el cauce de la riera mediante un arco de medio punto de gran luz asentado sobre los muros naturales del desfiladero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08255','iglesia','Iglesia de Santa María de Martorelles','Templo de base medieval profundamente transformado en época barroca que presenta una fachada enlucida muy sobria con portal adintelado de cantería, muros exteriores de mampostería basta y una torre-campanario cuadrangular rematada por un cuerpo octogonal posterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08255','monumento','Dolmen de Castellruf','Monumento megalítico del Neolítico final emplazado en la cordillera de Marina que conserva su cámara sepulcral delimitada por grandes losas de piedra granítica hincadas verticalmente en el terreno, rodeada por vestigios del túmulo circular original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08255','monumento','Núcleos de población de Santa Maria de Merlès','El término municipal incluye los siguientes núcleos de población: San Martín de Biure y San Pablo de Pinós.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08255','iglesia','Iglesia de Santa María de Merlès','Templo parroquial de factura barroca (siglo XVII) edificado con sillería regular sobre un oratorio medieval que destaca por su portalada neoclásica moldurada flanqueada por pilastras y por su imponente campanario de torre que domina el valle del río Merlès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08255','monumento','Puente de Merlès (Pont de Santa Maria)','Infraestructura civil de origen medieval reconstruida en el siglo XVIII mediante tres arcadas de medio punto de luces desiguales ejecutadas en cantería de piedra arenisca, la cual salva el cauce fluvial aprovechando las formaciones rocosas naturales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08255','iglesia','Iglesia de San Martín de Biure','Pequeño santuario románico del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante sin ornamentación exterior y una espadaña de dos vanos construida con aparejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08259','iglesia','Iglesia de Santa María de Palautordera','Templo parroquial de estilo gótico tardío del siglo XVI profundamente reformado que destaca por su estructura de muros fortificados con aspilleras de defensa, contrafuertes robustos exteriores y una monumental portada renacentista de sillería granítica gálica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08259','monumento','Torre de San Sebastián','Estructura defensiva medieval de planta circular construida con aparejo de mampostería basta y mortero de cal calavera que servía de torre de vigía para el control de las vías tradicionales de acceso al macizo del Montseny.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08259','monumento','Campanario Exento (Torre de las Horas)','Antigua torre de vigía del desaparecido palacio condal que fue reconvertida en campanario público civil durante las centurias barrocas, mostrando muros de sillería basta con remate superior de forja artística para el albergue de las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08259','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Santa Maria de Palautordera Sa...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08258','iglesia','Iglesia de San Vicente de Vilarassau','Templo románico del siglo XII edificado en sillería regular caliza que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular decorado exteriormente con arcuaciones ciegas y una notable portada meridional con arquivoltas molduradas sobre capiteles esculpidos con motivos vegetales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08258','monumento','Castillo de Oló','Ruinas de una monumental fortaleza medieval documentada desde el siglo X emplazada sobre un cerro escarpado de las que subsisten potentes lienzos de la muralla perimetral de mampostería basta, los cimientos de la gran torre del homenaje de planta circular y restos de la capilla románica de Santa María.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08258','iglesia','Iglesia de San Juan de Oló','Edificio religioso de origen medieval reconstruido íntegramente en el siglo XVII bajo los cánones del barroco rural que exhibe una fachada de paramentos enlucidos con portalada de cantería moldurada y una recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08260','monumento','Núcleos de población de Santa Perpètua de Mogoda','El término municipal incluye los siguientes núcleos de población: Mogoda y Santiga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08260','iglesia','Castillo e Iglesia de Santa María de Santiga','Conjunto monumental medieval integrado por una iglesia románica del siglo XII de nave única con ábside semicircular liso y un caserón señorial fortificado del siglo XIV reconstruido en época gótico-renacentista con muros de sillería basta y portales dovelados de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08260','monumento','Granja Soldevila','Suntuoso complejo agropecuario e industrial de estética modernista y ecléctica construido a finales del siglo XIX sobre una antigua masía medieval que exhibe un palacete residencial con torres angulares de tejados apuntados, ventanas con molduras de ladrillo visto y ornamentaciones de azulejería cerámica polícroma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08260','iglesia','Iglesia de Santa Perpetua de Mogoda','Templo parroquial de origen románico profundamente reformado en las centurias XVII y XVIII en estilo barroco que conserva de su fábrica primitiva los muros perimetrales de mampostería y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08261','monumento','Torre de Can Bonet d''Avall','Torre de defensa contra la piratería berberisca erigida en el siglo XVI de planta circular y sillería regular de granito que conserva saeteras, ménsulas del desaparecido matacán superior y se halla integrada de forma pintoresca en una masía tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08261','iglesia','Capilla de Santa Susanna','Pequeño oratorio de origen medieval profundamente transformado en época barroca rural que presenta una arquitectura popular muy sobria con muros de mampostería basta enlucida, un porche delantero techado a dos aguas para refugio de los fieles y una sencilla espadaña de un solo vano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08261','monumento','Masía de Can Ratés','Gran heredad agrícola fortificada estructurada a partir del siglo XVI que cuenta con una esbelta torre de defensa cilíndrica de mampostería regular, un gran portal dovelado de medio punto en piedra caliza local y un gran patio de armas interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90589','iglesia','Iglesia de San Pedro d''Or (Sant Pere d''Or)','Monumental templo gótico del siglo XIV construido en sillería caliza regular que destaca por su amplísima nave única con capillas laterales entre contrafuertes y por conservar una soberbia portada románica meridional del siglo XII con un tímpano','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90589','monumento','Recinto Amurallado de Santpedor','Vestigios del sistema defensivo medieval del siglo XIV del que subsisten tramos notables de cortina de sillería basta integrados en el casco urbano y portales de acceso monumentales de arco apuntado como el Portal de San Francisco y el Portal de Berga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90589','ermita','Ermita de San Francisco (Sant Francesc)','Ruinas consolidadas de un antiguo convento e iglesia del siglo XVII reconvertidas de forma vanguardista en auditorio municipal que conserva la estructura barroca de su nave única y capillas laterales integrada con cerramientos contemporáneos de hormigón aligerado y paramentos acristalados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90590','monumento','Castillo de Sentmenat','Monumental fortaleza medieval documentada desde el siglo XI y transformada en palacio residencial fortificado durante los siglos XIV y XV que destaca por sus potentes murallas de sillería caliza regular, sus almenas perimetrales, sus ventanas de tracería gótica flamígera y un impresionante patio de armas central con galerías de arcos rebajados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90590','iglesia','Iglesia de San Menardo','Templo parroquial de base románica profundamente reconstruido en el siglo XVIII en estilo barroco clasicista que muestra una amplia nave','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90590','monumento','Campanario Románico de San Jaime de Castellar','Torre de vigía y campanario exento del siglo XII que constituye el único testimonio en pie de un desaparecido cenobio medieval, caracterizado por sus tres pisos de planta cuadrada ejecutados con aparejo regular de sillarejo calizo y ventanas geminadas de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08269','iglesia','Iglesia de Santa María de Seva','Joya del románico lombardo del siglo XI que presenta una planta de nave única con ábside semicircular liso orientado a levante, destacando exteriormente por su soberbio y esbelto campanario de torre de planta cuadrada y cuatro pisos de altura provistos de dobles ventanas geminadas y frisos de arquillos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08269','monumento','Masía de El Sors (Mas El Sors)','Gran caserón solariego tradicional documentado desde el siglo XIV que exhibe una volumetría fortificada de tres cuerpos con tejado a dos aguas, un monumental portal dovelado de arco de medio punto en piedra arenisca local y ventanas con alféizares de época renacentista labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08269','iglesia','Capilla de San Roque','Pequeño santuario rural barroco edificado en el siglo XVIII con aparejo rústico de piedra de montaña que muestra una planta de cajón muy sobria, un porche delantero techado a dos aguas para refugio de fieles y una espadaña de un solo ojo centrada sobre el hastial de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','iglesia','Iglesia de San Bartolomé y Santa Tecla','Emblemático templo de traza barroca tardía (siglo XVII) emplazado de forma espectacular sobre un baluarte rocoso que domina el frente marítimo de la villa, caracterizado por su fachada escalonada de sillería calcárea vista, su interior de tres naves de gran altura y dos esbeltas torres-campanario asimétricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','palacio','Palacio de Maricel (Palau de Maricel)','Suntuoso complejo monumental e historicista proyectado por el arquitecto Miquel Utrillo a principios del siglo XX que fusiona elementos del gótico civil, el Renacimiento y el mudéjar mediante la integración de portaladas esculpidas, galerías porticadas con vistas al mar y salones nobles revestidos de azulejería polícroma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','monumento','Cau Ferrat (Casa-Museo de Santiago Rusiñol)','Antiguo taller y vivienda del célebre pintor modernista configurado a finales del siglo XIX mediante la unión de dos casas de pescadores del siglo XIV, la cual exhibe ventanas góticas caladas recuperadas de antiguos palacios, una fastuosa colección de forja artística medieval y obras de arte pictórico universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','monumento','Hospital de San Juan Bautista','Complejo asistencial de estética modernista inaugurado en 1912 obra del arquitecto Josep Font i Gumà que destaca por su disposición de pabellones exentos de ladrillo visto combinados con mampostería regular, sus amplios ventanales de arcos parabólicos y una esbelta torre de planta ochocavada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08023','monumento','Castillo de Garraf','Casa fuerte señorial fortificada del siglo XIV situada en el parque natural de la que subsisten tramos notables de muros de mampostería basta y una gran torre de defensa cuadrangular que servía para el control del paso estratégico de las costas meridionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08272','iglesia','Iglesia de San Pedro de Sora','Templo parroquial de origen románico profundamente transformado en el siglo XVIII en estilo barroco rural con líneas neoclásicas que presenta una amplia nave única con capillas intercomunicadas, una fachada de paramentos enlucidos con portal de cantería moldurada y una recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08272','monumento','Masía de Casanoves','Antigua explotación agropecuaria de montaña estructurada a partir del siglo XVI mediante aparejo rústico que exhibe un portal de arco de medio punto con grandes dovelas de piedra arenisca local, ventanas de repisa moldurada de inspiración renacentista y dependencias anexas para la producción ganadera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08273','monumento','Núcleos de población de Subirats','El término municipal incluye los siguientes núcleos de población: Lavern, Ordal, Sant Pau d''Ordal y Torre-ramona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08273','iglesia','Castillo de Subirats e Iglesia de San Pedro','Fortaleza medieval originaria del siglo X erigida sobre una imponente cresta rocosa que conserva los alzados de su torre del homenaje de planta rectangular, tramos de muralla con aspilleras de sillería caliza y la primitiva iglesia románica de una nave con ábside liso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08273','monumento','Conjunto Histórico de Torre-ramona','Caserón señorial y palacio fortificado de traza gótico-renacentista edificado en el','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08273','iglesia','Iglesia de San Juan Salerm','Pequeño santuario románico del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante con decoración exterior lombarda y una espadaña de dos ojos que corona la fachada occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08278','monumento','Castillo de Taradell (Castell dels Moures)','Ruinas de una monumental fortaleza medieval del siglo X emplazada sobre una espectacular aguja rocosa de las que subsiste un imponente muro arqueado de sillería caliza regular asentado de forma audaz sobre la piedra viva y restos de estancias abovedadas de almacenamiento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08278','iglesia','Iglesia de San Genís de Taradell','Templo parroquial barroco edificado en el siglo XVIII por la saga de arquitectos Morató que muestra una monumental fachada neoclásica de sillería de piedra arenisca local, un interior de tres naves y una recia torre-campanario de planta cuadrada de origen románico profundamente reformada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08278','monumento','Torre de Don Carlos (Torre de Don Carles)','Torre de vigía y defensa de planta circular construida en el siglo XVI mediante aparejo de mampostería regular con mortero de cal que conserva saeteras originales y ménsulas pétreas del desaparecido matacán superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90591','monumento','Núcleos de población de Tavèrnoles','El término municipal incluye los siguientes núcleos de población: Savassona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90591','iglesia','Iglesia de San Esteban de Tavèrnoles','Excepcional joya del románico lombardo del siglo XI que presenta una planta de nave única muy esbelta con bóveda de cañón, un ábside semicircular perfecto decorado con arcuaciones ciegas y lesenas de piedra caliza, y un soberbio campanario de torre de planta cuadrangular adosado al muro septentrional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90591','iglesia','Iglesia de San Pedro de Savassona','Templo románico del siglo XI profundamente reformado en época barroca que se alza junto a una gran peña rocosa, caracterizado por su ábside semicircular de sillería basta y por albergar en su término grabados rupestres prehistóricos antropomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90591','monumento','Castillo de Savassona','Caserón señorial e historicista levantado en el siglo XVII sobre las bases de una antigua casa fuerte medieval que exhibe muros perimetrales de mampostería regular, ventanas de cantería moldurada y portales dovelados de arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08024','monumento','Núcleos de población de Tavertet','El término municipal incluye los siguientes núcleos de población: San Bartolomé de las Cuadras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08024','monumento','Conjunto Histórico-Artístico de la Villa de Tavertet','Núcleo rural fortificado de origen medieval colgado sobre espectaculares acantilados de roca calcárea que destaca por la conservación impecable de sus masías tradicionales de los siglos XVI al XVIII, edificadas con muros de mampostería basta y ventanas con dinteles y alféizares de piedra arenisca labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08024','iglesia','Iglesia de San Cristóbal de Tavertet','Templo de origen románico del siglo XI modificado en el XII que presenta una planta de nave única con bóveda de cañón apuntada, un ábside semicircular decorado exteriormente con un friso de arcuaciones lombardas y una robusta torre-campanario de planta cuadrada con vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08024','iglesia','Iglesia de San Miguel de Sorerols','Excepcional ermita románica del siglo XII aislada en un promontorio boscoso que destaca por la pureza geométrica de su nave única, su ábside semicircular orientado al este con cornisa de canecillos lisos y muros ejecutados en sillería caliza regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08024','monumento','Torre de la Vall','Gran masía fortificada del siglo XVI de planta cuadrangular que cuenta con una esbelta torre de defensa exenta integrada en el conjunto residencial, portales de arco de medio punto dovelados y ventanas de repisa moldurada de inspiración renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90592','iglesia','Iglesia de San Martín de Teià','Templo parroquial de estilo gótico tardío del siglo XVI que presenta una amplia nave con bóveda de crucería, una fachada sobria con portalada renacentista de sillería granítica y una robusta torrecampanario cuadrangular que ejercía funciones de vigía contra la piratería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90592','monumento','Cella Vinaria (Yacimiento Romano de Vallmora)','Complejo arqueológico musealizado que conserva las estructuras de una gran explotación vinícola de época imperial con los cimientos de los prensados, las balsas de fermentación de opus signinum y réplicas de las colosales prensas de madera reconstruidas según los tratados de Catón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90592','monumento','Torre de los Diablos (Torre de Can Pasqual)','Estructura defensiva señorial del siglo XVI de planta circular ejecutada en mampostería regular y mortero de cal que conserva saeteras y las ménsulas del desaparecido matacán superior destinado a proteger el núcleo rural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90593','iglesia','Conjunto Monumental de las Iglesias de San Pedro (Seu d''Ègara)','Complejo paleocristiano y románico excepcional de los siglos V al XII único en Europa, integrado por las iglesias de San Pedro, Santa María y San Miguel, las cuales albergan pinturas murales al fresco altomedievales, ábsides de planta poligonal de herencia visigótica y una cripta subterránea soportada por columnas monolíticas con capiteles toscos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90593','monumento','Masía Freixa','Joya del modernismo catalán proyectada por el arquitecto Lluís Muncunill en 1907 que destaca mundialmente por su perfil sinuoso de arcos parabólicos, muros revestidos con mortero de cal blanca y una espectacular cubierta sinuosa cupulada que imita formas orgánicas de la naturaleza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90593','monumento','Vapor Aymerich, Amat i Jover (Museo de la Ciencia y de la Técnica de Cataluña)','Magna obra de la arquitectura industrial modernista diseñada por Lluís Muncunill en 1907, caracterizada por su colosal cubierta de dientes de sierra sostenida por 300 columnas de fundición de hierro y un imponente espacio diáfano que albergaba los telares mecánicos de lana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90593','iglesia','Castillo-Cartuja de Vallparadís','Fortaleza medieval del siglo XII convertida en monasterio cartujo en el siglo XIV que presenta muros de sillería caliza regular, un claustro central de dos pisos con arcadas apuntadas de gran pureza y salas capitulares cubiertas con bóvedas de crucería gótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90593','palacio','Torre del Palacio (Torre del Palau)','Único vestigio en pie del desaparecido castillo palacio de los condes de Barcelona de la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08283','iglesia','Iglesia de San Andrés del Castillo de Tona','Monumental templo románico del siglo XI emplazado de forma escarpada en la cumbre del cerro del castillo que presenta una sola nave muy esbelta con bóveda de cañón, un ábside semicircular perfecto decorado exteriormente con un friso de arcuaciones lombardas y una robusta torre-campanario adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08283','monumento','Castillo de Tona','Ruinas consolidadas de una estratégica fortaleza defensiva militar del siglo X de la que subsiste una imponente torre del homenaje de planta cuadrangular ejecutada con aparejo regular de gruesos bloques de piedra caliza cementados con mortero de cal calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08283','iglesia','Iglesia de Santa María del Barri','Edificio religioso románico del siglo XII modificado en época barroca que muestra una planta de nave única con capillas laterales entre contrafuertes robustos, una portada meridional de tres arquivoltas en degradación y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08283','monumento','Balneario Ullastres','Complejo hotelero y medicinal de estética modernista construido a finales del siglo XIX para el aprovechamiento de las aguas sulfurosas de la plana de Vic, caracterizado por sus pabellones con fachadas esgrafiadas, galerías porticadas románticas y un gran parque de diseño axial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08283','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Tiana Tiana 9110 Tona Tona 836...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08284','monumento','Núcleos de población de Tordera','El término municipal incluye los siguientes núcleos de población: Sant Pere de de Tordera, El Mas Móra y Ágora Park.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08284','iglesia','Iglesia de San Esteban de Tordera','Templo parroquial de origen románico profundamente reformado en el siglo XVI en estilo gótico tardío y ampliado en el siglo XVIII que destaca por su fachada de sillería vista con portada renacentista de líneas clásicas y por su recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08284','ermita','Ermita de San Ponce (Sant Ponç)','Pequeño santuario románico del siglo XI edificado en sillería regular caliza que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante sin ornamentación exterior y un campanario de espadaña de dos vanos sobre la fachada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08284','monumento','Can Fontrodona','Gran masía fortificada del siglo XVI de planta cuadrangular que cuenta con muros de mampostería regular, un monumental portal dovelado de arco de medio punto en piedra granítica, ventanas conopiales talladas en arenisca y restos de aspilleras de defensa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08025','iglesia','Iglesia de San Feliu de Torelló','Monumental templo edificado en el siglo XVII por la saga de arquitectos Morató que fusiona elementos del barroco tardío y el neoclásico, destacando su imponente fachada de sillería de piedra arenisca local, su interior de nave única de gran amplitud con capillas intercomunicadas y pinturas murales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08025','iglesia','Santuario de la Virgen de Rocapre','Centro de peregrinación de traza barroca edificado en el siglo XVIII sobre un oratorio medieval que muestra una sobria arquitectura clasicista con fachada enlucida, un interior cubierto con bóvedas de lunetos y una avenida ajardinada exenta con estaciones del Viacrucis de piedra tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08025','monumento','Museo de la Tornería (Museu de la Torneria)','Centro cultural ubicado en una antigua fábrica decimonónica que constituye una muestra primordial de la arqueología industrial de la comarca de Osona al conservar la maquinaria original, las correas de transmisión y las herramientas tradicionales destinadas al torneado de madera y cuerno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08286','monumento','Núcleos de población de La Torre de Claramunt','El término municipal incluye los siguientes núcleos de población: Vilanova d''Espoia, El Poal y Camaró.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08286','monumento','Castillo de la Torre de Claramunt','Monumental fortaleza medieval documentada desde el siglo XI y transformada en palacio residencial de estilo renacentista en el siglo XVI que destaca por su simétrica fachada de sillería caliza vista, sus ventanas con molduras clasicistas y una imponente torre de planta cuadrangular con almenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08286','iglesia','Iglesia de San Juan de la Torre de Claramunt','Templo de origen medieval reedificado en el siglo XVIII bajo las directrices del estilo barroco que exhibe una fachada de mampostería enlucida con portal de cantería moldurada flanqueada por pilastras, una nave longitudinal y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08286','iglesia','Iglesia de San Salvador de Vilanova d''Espoia','Edificio religioso románico del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado al este con decoración exterior lombarda de arquillos ciegos y un campanario de espadaña transformado posteriormente en torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08287','monumento','Núcleos de población de Torrelavit','El término municipal incluye los siguientes núcleos de población: Lavit, Terrassola, Els Casals y Can Rossell.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08287','iglesia','Iglesia de San Marcial de Terrassola','Templo románico del siglo XII edificado en sillería regular que presenta una planta de nave única con bóveda de cañón, un ábside semicircular decorado exteriormente con un friso de dientes de sierra y una hermosa portada meridional de tres arquivoltas en degradación soportadas por capiteles esculpidos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08287','iglesia','Iglesia de Santa María de Lavit','Edificio religioso de origen románico profundamente transformado en época barroca que conserva de su estructura del siglo XII la planta de nave única','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08287','monumento','Molino papelero de Can Font (Molí de Can Font)','Antiguo complejo industrial del siglo XVIII situado junto al río Bitlles que constituye un exponente de la fabricación tradicional de papel al conservar sus canales de derivación de agua, sus salas abovedadas de pilones y los tendederos de madera en los pisos superiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08287','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08288','monumento','Núcleos de población de Torrelles de Foix','El término municipal incluye los siguientes núcleos de población: Foix, Les Piles y Cal Miret.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08288','iglesia','Santuario de Nuestra Señora de Foix','Templo románico del siglo XII emplazado de forma espectacular sobre un risco escarpado que constituye el único resto íntegro del antiguo castillo de Foix, caracterizado por su planta de nave única con bóveda de cañón apuntada, su ábside semicircular decorado exteriormente con arcuaciones ciegas lombardas y una majestuosa torre-campanario que domina la cabecera del valle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08288','iglesia','Iglesia de San Ginés de Torrelles','Edificio religioso de época barroca (siglo XVIII) edificado con un recio aparejo de sillería vista que presenta una amplia nave con capillas laterales intercomunicadas, una portada de líneas clásicas molduradas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08288','monumento','Torres Altas (Torres Altes)','Ruinas de dos estructuras defensivas medievales de planta cuadrangular situadas en los pasos de montaña que conservan alzados notables de mampostería basta y saeteras originales destinadas al control militar del territorio del Penedès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08289','monumento','Núcleos de población de Torrelles de Llobregat','El término municipal incluye los siguientes núcleos de población: Can Güell, Cesalpina y Can Coll.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08289','iglesia','Iglesia de San Martín de Torrelles','Templo parroquial de origen medieval reedificado a principios del siglo XX en estilo historicista de inspiración neogótica que presenta una fachada monumental enlucida con un gran rosetón de tracería calada, portales de arcos apuntados en degradación y una esbelta torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08289','monumento','Masía de Can Coll','Gran explotación agrícola tradicional catalana estructurada a partir del siglo XVII mediante muros portantes de mampostería y mortero de cal que exhibe un gran portal dovelado de arco de medio punto en piedra caliza, ventanas con dinteles moldurados de arenisca y un gran reloj de sol esgrafiado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08290','monumento','Núcleos de población de Ullastrell','El término municipal incluye los siguientes núcleos de población: Ca n''Amat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08290','iglesia','Iglesia de Santa María de Ullastrell','Templo parroquial levantado a principios del siglo XX sobre una base neogótica e historicista que cuenta con una nave longitudinal, una fachada principal decorada con molduras de ladrillo visto, un gran óculo central y un esbelto campanario de torre cuadrangular rematado por una aguja piramidal de hierro forjado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08290','monumento','Masía de Can Curull','Antigua heredad rural documentada desde el siglo XVI que presenta la volumetría tradicional de tres cuerpos con tejado a dos aguas, muros exteriores de mampostería basta y ventanas con dinteles de cantería labrada de inspiración renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08291','monumento','Núcleos de población de Vacarisses','El término municipal incluye los siguientes núcleos de población: Torreblanca, Els Carps y Can Franc.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08291','monumento','El Castillo de Vacarisses (La Torrota)','Estructura defensiva medieval del siglo XI de la que subsiste una imponente torre de vigía de planta circular ejecutada en sillería de piedra caliza regular con mortero de cal, la cual corona un promontorio estratégico que domina el paso hacia la comarca del Bages.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08291','iglesia','Iglesia de San Pedro de Vacarisses','Templo parroquial del siglo XVIII edificado en estilo barroco de aire clasicista que muestra una amplia nave única con capillas laterales entre contrafuertes robustos, una fachada de paramentos enlucidos con portalada moldurada de cantería y una recia torrecampanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08291','monumento','Masía de Can Boada','Gran complejo agropecuario tradicional estructurado a partir del siglo XVI que presenta muros perimetrales de mampostería basta, un monumental portal dovelado de arco de medio punto de gran envergadura y ventanas de repisa moldurada protegidas por alféizares labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08291','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Vallbona d''Anoia Vallcebre Nombre en castellano Vallbona Vallcebre P...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08292','iglesia','Iglesia de San Bartolomé','Templo parroquial de origen medieval profundamente reformado en el siglo XVII bajo las directrices del barroco rural que presenta una fachada enlucida con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular ejecutada en piedra caliza local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08292','monumento','Cal Munguet','Gran masía tradicional del núcleo urbano estructurada a partir del siglo XVI mediante aparejo de mampostería basta que exhibe un portal de arco de medio punto dovelado, ventanas con repisas de arenisca labrada de inspiración renacentista y dependencias anexas destinadas a la producción agrícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08293','iglesia','Iglesia de Santa María de Vallcebre','Templo de base románica profundamente transformado en el siglo XVII en estilo barroco que exhibe muros de mampostería rústica con piedra de alta montaña, una fachada con porche cubierto tradicional y un campanario de torre de planta cuadrada con vanos de medio punto que domina el perfil de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08293','monumento','Yacimiento de Huellas de Dinosaurio de Fumanya','Espectacular paraje paleontológico musealizado del Cretácico Superior situado en su cuenca geológica que conserva miles','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08295','iglesia','Iglesia de San Mateo de Vallirana','Templo parroquial levantado a principios del siglo XIX en estilo neoclásico que exhibe una fachada monumental flanqueada por pilastras, un gran frontón triangular superior y una esbelta torre-campanario de planta octogonal con remate cupulado de azulejería vidriada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08295','monumento','Masia de Molí de Can Batlle','Antiguo complejo industrial y agropecuario del siglo XVII que funciona como centro de interpretación al conservar sus estructuras de mampostería, las canalizaciones de piedra basta, la balsa de decantación y los restos de la maquinaria de madera destinada a la molturación de grano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08296','monumento','Castillo de Vallromanes','Ruinas consolidadas de una monumental fortaleza medieval documentada desde el siglo X de la que subsisten potentes lienzos de muralla ejecutados en mampostería regular con mortero de cal y la base de su primigenia torre del homenaje de planta circular adaptada a la orografía de la colina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08296','iglesia','Iglesia de San Vicente de Vallromanes','Templo de origen románico profundamente reformado en el siglo XVII bajo la estética barroca que conserva de su fábrica medieval un ábside semicircular liso de sillería caliza, presentando una fachada occidental con portalada moldurada bajo un campanario de torre cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08296','monumento','Masía de Can Poal','Gran heredad agrícola tradicional estructurada a partir del siglo XVI que exhibe una volumetría de tres cuerpos con tejado a dos aguas, un monumental portal dovelado de arco de medio punto en piedra granítica local y ventanas conopiales talladas en arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08297','monumento','Núcleos de población de Veciana','El término municipal incluye los siguientes núcleos de población: Segur, Santa Maria del Camí, Montfalcó el Gros y Per領oles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08297','monumento','Castillo de Veciana','Ruinas de una estratégica fortificación militar del siglo X emplazada sobre una cresta rocosa de las que perviven los cimientos de la torre del homenaje de planta circular, tramos de la muralla defensiva perimetral y restos de estancias de almacenamiento de mampostería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08297','iglesia','Iglesia de Santa María de Jesús del Camí','Joya del románico del siglo XII edificada con un aparejo regular de bloques de piedra caliza que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante con cornisa de canecillos lisos y una espadaña de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08297','iglesia','Iglesia de San Pedro de Montfalcó','Edificio religioso románico que presenta una estructura fortificada muy singular al estar adosado a los muros de la antigua casa fuerte del núcleo, destacando su portal de arco de medio punto con grandes dovelas y su campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','monumento','Núcleos de población de Vic','El término municipal incluye los siguientes núcleos de población: Sentfores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','iglesia','Templo Romano de Vic','Monumental e impresionante estructura sacra del siglo II d.C. descubierta intacta en 1882 al haber estado embutida dentro de las murallas del castillo de los Moncada, la cual destaca mundialmente por su perfecta cella de sillería y su pórtico columnado con capiteles corintios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','catedral','Catedral de San Pedro de Vic','Magna basílica que fusiona estilos arquitectónicos desde el siglo XI hasta el XIX, célebre por albergar una imponente torre-campanario románica de planta cuadrada de seis pisos, una cripta medieval con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','monumento','Plaza Mayor (Plaça del Mercat)','Histórico espacio público porticado de traza medieval configurado por edificios de fachadas clasicistas, góticas y barrocas con pilastras de piedra tallada, la cual mantiene su pavimento de tierra compactada tradicional desde hace siglos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','monumento','Puente de Queralt (Pont de Queralt)','Viaducto románico del siglo XI edificado en cantería regular para salvar el cauce del río Mèder mediante cuatro arcos de medio punto provistos de potentes tajamares apuntados destinados a desviar las grandes avenidas fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08026','palacio','Palacio Episcopal','Residencia e institución eclesiástica gótica del siglo XIV profundamente reformada en los siglos XVII y XVIII que presenta un claustro central de arcos apuntados, portales dovelados de medio punto y amplias salas que custodian el tesoro y el archivo diocesano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08299','iglesia','Iglesia de San Juan de Vilada','Templo parroquial de origen románico profundamente transformado en el siglo XVII bajo cánones barrocos que exhibe muros de mampostería rústica con piedra caliza de alta montaña, una fachada con portalada neoclásica moldurada de cantería local y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08299','monumento','Castillo de Roset','Ruinas de una antigua fortaleza medieval del siglo XI emplazada de forma escarpada sobre un cerro boscoso del Berguedà de las que subsisten tramos notables de muros de contención perimetrales construidos con aparejo tosco cementado con cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08301','monumento','Torre del Baró','Mansión señorial de origen medieval construida en el siglo XII y profundamente reformada en las centurias góticas que presenta una imponente planta cuadrangular fortificada con sillería caliza regular, ventanas geminadas de tracería calada y un patio de armas perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08301','ermita','Ermita de Santa María de Sales','Pequeño santuario de base románica del siglo XII que destaca por albergar en su interior un excepcional conjunto de pinturas murales góticas al fresco y por su ábside semicircular liso edificado con aparejo rústico cementado con mortero de cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08301','monumento','Masía de Can Amat','Gran explotación agrícola tradicional del siglo XIX reconvertida en espacio cultural que exhibe una fachada de líneas neoclásicas con un gran reloj de sol esgrafiado, balconadas de forja artística y grandes salas cubiertas con techumbres de viguería noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08300','monumento','Núcleos de población de Viladecavalls','El término municipal incluye los siguientes núcleos de población: Can Tries, El Molinot y San Miguel de Toudell.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08300','iglesia','Iglesia de San Miguel de Toudell','Templo románico del siglo XII edificado en sillería regular que consta de una sola nave','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08300','iglesia','Iglesia Parroquial de San Martín','Edificio religioso barroco del siglo XVIII que muestra una sobria arquitectura clasicista con fachada de paramentos enlucidos, un portal de cantería moldurada flanqueada por pilastras y una recia torrecampanario de planta cuadrangular que corona el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08300','monumento','Masía de Can Boada de las Parentas','Antigua heredad agrícola tradicional estructurada a partir del siglo XVI mediante muros de mampostería basta que presenta un monumental portal dovelado de arco de medio punto en piedra local y ventanas con dinteles de arenisca labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08305','monumento','Núcleos de población de Vilafranca del Penedès','El término municipal incluye los siguientes núcleos de población: Moja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08305','iglesia','Basílica de Santa María de Vilafranca','Monumental templo gótico del siglo XIII que constituye el edificio histórico más señero de la capital del vino, caracterizado por su imponente nave única de gran anchura, su fachada principal con un colosal rosetón de tracería calada y una cripta del siglo XIV con un grupo escultórico tallado por Josep Llimona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08305','palacio','Palacio Real (Palau Reial - Museo de las Culturas del Vino de Cataluña)','Complejo palaciego del gótico civil construido en el siglo XIV que destaca por su fachada de sillería caliza vista provista de ventanas coronelas de arcos apuntados, su patio de armas central con majestuosas escalinatas de piedra y sus salas nobles abovedadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08305','palacio','Palacio Baltà','Residencia señorial fortificada del siglo XIV reconstruida en estilo gótico tardío que exhibe una fachada con almenas perimetrales, ventanas de tracería flamígera','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08305','iglesia','Convento de San Francisco (Sant Francesc)','Cenobio franciscano fundado en el siglo XIII que conserva una bellísima iglesia gótica de nave única con capillas laterales repletas de sepulcros heráldicos de la nobleza local y un claustro renacentista de líneas clasicistas muy sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08305','monumento','Casa Miró','Edificio residencial modernista proyectado por el arquitecto Santiago Güell en 1905 que destaca por su fachada ornamentada con profusos esgrafiados vegetales, suntuosas tribunas caladas y barandillas de hierro forjado con perfiles sinuosos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08306','iglesia','Iglesia Vieja de Santa María','Ruinas consolidadas de un templo parroquial de origen románico del siglo XI modificado en el periodo barroco que conservan alzados notables de sus muros de mampostería regular de piedra granítica local y la base del antiguo ábside semicircular rodeado por la vegetación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08306','monumento','Dolmen de la Piedra Arca (Dolmen de la Pedra Arca)','Sepulcro megalítico del Neolítico final emplazado en su término municipal que conserva su cámara funeraria delimitada por grandes losas de piedra local hincadas verticalmente en el terreno y restos del túmulo circular perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08306','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Vilalba Sasserra Villalba Sase...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08303','iglesia','Iglesia de San Román de Sau','Célebre templo románico del siglo XI edificado en sillería regular que presenta una sola nave con bóveda de cañón y un campanario de torre de planta cuadrada con ventanas geminadas lombardas, conocido internacionalmente por emerger de forma pintoresca entre las aguas del embalse de Sau según el nivel hídrico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08303','iglesia','Iglesia de Santa María de Vilanova de Sau','Templo parroquial de origen románico profundamente reformado en el siglo XVIII bajo los cánones del barroco clasicista que muestra una fachada de paramentos enlucidos con portada de cantería moldurada, una nave diáfana y una recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08303','monumento','Masía de Els Moros (Casal dels Moures)','Antigua casa fuerte señorial del siglo XIV de estilo gótico rural que conserva sus muros perimetrales de mampostería basta, ventanas de dintel calado talladas en piedra arenisca y portales dovelados de arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90594','iglesia','Iglesia de San Hilario de Vilanova del Camí','Templo parroquial reedificado en el siglo XVIII en estilo barroco rural sobre una estructura medieval anterior que presenta una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90594','monumento','Masía de Can Muset','Gran explotación agrícola tradicional estructurada a partir del siglo XVI mediante muros portantes de mampostería y mortero de cal que exhibe un gran portal dovelado de arco de medio punto en piedra caliza, ventanas con dinteles moldurados de arenisca y un gran reloj de sol esgrafiado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08902','iglesia','Iglesia de San Esteban de Vilanova del Vallès','Templo de origen románico profundamente transformado en el siglo XVI en estilo gótico tardío que exhibe una fachada con portal renacentista de sillería granítica, contrafuertes exteriores y una recia torre-campanario de planta cuadrada con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08902','monumento','Masía de Can Palau','Antigua heredad agrícola tradicional del Vallès estructurada a partir del siglo XVII que presenta la volumetría tradicional de tres cuerpos con tejado a dos aguas, muros exteriores de mampostería basta y ventanas con dinteles de cantería labrada de inspiración renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90026','monumento','Castillo de la Geltrú','Fortaleza medieval documentada desde el siglo XII y suntuosamente reconstruida en estilo gótico historicista a principios del siglo XX que destaca por sus potentes murallas de sillería caliza regular, sus almenas perimetrales, sus ventanas coronelas de arcos apuntados y un impresionante patio de armas central.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90026','monumento','Museo del Ferrocarril de Cataluña','Espectacular complejo de la arqueología industrial decimonónica emplazado en los antiguos talleres del ferrocarril que destaca por albergar una de las colecciones de locomotoras de vapor más completas de Europa, dispuestas alrededor de un puente giratorio de vía ancha original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90026','monumento','Biblioteca Museo Víctor Balaguer','Palacio de estética historicista y neoclásica inaugurado en 1884 que constituye una joya museística al conservar salones nobles decimonónicos con pavimentos polícromos y una pinacoteca extraordinaria con obras depositadas del Museo del Prado de pintores universales como El Greco y Goya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90026','iglesia','Iglesia de San Antonio Abad','Monumental templo edificado a finales del siglo XVIII que fusiona el barroco tardío con el neoclásico, caracterizado por su fachada de sillería de líneas severas con portada flanqueada por columnas y un campanario barroco exento que corona la fisonomía de la ciudad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90026','monumento','Xalet del Nin (Chalet del Nin)','Suntuosa residencia señorial de estética ecléctica construida a principios del siglo XX sobre una antigua fortificación defensiva del frente marítimo que exhibe fachadas con profusa ornamentación escultórica, grandes tribunas de piedra caliza calada y un frondoso jardín de palmeras tropicales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90026','monumento','Anexo','Municipios de la provincia de Barcelona Anexo: Municipios de la provincia de Barcelona Nombre oficial Nombre en castellano Población (2022) Vilalba Sasserra Villalba Sase...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08214','monumento','Castillo de Vilassar','Magna fortaleza medieval del siglo X declarada Bien de Interés Cultural que destaca por su imponente torre del homenaje cilíndrica con muros de sillería regular granítica, su recinto amurallado perimetral provisto de almenas e históricas saeteras y sus ventanales góticos de tracería lobulada añadidos en las reformas señoriales del siglo XIV.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08214','iglesia','Iglesia de San Ginés de Vilassar de Dalt','Templo de base medieval reedificado tras la Guerra Civil en un estilo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08214','monumento','Fábrica de Can Garbat','Complejo hilandero decimonónico que constituye una muestra primordial de la arqueología industrial de la comarca del Maresme, caracterizado por sus amplias naves de ladrillo visto con estructuras de fundición de hierro y su esbelta chimenea troncocónica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08219','monumento','Torre de Can Nadal','Torre de defensa costera contra la piratería berberisca erigida en el siglo XVI de planta cuadrangular y sillería regular que conserva sus saeteras originales, las ménsulas del desaparecido matacán superior y que hoy en día se halla exenta e integrada orgánicamente en el entorno urbano de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08219','iglesia','Iglesia de San Juan de Vilassar de Mar','Templo parroquial levantado a mediados del siglo XX de líneas historicistas clásicas que destaca por albergar una monumental fachada de paramentos enlucidos con portal de cantería y un campanario de torre octogonal que corona el perfil marítimo de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08219','monumento','Museo de la Marina','Centro cultural e histórico ubicado en una antigua casa señorial de indianos de estilo modernista que custodia una valiosa colección de cartografía náutica del siglo XIX, instrumental de navegación tradicional y exvotos marineros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08219','monumento','Pasar a las provincias de Girona o Lleida para terminar el mapa de Cataluña','Pasar a las provincias de Girona o Lleida para terminar el mapa de Cataluña','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08219','monumento','Indicame otra provincia activa en la que desees que nos enfoquemos hoy','Indicame otra provincia activa en la que desees que nos enfoquemos hoy','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90595','monumento','Núcleos de población de Albanyà','El término municipal incluye los siguientes núcleos de población: Bassegoda, Lliurona y Carbonills.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90595','iglesia','Iglesia de San Pedro de Albanyà','Monasterio románico del siglo XI edificado en sillería regular que presenta una planta de nave única con bóveda de cañón apuntada, un ábside semicircular orientado al este con decoración exterior de estilo lombardo y un campanario de torre de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90595','iglesia','Santuario de Nuestra Señora del Monte (Mare de Déu del Mont)','Monumental complejo religioso del siglo XIV emplazado en una cumbre estratégica de la cordillera Transversal que destaca por su iglesia gótica de líneas austeras, muros de piedra caliza adaptados a la alta montaña y una hospedería anexa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90595','iglesia','Iglesia de San Miguel de Bassegoda','Pequeño santuario románico del siglo XII que consta de una sola nave con ábside semicircular orientado a levante, muros de sillería basta cementada con cal y una espadaña de dos vanos sobre el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90596','iglesia','Iglesia de San Pedro de Alp','Templo de base románica profundamente transformado en el siglo XIV en estilo gótico pirenaico que destaca por su robusta fachada fortificada con muros de mampostería rústica de alta montaña, una nave longitudinal y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90596','monumento','Torre de Riu','Suntuosa mansión residencial de estética historicista neogótica reconstruida a finales del siglo XIX sobre una antigua casa fuerte medieval, caracterizada por sus almenas perimetrales, ventanas geminadas con arcos conopiales labrados y torres angulares de pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90597','monumento','Núcleos de población de Amer','El término municipal incluye los siguientes núcleos de población: Palou, Sant Maurici y Costa de Santa Brígida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90597','iglesia','Monasterio de Santa María de Amer','Antiguo cenobio benedictino del siglo X que conserva su monumental iglesia románica de planta basilical con tres naves cubiertas por bóvedas de cañón sobre pilares de sillería y un majestuoso ábside central decorado con arquillos ciegos lombardos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90597','monumento','Plaza Porchada (Plaça de la Vila)','Histórico espacio público porticado de traza medieval que destaca por ser una de las plazas porticadas más grandes y mejor conservadas de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90597','ermita','Ermita de Santa Brígida','Pequeño santuario románico del siglo XII emplazado de forma espectacular sobre un acantilado rocoso que consta de una sola nave con ábside semicircular liso y una espadaña de dos vanos ejecutada en aparejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90598','monumento','Núcleos de población de Anglès','El término municipal incluye los siguientes núcleos de población: Pla d''Avall.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90598','monumento','Barrio Viejo y Calle de la Avellaneda','Núcleo urbano fortificado de origen medieval que conserva uno de los conjuntos de arquitectura gótica civil más relevantes de la comarca con sus muros de mampostería regular, portales dovelados de medio punto y excepcionales ventanales de arcos conopiales y trilobulados finamente labrados en piedra local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90598','iglesia','Iglesia de San Miguel','Templo de base medieval profundamente reconstruido en el siglo XVII en estilo barroco rural de líneas severas que exhibe una fachada monumental enlucida con portal de cantería moldurada, contrafuertes robustos exteriores y una recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90598','monumento','Fábrica de Can Burés','Antiguo complejo industrial textil fundado a finales del siglo XIX que constituye un exponente de la arqueología industrial de la cuenca del Ter al mantener sus grandes naves de ladrillo visto, una imponente máquina de vapor y una chimenea troncocónica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90599','monumento','Núcleos de población de Arbúcies','El término municipal incluye los siguientes núcleos de población: Lliors, Cerdans y Joanet.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90599','monumento','Castillo de Montsoriu','Monumental e imponente fortaleza medieval gótica construida entre los siglos X y XIV que está considerada el castillo gótico más excelso y mejor conservado de Catalunya, destacando su soberbio recinto amurallado con torreones cilíndricos exentos, su patio de armas fortificado de sillería granítica y su gran sala gótica abovedada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90599','iglesia','Iglesia de San Quirico y Santa Julita','Templo parroquial de origen románico profundamente transformado en época barroca que conserva de su fábrica medieval muros perimetrales de mampostería basta y destaca por albergar un interior clasicista bajo un robusto campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90599','monumento','Museo Etnológico del Montseny (La Gabella)','Caserón señorial del siglo XVII restaurado como centro cultural que custodia una exhaustiva colección de herramientas tradicionales, piezas cerámicas y maquetas que ilustran el aprovechamiento de los recursos naturales del macizo montañoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90600','monumento','Núcleos de población de Argelaguer','El término municipal incluye los siguientes núcleos de población: Sant Jaume de de Corts y Tapioles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90600','monumento','Castillo de Argelaguer','Casa fuerte señorial fortificada del siglo XV que conserva notables lienzos de sus murallas de sillería caliza regular, portales dovelados de arco de medio punto y ventanas coronelas de traza gótica modificadas en centurias posteriores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90600','iglesia','Iglesia de Santa María de Argelaguer','Templo parroquial románico del siglo XII edificado en sillería regular que presenta una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante sin ornamentación exterior y un campanario de torre cuadrangular añadido en el periodo barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90600','ermita','Ermita de Santa Ana de Corts','Pequeña capilla románica del siglo XII que consta de un aparejo tosco de sillarejo calizo, una nave longitudinal rematada por un ábside semicircular liso y una espadaña de dos vanos sobre la fachada de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90601','iglesia','Iglesia de San Martín','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un templo medieval anterior que presenta una amplia nave con capillas laterales, una monumental fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90601','monumento','Molino de L''Armentera','Antiguo complejo hidráulico harinero edificado en el siglo XVIII con aparejo de mampostería basta que conserva sus canales de derivación de las aguas del río Fluvià, las compuertas de fundición y las muelas de piedra caliza originales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90602','monumento','Núcleos de población de Avinyonet de Puigventós','El término municipal incluye los siguientes núcleos de población: Santa Eugènia d''Avinyó.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90602','monumento','Encomienda Hospitalaria de Avinyonet','Ruinas consolidadas de un imponente castillo-palacio fortificado de la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90602','iglesia','Iglesia de San Esteban de Avinyonet','Templo de base románica profundamente reformado en el siglo XVI en estilo gótico tardío que exhibe una fachada con portal renacentista de cantería moldurada, contrafuertes exteriores robustos y una recia torre-campanario de planta cuadrada con vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90602','ermita','Ermita de Santa Eugenia de Aviñón','Pequeño santuario rural románico del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante sin ornamentación exterior y una espadaña de dos ojos construida con aparejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90603','monumento','Núcleos de población de Banyoles','El término municipal incluye los siguientes núcleos de población: Puigpalter y Lió.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90603','iglesia','Monasterio de San Esteban de Banyoles','Monumental cenobio benedictino del siglo IX reconstruido en épocas gótica y barroca que destaca por su portalada gótica tardía de sillería vista, un bellísimo claustro clasicista y por custodiar en su interior la Arqueta de San Cornelio y San Cipriano, una joya cumbre de la orfebrería gótica de plata repujada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90603','monumento','Plaza Mayor (Plaça Major)','Histórico espacio público porticado de traza medieval (siglo XIII) configurado por cuarenta arcadas de piedra caliza travertina de lights desiguales que sostienen masías de cantería regular con ventanales de arcos conopiales labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90603','monumento','Pías Almoinas (Día de las Almoines)','Palacio del gótico civil del siglo XIV que funciona como museo arqueológico comarcal, caracterizado por su patio de armas central con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90603','monumento','Muralla Medieval y Recintos de los Pesqueros','Vestigios de las fortificaciones de sillería basta del siglo XIII del que subsisten dos torreones de planta circular con cúpulas apuntadas de piedra caliza, combinados con las icónicas cabañas portuarias decimonónicas dispuestas sobre la orilla del lago para el albergue de barcas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90603','iglesia','Iglesia de Santa María de Turers','Templo de traza gótica edificado en el siglo XIV que presenta una imponente nave única de gran anchura, capillas laterales entre los contrafuertes provistas de ventanales calados con vitrales y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90604','monumento','Núcleos de población de Bàscara','El término municipal incluye los siguientes núcleos de población: Calabuig, Orriols y Vilademuls.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90604','monumento','Recinto Amurallado y Castillo de Bàscara','Conjunto fortificado medieval del siglo XIII emplazado de forma estratégica sobre un risco del río Fluvià que conserva potentes paños de muralla de sillería caliza regular, torreones cilíndricos exentos de defensa y el monumental Portal de Gerona de arco apuntado dovelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90604','monumento','Castillo de Calabuig','Ruinas de una casa fuerte señorial del siglo XIV situadas en una colina de las que subsisten tramos notables de muros portantes de mampostería basta adaptados a la estructura defensiva de la actual iglesia de San Félix.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90604','iglesia','Iglesia de San Iscle y Santa Victoria','Templo parroquial de origen románico profundamente transformado en el siglo XVIII en estilo barroco rural de líneas severas que exhibe una fachada con portalada de cantería moldurada flanqueada por pilastras y un recio campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','monumento','Núcleos de población de Begur','El término municipal incluye los siguientes núcleos de población: Esclanyà, Sa Riera, Sa Tuna y Aiguafreda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','monumento','Castillo de Begur','Fortaleza medieval documentada desde el siglo XI y emplazada sobre un majestuoso peñón rocoso que domina el litoral ampurdanés de la que subsisten la base de su gran torre del homenaje cilíndrica de sillería basta, lienzos de murallas almenadas y escalinatas talladas directamente en la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','monumento','Torres de Defensa contra la Piratería','Conjunto de cinco robustas estructuras defensivas urbanas del siglo XVI (como las torres de Can Marquès, San Ramón o Ca n''Armanac) de planta circular o cuadrangular ejecutadas en mampostería regular con saeteras y matacanes para proteger la villa de los corsarios berberiscos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','iglesia','Iglesia de San Pedro','Templo parroquial de estilo gótico tardío construido en el siglo XVI que presenta una amplia nave con bóveda de crucería, una fachada sobria con portalada renacentista de sillería caliza y un robusto campanario cuadrangular adosado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','monumento','Casas de Indianos','Conjunto de suntuosos palacetes decimonónicos de arquitectura ecléctica edificados por begurenses retornados de Cuba que exhiben fachadas polícrómas con columnatas clasicistas, grandes frescos murales con paisajes tropicales en los porches y frondosos jardines con palmeras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','iglesia','Iglesia de San Esteban de Esclanyà','Pequeño templo de base románica del siglo X que presenta una nave única con ábside semicircular decorado exteriormente con arcuaciones ciegas de estilo lombardo, flanqueado por una maciza torre fortificada de planta rectangular del antiguo castillo medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90605','palacio','Castillo-Palacio de los Condes de Empúries','Monumental palacio fortificado de traza gótica construido a finales del siglo XIII que destaca por su planta rectangular estructurada en torno a un patio de armas central con muros de sillería caliza regular, un gran salón de arcos diafragmáticos apuntados y una corona perimetral de almenas e históricas aspilleras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90605','iglesia','Iglesia de San Juan de Bellcaire','Excepcional edificio románico del siglo XI de planta basilical con tres naves separadas por pilares cuadrangulares que cuenta con un ábside semicircular decorado con lesenas lombardas, un interior con vestigios de pintura mural románica y una singular estructura absidial que reutiliza cimientos paleocristianos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','monumento','Puente Viejo (Pont Vell)','Monumental e imponente infraestructura civil de origen románico reconstruida en el siglo XIV que salva el cauce del río Fluvià mediante siete arcadas angulares de luces decrecientes apoyadas sobre tajamares asentados en la roca viva, coronada en su tramo central por una colosal torre de defensa de planta hexagonal con portal dovelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','iglesia','Monasterio de San Pedro de Besalú','Magna iglesia abacial románica consagrada en el año 1003 que presenta una planta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','monumento','Miqvé y Sinagoga de Besalú','Excepcional complejo de baños rituales de purificación judíos del siglo XII descubierto intacto en 1964, el cual constituye el único monumento de esta tipología medieval conservado en la península ibérica al constar de una sala subterránea abovedada con sillería de piedra caliza y una escalinata que desciende hasta el nivel freático fluvial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','iglesia','Iglesia de San Vicente','Templo de transición románico-gótica construido entre los siglos XII y XIII edificado en cantería perfecta que destaca por su portada meridional de múltiples arquivoltas molduradas sobre columnas con capiteles de temática zoomorfa, su gran rosetón de tracería calada y una capilla lateral gótica de sillería vista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','monumento','Hospital de San Julián (Casa Cornellà)','Uno de los exponentes más puros y mejor conservados de la arquitectura gótica civil catalana del siglo XII que presenta un patio de armas interior con tres pisos de galerías porticadas de arcos rebajados sobre columnas exentas y una fachada de sillería regular con ventanales geminados labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90606','monumento','Núcleos de población de Bescanó','El término municipal incluye los siguientes núcleos de población: Estanyol, Montfullà y Vilanna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90606','monumento','Central Hidroeléctrica de Bescanó','Joya de la arquitectura industrial modernista diseñada por el arquitecto Joan Roca i Pinet en 1908 que destaca por su fachada ricamente ornamentada con gárgolas escultóricas y relieves cerámicos polícromos que representan alegorías de la electricidad, albergando en su interior naves de ladrillo visto con las turbinas originales francesas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90606','monumento','Yacimiento Arqueológico de la Cueva del Bisbe (Montfullà)','Asentamiento prehistórico paleolítico que ha aportado una valiosa colección de industria lítica de cuarcita y restos de fauna del Pleistoceno, musealizados para comprender el poblamiento más temprano del valle del río Ter.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90606','iglesia','Iglesia de San Lorenzo de Vilanna','Templo de base románica profundamente transformado en el periodo barroco (siglo XVIII) que muestra una planta de nave única con capillas laterales, una fachada de líneas neoclásicas con portalada moldurada de piedra local y un campanario de torre de sección cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90607','monumento','Castillo de Biure d''Empordà','Ruinas consolidadas de una estratégica fortaleza medieval documentada desde el siglo XII de la que subsisten notables tramos de sus muros de mampostería basta y la base de su antigua torre del homenaje cuadrangular adaptada a la elevación rocosa. [1, 2]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90607','iglesia','Iglesia de San Esteban de Biure','Templo parroquial de factura barroca rural reedificado en el siglo XVIII que exhibe una fachada de paramentos enlucidos con un portal moldurado de cantería, una amplia nave con capillas laterales y una recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90033','monumento','Castillo de San Juan (Castell de Sant Joan)','Fortaleza medieval erigida en el siglo XI sobre la cumbre del cerro homónimo que domina toda la bahía litoral, caracterizada por la impecable conservación de su gran torre del homenaje cilíndrica construida con aparejo de sillería caliza regular y tramos de muros almenados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90033','iglesia','Iglesia de Santa María de Blanes','Monumental templo gótico del siglo XIV adosado al antiguo palacio de los vizcondes de Cabrera que presenta una amplia nave única con capillas laterales entre contrafuertes robustos, una fastuosa portada meridional de arquivoltas ojivales y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90033','monumento','Fuente Gótica (Font Gòtica)','Joya cumbre de la arquitectura gótica civil de Cataluña proyectada a principios del siglo XV por orden del conde de Prades, consistente en una estructura octogonal exenta tallada finamente en piedra caliza con tracería flamígera, pináculos calados y gárgolas con figuras de animales fantásticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90033','iglesia','Santuario de la Virgen del Vilar','Complejo religioso de traza barroca y neoclásica situado en su entorno montañoso que cuenta con una iglesia de nave única con bóveda de cañón, paramentos de mampostería regular y una hospedería anexa destinada al cobijo tradicional de peregrinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90033','monumento','Jardín Botánico Marimurtra','Espectacular parque natural y paisajístico fundado en 1920 por el científico Carl Faust que fusiona colecciones botánicas mundiales con estructuras arquitectónicas clasicistas y románticas, destacando el emblemático Templete de Linneo alzado sobre un acantilado de roca viva con vistas al mar Mediterráneo. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17029','palacio','Castillo-Palacio de Boadella','Palacio fortificado tardogótico construido en el siglo XIV por los barones de Vilamarí que destaca por su simétrica fachada de sillería caliza regular, sus ventanas coronelas conopiales labradas de gran virtuosismo y un patio de armas central con galerías de arcos rebajados. [1, 2]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17029','monumento','Castillo de Les Escaules','Monumental fortaleza medieval del siglo XIV emplazada sobre una cresta rocosa calcárea de la que subsiste una imponente torre de vigía cilíndrica de diez metros de altura ejecutada en cantería perfecta y lienzos de la muralla perimetral provistos de saeteras y almenas rectangulares. [1, 2, 3]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17029','iglesia','Iglesia de Santa Cecilia de Boadella','Templo parroquial del siglo XVI profundamente reformado que presenta una estructura de nave única con capillas entre contrafuertes robustos, una portalada meridional de arco de medio punto adintelada y un campanario de torre de planta cuadrangular. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17029','monumento','Molino de las Pulgas (Molí de les Puces)','Ruinas consolidadas de un antiguo complejo hidráulico harinero de origen altomedieval que constituye un testimonio clave de la arqueología industrial preindustrial gracias a sus canalizaciones de piedra basta talladas en la roca junto al río Muga. [1, 2]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90608','monumento','Núcleos de población de Bolvir','El término municipal incluye los siguientes núcleos de población: Talltorta y Raval del Castell.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90608','monumento','Yacimiento Arqueológico de El Castellot','Destacado asentamiento fortificado ibérico y romano de los siglos IV al I a.C. que constituye uno de los pocos poblados pirenaicos musealizados al conservar las plantas completas de viviendas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90608','iglesia','Iglesia de Santa Cecilia de Bolvir','Templo de base románica del siglo XII edificado en sillería regular de granito de los Pirineos que presenta una sola nave cubierta por bóveda de cañón apuntada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una portada meridional de múltiples arquivoltas en degradación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90608','iglesia','Iglesia de San Clemente de Talltorta','Edificio religioso de origen románico profundamente transformado en el siglo XVII que destaca internacionalmente por albergar en su interior un fastuoso ciclo de pinturas murales barrocas de carácter popular que recubren por completo las cubiertas de viguería de madera y los muros interiores. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90608','monumento','Provincia de Girona - Viajes por España Municipios de la provincia de Girona ; B, Begur, Banyoles, Bàscara, Bellcaire','Provincia de Girona - Viajes por España Municipios de la provincia de Girona ; B, Begur, Banyoles, Bàscara, Bellcaire','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90608','monumento','Castell de les Escaules.Boadella d''Empordà -Girona 17 abr 2024 — hoy venimos a visitar el castillo de las escaulas monum','Castell de les Escaules.Boadella d''Empordà -Girona 17 abr 2024 — hoy venimos a visitar el castillo de las escaulas monumento histórico de la provincia del mismo nombre perteneciente al municipio ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90608','palacio','Castillo palacio de Boadella - CastillosNet Situación. El Castillo palacio de Boadella','Castillo palacio de Boadella - CastillosNet Situación. El Castillo palacio de Boadella se encuentra en Calle de la Procesó, junto a la Iglesia de Santa Cecilia, de la localid...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90609','iglesia','Iglesia de San Esteban','Monumental templo edificado entre los siglos XVI y XVIII que fusiona de forma única la arquitectura gótica tardía de su nave, cubierta con bóvedas de crucería, con una fastuosa fachada barroca de sillería calcárea y un campanario octogonal rematado por una esbelta aguja calada de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90609','monumento','Casa de la Villa (Antiguo Hospital)','Edificio civil de origen medieval reformado en el siglo XVI que presenta un aparejo regular de cantería, portales dovelados de arco de medio','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90609','monumento','Masía de Can Baio','Gran explotación agrícola tradicional estructurada a partir del siglo XVII en mampostería basta que conserva su estructura de tres cuerpos, un gran portal dovelado y un reloj de sol pintado al fresco en el paramento principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17026','monumento','Núcleos de población de Borrassà','El término municipal incluye los siguientes núcleos de población: Creixell.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17026','iglesia','Iglesia de San Andrés de Borrassà','Templo parroquial barroco del siglo XVIII de gran envergadura que destaca por su fachada monumental de sillería vista con una portalada clasicista flanqueada por columnas y hornacinas, un amplio interior de tres naves y un imponente campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17026','iglesia','Iglesia de Santa María de Creixell','Pequeña iglesia románica del siglo XII que presenta un aparejo regular de cantería regular, una nave longitudinal rematada por un ábside semicircular liso y un campanario de espadaña de dos vanos transformado posteriormente en torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17026','monumento','Masía fortificada de Can Llavanera','Gran complejo agropecuario de los siglos XVI y XVII que cuenta con una esbelta torre de defensa integrada de planta cuadrada con saeteras, portal de arco de medio punto con dovelas de piedra caliza y amplias salas de viguería noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17027','iglesia','Monasterio de San Salvador de Breda','Antiguo cenobio benedictino fundado en el siglo XI del que destaca su impresionante campanario románico de torre exento, una estructura de planta cuadrada de 32 metros de altura con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17027','iglesia','Claustro del Monasterio','Espacio claustral gótico del siglo XIV ejecutado en cantería perfecta del que se conserva un ala completa con arcadas apuntadas trilobuladas sustentadas sobre esbeltas columnas pareadas con capiteles de motivos vegetales finamente tallados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17027','iglesia','Iglesia de Santa María (Actual Ayuntamiento)','Antiguo templo parroquial románico del siglo XII del que subsiste la cabecera absidial y la fachada occidental con portada de arquivoltas molduradas, integrada de forma rigurosa en las dependencias administrativas municipales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17027','monumento','Centro Cultural de los Hornos de la Alfarda','Complejo preindustrial musealizado que constituye un testimonio clave de la arqueología industrial y de la larga tradición cerámica de la villa al conservar intactos dos grandes hornos de cocción de ladrillo y arcilla del siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17028','monumento','Núcleos de población de Brunyola','El término municipal incluye los siguientes núcleos de población: Brunyola y Sant Martí Sapresa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17028','monumento','Castillo de Brunyola','Monumental e imponente fortaleza medieval del siglo XII que constituye uno de los conjuntos fortificados mejor conservados de la comarca de la Selva, caracterizado por su planta cuadrangular de sillería granítica que integra en sus ángulos tres grandes torres de defensa (una cilíndrica y dos cuadradas) con almenas y matacanes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17028','iglesia','Iglesia de San Fructuoso de Brunyola','Edificio religioso adosado directamente a la estructura de la muralla del castillo que presenta una base medieval reformada en los siglos XVI y XVII con un interior de nave única, capillas laterales y una robusta torre-campanario que aprovecha un antiguo torreón defensivo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17028','iglesia','Iglesia de San Martín de Sapresa','Templo parroquial de factura barroca rural (siglo XVIII) construido con aparejo de mampostería regular enlucida que exhibe una fachada de líneas neoclásicas severas con portalada moldurada de cantería y un campanario de torre de sección cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17028','monumento','Pueblos en Girona La villa','Pueblos en Girona La villa es de origen medieval y creció alrededor de una fortaleza, el Castillo de Besalú, antiguo centro de la administración y e...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17031','monumento','Núcleos de población de Cabanelles','El término municipal incluye los siguientes núcleos de población: Vilademires, Espinavessa, San Martín Sesserres y Queixàs.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17031','iglesia','Iglesia de San Vicente de Cabanelles','Monumental templo románico del siglo XII edificado en sillería caliza regular que destaca por su ábside semicircular con decoración de estilo lombardo y su espléndida portalada meridional de cinco arquivoltas en degradación soportadas por columnas con capiteles historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17031','iglesia','Iglesia de San Román de Casals','Pequeña capilla románica del siglo XI que presenta un aparejo regular de sillarejo, una nave longitudinal cubierta por bóveda de cañón y una espadaña de dos vanos construida con piedra tosca local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17031','monumento','Masía fortificada de Can Corominas','Gran complejo agropecuario de los siglos XV y XVI que conserva una esbelta torre de defensa de planta cuadrada integrada en la vivienda, portales dovelados de arco de medio punto y aspilleras para armas de fuego.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17030','monumento','Torre de Cabanes','Imponente torre de defensa medieval de planta circular y sillería perfecta que constituye el único vestigio en pie del desaparecido castillo de la villa del siglo XIV, conservando saeteras defensivas a diferentes alturas y ménsulas del destruido matacán superior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17030','iglesia','Iglesia de San Vicente de Cabanes','Templo parroquial de factura barroca del siglo XVIII construido sobre cimientos románicos que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portal de cantería moldurada y una recia torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','monumento','Núcleos de población de Cadaqués','El término municipal incluye los siguientes núcleos de población: Portlligat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','iglesia','Iglesia de Santa María de Cadaqués','Monumental templo edificado entre los siglos XVI y XVII en estilo gótico tardío que domina el perfil costero de la villa, célebre por albergar en su interior un fastuoso retablo mayor barroco de madera tallada y dorada ejecutado por los escultores Pau Costa y Joan Torras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','monumento','Casa-Museo de Salvador Dalí (Portlligat)','Complejo arquitectónico y laberíntico configurado por el genial pintor surrealista a partir de la unión de varias cabañas de pescadores del siglo XIV, la cual conserva la fisonomía','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','monumento','Castillo de San Jaime (Castell de Sant Jaume)','Ruinas consolidadas de una fortaleza defensiva del siglo XIX emplazada en un promontorio estratégico de las que subsisten tramos de la muralla perimetral ejecutados con pizarra rústica y fosos defensivos tallados en la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','monumento','Torre del Colom','Esbelta mansión residencial e historicista construida a principios del siglo XX de estética modernista que exhibe una fachada con ornamentación de esgrafiados geométricos, almenas decorativas y ventanales con molduras de inspiración gótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17033','monumento','Núcleos de población de Caldes de Malavella','El término municipal incluye los siguientes núcleos de población: Franciac, Santa Seclina y San Mauricio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17033','monumento','Termas Romanas de Sant Grau','Monumental e impresionante complejo termal del siglo I d.C. que constituye uno de los monumentos de época imperial mejor conservados de la península, manteniendo intacta una gran piscina central (natatio) rodeada por muros de opus signinum y las salas de los baños de vapor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17033','monumento','Castillo de Malavella','Ruinas de una estratégica fortaleza medieval documentada desde el siglo XI de la que subsisten potentes lienzos de muralla construidos con bloques de basalto negro local y la base de su primigenia torre del homenaje cilíndrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17033','iglesia','Iglesia de San Esteban de Caldes','Templo parroquial de origen románico profundamente transformado en época barroca que conserva de su estructura del siglo XII una notable cabecera triabsidial con arcuaciones lombardas y una portada meridional de cantería moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17033','monumento','Balneario Vichy Catalán','Complejo hotelero y medicinal de estética mudéjar y modernista inaugurado a finales del siglo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17035','monumento','Núcleos de población de Camós','El término municipal incluye los siguientes núcleos de población: Santa Maria de Camós.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17035','iglesia','Iglesia de San Vicente de Camós','Templo de base románica del siglo XII que presenta una sola nave cubierta por bóveda de cañón apuntada, un ábside semicircular orientado a levante decorado exteriormente con un friso de canecillos lisos y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17035','monumento','Villa Romana de Vilauba','Yacimiento arqueológico musealizado que abarca desde el siglo I a.C. hasta el siglo IV d.C. donde se conservan las trazas de piedra de la zona residencial (pars urbana) con restos de almacenes agrícolas y un larario destinado al culto doméstico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','monumento','Núcleos de población de Camprodon','El término municipal incluye los siguientes núcleos de población: Beget, Rocabruna y Freixenet de Camprodon.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','monumento','Puente Nuevo (Pont Nou)','Monumental e icónica infraestructura civil del siglo XIV que salva el cauce del río Ter mediante un único y colosal arco apuntado de gran luz reforzado con tajamares sobre la roca viva, coronado por una torre de defensa con portal dovelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','iglesia','Iglesia de San Cristóbal de Beget','Excepcional joya del románico pirenaico del siglo XII declarada Monumento Nacional que destaca por su impecable conservación de sillería caliza regular, su esbelto campanario de torre de cuatro pisos y por custodiar la Majestad de Beget, una talla románica de madera policromada del siglo XII excelsa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','iglesia','Monasterio de San Pedro de Camprodon','Magna iglesia abacial románica del siglo XII de planta de cruz latina que presenta cinco ábsides semicirculares perfectos provistos de decoración exterior lombarda y un imponente campanario cuadrangular que corona el crucero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','monumento','Castillo de Rocabruna','Ruinas de una estratégica fortaleza defensiva militar del siglo X emplazada sobre un risco escarpado de las que subsisten potentes lienzos de la muralla perimetral construidos con aparejo rústico y la base de su torre de vigía cilíndrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17040','monumento','Núcleos de población de Canet d''Adri','El término municipal incluye los siguientes núcleos de población: Adri, Rocacorba y Montbó.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17040','iglesia','Santuario de la Virgen de Rocacorba','Templo edificado en el siglo XVIII sobre los restos del antiguo castillo medieval emplazado en la cumbre de un espectacular risco de la cordillera Transversal, caracterizado por su sólida fábrica de sillería de piedra calcárea adaptada a la alta montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17040','iglesia','Iglesia de San Vicente de Canet','Edificio religioso románico del siglo XII edificado en sillería regular que presenta una sola nave con bóveda de cañón apuntada, un ábside semicircular decorado exteriormente con un friso de dientes de sierra y un campanario de torre cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17041','monumento','Castillo de Cantallops','Ruinas de una antigua fortaleza militar del siglo XIII integrada en viviendas del casco urbano de la que perviven los cimientos de la torre del homenaje de planta circular y algunos paños de la muralla perimetral provistos de saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17041','iglesia','Iglesia de San Esteban','Templo parroquial de origen medieval profundamente transformado en época barroca que mantiene de su fábrica primitiva una nave longitudinal y destaca por su portalada modificada de cantería moldurada flanqueada por una recia torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17042','iglesia','Iglesia de Santa Ágata de Capmany','Monumental templo románico fortificado del siglo XII construido con bloques de granito berroqueño regular que cuenta con una nave con bóveda de cañón apuntada, un ábside semicircular y un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17042','monumento','Dolmen de Quer Afumat','Destacado monumento megalítico del Neolítico final emplazado en su término comunal que conserva su cámara funeraria delimitada por grandes losas de granito hincadas verticalmente y restos del túmulo perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17044','iglesia','Iglesia de San Martín','Templo de base gótica del siglo XVI que presenta capillas laterales entre contrafuertes robustos, una monumental fachada decorada con gárgolas esculpidas y una esbelta torre-campanario que combina sillería granítica con remate balaustrado barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17044','monumento','Can Frigola y Torre Salvana','Casa señorial del gótico civil que destaca por incorporar una imponente torre de defensa del siglo XIV de planta cuadrangular ejecutada en piedra caliza calavera, ventanas ajimezadas y portalada dovelada de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17046','iglesia','Iglesia Vieja de San Salvador','Templo de origen medieval reedificado tras los terremotos del siglo XV que se alza de forma espectacular sobre el extremo de un acantilado basáltico de cincuenta metros de altura, combinando muros de sillería negra volcánica con un campanario exento de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17047','monumento','Núcleos de población de Castelló d''Empúries','El término municipal incluye los siguientes núcleos de población: Ampuriabrava.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17047','catedral','Basílica de Santa María (La Catedral de l''Empordà)','Magna iglesia gótica de los siglos XIII y XIV que destaca por su fachada monumental provista de un portal de mármol','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17047','palacio','Palacio de los Condes (Palau Comtal)','Residencia señorial fortificada del siglo XIV que conserva un impresionante patio de armas central con galerías porticadas de arcos apuntados, amplias salas institucionales abovedadas y lienzos de la muralla de sillería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17047','monumento','La Lonja de Mar (Llotja)','Edificio civil del gótico tardío construido en el siglo XV para el comercio marítimo que presenta un gran espacio diáfano estructurado mediante monumentales arcos diafragmáticos que sostienen la techumbre de viguería de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17060','monumento','Castillo de Montroig','Ruinas de una estratégica fortaleza militar del siglo XII de las que subsisten potentes lienzos de muralla de mampostería basta y saeteras originales que se adaptan a la cresta rocosa del macizo pirenaico de las Salinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17060','iglesia','Iglesia de Santa María de Darnius','Templo románico de finales del siglo XII edificado en cantería de granito berroqueño regular que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular y una espadaña de tres ojos reformada posteriormente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17061','monumento','Núcleos de población de Das','El término municipal incluye los siguientes núcleos de población: Sanavastre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17061','iglesia','Iglesia de San Lorenzo de Das','Templo de factura románica del siglo XII profundamente modificado en época barroca que mantiene su ábside semicircular y destaca por su portalada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17061','iglesia','Iglesia de San Juan de Sanavastre','Pequeño santuario medieval edificado en sillería de alta montaña que consta de una sola nave con ábside trapezoidal lisos, muros gruesos provistos de aspilleras de vigía y una espadaña de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18006','monumento','Núcleos de población de L'' Escala','El término municipal incluye los siguientes núcleos de población: Sant Martí d''Empúries.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18006','monumento','Yacimiento Arqueológico de Empúries','Monumental y único complejo arqueológico de la península que conserva superpuestas las plantas completas de la ciudad griega (Emporion) y de la ciudad romana (Emporiae) con espectaculares pavimentos de mosaico polícromo, murallas ciclópeas y los cimientos del santuario de Asclepio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18006','iglesia','Iglesia de San Pedro de la Escala','Monumental templo de estilo gótico tardío del siglo XVIII que exhibe una fachada de sillería caliza regular de líneas clásicas con portada moldurada flanqueada por pilastras y una torre-campanario cuadrangular de gran envergadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18006','monumento','Conjunto Histórico de Sant Martí d''Empúries','Núcleo urbano amurallado de origen medieval que conserva de forma impecable sus masías de piedra de los siglos XVI al XVIII, su portal de acceso de medio punto dovelado y la iglesia gótica de San Martín alzada junto al mar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17064','monumento','Castillo de Espolla','Casa fuerte señorial fortificada del siglo XIV de la que perviven los cimientos de la torre del homenaje de planta circular, tramos notables de muros de mampostería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17064','monumento','Dolmen de la Cabaña Arqueta','Destacado monumento megalítico del Neolítico final emplazado en el paraje natural de la Albera que conserva su cámara funeraria delimitada por grandes losas de piedra caliza hincadas verticalmente en el terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17066','monumento','Castillo de San Fernando (Castell de Sant Ferran)','Monumental e imponente fortaleza militar de la Ilustración construida en el siglo XVIII que está considerada el monumento fortificado más grande de Europa gracias a sus baluartes de sillería, sus kilómetros de fosos defensivos y sus cisternas subterráneas abovedadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17066','monumento','Teatro-Museo Dalí','Obra cumbre de la arquitectura surrealista diseñada por Salvador Dalí sobre los restos del antiguo teatro municipal decimonónico, caracterizada por su espectacular cúpula de estructura reticular acristalada y sus fachadas decoradas con panes de estilo modernista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17066','iglesia','Iglesia de San Pedro de Figueres','Templo de base románica profundamente transformado en estilo gótico en el siglo XIV que presenta una amplia nave con capillas laterales entre contrafuertes y un campanario de torre cuadrangular con remate balaustrado renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17902','monumento','Núcleos de población de Forallac','El término municipal incluye los siguientes núcleos de población: Peratallada, Vulpellac y Fonteta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17902','monumento','Conjunto Histórico de Peratallada','Núcleo medieval fortificado de primer orden que destaca por su sistema','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17902','monumento','Castillo de Vulpellac','Palacio fortificado del gótico civil y del Renacimiento construido en el siglo XIV que presenta un magnífico patio de armas central con galerías de arcos rebajados, ventanas ajimezadas y estancias nobles revestidas de pavimentos cerámicos tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17902','iglesia','Iglesia de San Julián y Santa Basilisa','Templo románico de finales del siglo XII edificado en sillería regular que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular decorado exteriormente con un friso de dientes de sierra y una espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17077','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de sillería caliza vista con portada clasicista moldurada, un interior de tres naves de gran amplitud y un esbelto campanario octogonal con remate cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17077','monumento','Torre de Can Teixidor','Antigua torre de defensa del núcleo urbano del siglo XVI de planta circular y mampostería regular que conserva saeteras y las ménsulas del desaparecido matacán superior destinado a proteger la heredad agrícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17081','monumento','Puente de Gualta','Viaducto medieval de origen gótico (siglo XIV) ejecutado en cantería perfecta que salva el cauce del río','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17081','iglesia','Iglesia de Santa María de Gualta','Edificio religioso de traza barroca clasicista construido en el siglo XVIII que muestra una planta de nave única con capillas laterales, portalada moldurada de piedra local y un campanario de torre de sección cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17083','monumento','Fortaleza de Hostalric','Monumental e imponente complejo militar de época borbónica construido en el siglo XVIII sobre un cerro volcánico estratégico que conserva sus baluartes de sillería y ladrillo visto, polvorines abovedados y un gran foso defensivo tallado en el terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17083','monumento','Recinto Amurallado y Torre de los Frailes','Vestigios del sistema defensivo medieval del siglo XIV del que subsisten seiscientos metros de cortina de sillería basta con almenas rectangulares y diez torreones exentos de planta circular provistos de aspilleras de vigía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17088','iglesia','Monasterio de Santa María de Lladó','Antiguo cenobio agustiniano del siglo XII del que destaca su monumental iglesia románica de planta basilical con tres naves cubiertas por bóvedas de cañón y una espectacular portada occidental de seis arquivoltas en degradación con capiteles historiados tallados en piedra caliza regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90610','monumento','Torre Románica de la Plaza','Estructura exenta del siglo XIII que constituía el campanario del desaparecido templo medieval de la villa, caracterizada por su planta cuadrada de sillería de piedra pizarra rústica con ventanas geminadas de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90610','iglesia','Iglesia de San Vicente de Llançà','Templo de traza barroca clasicista edificado en el siglo XVIII que presenta una fachada monumental de sillería vista con portada moldurada flanqueada por pilastras y una recia torre-campanario cuadrangular rematada por balaustrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17097','monumento','Núcleos de población de Madremanya','El término municipal incluye los siguientes núcleos de población: Millàs y Millars.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17097','iglesia','Iglesia de San Esteban de Madremanya','Monumental templo románico fortificado del siglo XII edificado en cantería regular que consta de una amplia nave única con bóveda de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17097','iglesia','Iglesia de San Iscle de Millàs','Pequeña capilla románica del siglo XII que presenta un aparejo regular de sillarejo calizo, una nave longitudinal rematada por un ábside semicircular orientado al este y un campanario de espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17102','iglesia','Iglesia de San Martín de Maçanet','Templo románico de finales del siglo XII edificado en sillería regular que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular decorado exteriormente con un friso de canecillos lisos y una espadaña de tres ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17102','iglesia','Santuario de Nuestra Señora de las Salinas','Complejo religioso del siglo XVII emplazado a más de mil metros de altitud en el Pirineo que cuenta con una iglesia de nave única con paramentos de mampostería basta adaptados al clima de alta montaña y una hospedería anexa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17099','iglesia','Iglesia de San Saturnino de Meranges','Joya del románico pirenaico del siglo XII edificada en piedra caliza regular que destaca por su ábside semicircular orientado a levante y por albergar en su interior una notable portada meridional de cinco arquivoltas en degradación con capiteles esculpidos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17111','iglesia','Iglesia Vieja de San Pedro de Navata','Ruinas consolidadas de un templo parroquial de origen románico del siglo XII que conservan alzados notables de sus muros de sillería de piedra caliza regular y la base del antiguo ábside semicircular liso integrado en el paisaje rural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17111','monumento','Castillo de Navata','Ruinas de una estratégica fortificación medieval del siglo XI de las que subsisten los potentes cimientos de la torre del homenaje de planta circular y tramos dispersos de la muralla perimetral de mampostería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17112','monumento','Instalaciones de las Minas de Carbón de Ogassa','Complejo industrial decimonónico musealizado que constituye un exponente de la arqueología industrial catalana al conservar las bocaminas de piedra basta, los planos inclinados para el transporte de mineral y los cargaderos de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17112','iglesia','Iglesia de Santa María de Ogassa','Pequeño templo de base románica del siglo XII de planta de nave única con ábside semicircular liso, muros de sillería rústica con piedra de alta montaña y una espadaña de un vano centrada en el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17114','monumento','Núcleos de población de Olot','El término municipal incluye los siguientes núcleos de población: Batet de la Serra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17114','iglesia','Iglesia de San Esteban de Olot','Monumental basílica reedificada en el siglo XVIII en estilo barroco clasicista que destaca por su imponente fachada de sillería vista con portada monumental flanqueada por pilastras, un amplio interior de tres naves de gran altura y un robusto campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17114','monumento','Casas Modernistas de Olot (Casa Solà-Morales y Casa Pujador)','Conjunto residencial de principios del siglo XX proyectado por arquitectos locales que destaca por sus fachadas con profusa ornamentación exterior a base de esgrafiados florales, cariátides escultóricas y barandillas sinuosas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17114','monumento','Hospicio de Olot','Palacio del siglo XVIII proyectado por el arquitecto Ventura Rodríguez en estilo neoclásico que presenta un monumental patio interior de tres pisos con galerías porticadas de arcos de medio punto sobre pilares de piedra caliza calavera regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17117','monumento','Núcleos de población de Palafrugell','El término municipal incluye los siguientes núcleos de población: Calella de Palafrugell, Llofriu y Tamariu.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17117','monumento','Conjunto de la Torre de San Sebastián (Sant Sebastià de la Guarda)','Complejo defensivo medieval del siglo XV erigido sobre un cabo estratégico que conserva una imponente torre de defensa de planta cuadrangular de sillería, saeteras y una capilla barroca adosada dedicada al santo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17117','iglesia','Iglesia de San Martín de Palafrugell','Templo parroquial de origen románico profundamente transformado en el siglo XVIII en estilo barroco de aire clasicista que muestra una amplia nave única con capillas laterales entre contrafuertes y un campanario de torre de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17117','monumento','Fábrica de Corcho de Can Mario','Antiguo complejo industrial modernista de principios del siglo XX que constituye un exponente de la arqueología industrial al conservar sus naves de ladrillo visto y una esbelta torre de depósito de agua de hierro forjado artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17118','iglesia','Iglesia de Santa María del Mar','Templo parroquial de estilo gótico tardío construido en el siglo XVI que presenta una amplia nave con bóveda de crucería, una fachada sobria con portalada renacentista de sillería caliza y una robusta torrecampanario cuadrangular de vigía costera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17118','monumento','Castillo de San Esteban de Mar','Ruinas de una estratégica fortaleza medieval del siglo XIII emplazada sobre un acantilado marino de las que subsisten lienzos de la muralla perimetral de mampostería basta y la base de su torre de defensa cilíndrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17124','monumento','Torre de las Horas (Torre de les Hores)','Monumental e impresionante torre del homenaje románica del siglo XI de planta circular y sillería caliza perfecta que constituye el elemento más señero del desaparecido castillo de la villa, conservando sus saeteras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17124','monumento','Recinto Amurallado de Pals','Vestigios del sistema defensivo medieval del siglo XIV del que subsisten tramos notables de cortina de sillería basta con almenas rectangulares, fosos defensivos y portales monumentales de acceso de arco apuntado como el Portal de la Villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17124','iglesia','Iglesia de San Pedro de Pals','Edificio religioso de origen románico profundamente transformado en estilo gótico en el siglo XIV que presenta una amplia nave única con bóvedas de crucería, una portada con arquivoltas apuntadas molduradas y una recia torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17138','monumento','Estación Internacional de Ferrocarril','Monumental infraestructura civil inaugurada a principios del siglo XX que constituye un hito de la arquitectura del hierro y el cristal al salvar las vías mediante una descomunal marquesina metálica de perfiles curvos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17138','iglesia','Iglesia de Santa María de Portbou','Templo parroquial neogótico diseñado por el arquitecto Joan Martorell en el siglo XIX que destaca por su esbelto campanario exento de aguja piramidal, su fachada con un gran rosetón de tracería calada y sus ventanales apuntados con vitrales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17043','iglesia','Iglesia de San Jaime de Queralbs','Excepcional templo románico del siglo XII edificado en sillería regular de granito que destaca por albergar un bellísimo porche porticado de seis arcadas de medio punto sobre columnas exentas con capiteles historiados de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17043','iglesia','Santuario de Nuria','Complejo religioso de estilo historicista neorrománico situado en un circo glacial a dos mil metros de altitud que cuenta con una iglesia de tres naves con fachada monumental y dependencias anexas destinadas tradicionalmente al albergue de peregrinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17145','monumento','Castillo de Ribes (Castell de Sant Pere)','Ruinas de una estratégica fortaleza medieval del siglo XI emplazada sobre una cresta rocosa del Pirineo de las que subsisten los potentes cimientos de la torre del homenaje y tramos dispersos de la muralla perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17145','iglesia','Iglesia de Santa María de Ribes','Templo de base románica profundamente transformado en el siglo XVIII en estilo barroco que mantiene de su fábrica original tres ábsides semicirculares perfectos con decoración exterior lombarda de arquillos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17147','iglesia','Monasterio de Santa María de Ripoll','Magna abadía benedictina medieval que constituye el principal símbolo del origen de Catalunya, célebre por su impresionante e incomparable portalada románica del siglo XII tallada en piedra caliza como una biblia en imágenes y su claustro de dos pisos con capiteles historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17147','monumento','Farga Palau de Ripoll','Antigua fragua de origen medieval que constituye un hito de la arqueología industrial y de la siderurgia preindustrial catalana al conservar intactos los martillos mecánicos impulsados por agua, las trompas de aire y las muelas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17147','iglesia','Iglesia de San Pedro de Ripoll','Edificio religioso adosado al recinto monástico construido en el siglo XII que presenta una planta de nave única con bóveda de cañón, una fachada muy sobria con espadaña de dos ojos y un interior reformado en el barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18014','monumento','Ciudadela de Roses','Monumental recinto fortificado de planta pentagonal de época renacentista (siglo XVI) que protege un valioso yacimiento arqueológico con las trazas de la ciudad griega de Rhode, una villa romana y el monasterio románico de Santa María con su ábside.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18014','monumento','Castillo de la Trinidad (Castell de la Trinitat)','Fortaleza militar costera del siglo XVI de planta estrellada erigida sobre la punta de la bahía para el albergue de artillería defensiva, caracterizada por sus potentes muros de sillería y ladrillo visto resistentes a los bombardeos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17164','iglesia','Iglesia de San Hilario','Templo de origen medieval profundamente reformado en el siglo XVIII en estilo barroco clasicista que muestra una amplia nave única con capillas laterales entre contrafuertes robustos, una fachada de paramentos enlucidos con portalada de cantería y un campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17164','monumento','Balneario de Font Picant','Complejo hotelero y medicinal de estética modernista construido a finales del siglo XIX para el aprovechamiento de las aguas mineromedicinales de las Guilleries, caracterizado por sus pabellones con fachadas esgrafiadas y amplios jardines.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08021','iglesia','Monasterio de Sant Joan de les Abadesses','Magna abadía medieval fundada en el siglo IX por el conde Guifré el Pilós que destaca por su monumental iglesia románica del siglo XII que alberga el grupo escultórico del Santísimo Misterio, una joya cumbre de la talla románica en madera policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08021','monumento','Puente Viejo (Pont Vell)','Infraestructura civil de origen gótico construida en el siglo XIV sobre el río Ter mediante un colosal arco apuntado de gran luz reforzado con tajamares sobre la roca viva, destruido en la contienda civil y reconstruido con rigor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08021','iglesia','Palacio de la Abadía','Edificio residencial fortificado del gótico civil catalán del siglo XIV que presenta un patio de armas interior con dos pisos de galerías porticadas de arcos apuntados sobre columnas y salas nobles abovedadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18017','monumento','Recinto Amurallado de la Vila Vella','Espectacular y único ejemplo de población medieval fortificada que se conserva en el litoral catalán (siglo XIV), caracterizado por sus murallas de sillería caliza regular con siete torres de defensa cilíndricas exentas coronadas por almenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18017','iglesia','Iglesia Vieja de San Vicente','Ruinas consolidadas de un templo gótico del siglo XIV situado dentro del recinto amurallado de las que subsisten el ábside poligonal con bóveda de crucería calada, los muros portantes de la nave y las capillas laterales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18017','monumento','Casa del Gobernador (Museo Municipal)','Palacio civil de traza gótica edificado en el siglo XIV que destaca por su fachada de sillería vista provista de ventanas coronelas conopiales labradas y por albergar una de las colecciones de arte de vanguardia pioneras de la costa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17210','iglesia','Iglesia de San Miguel de Ventalló','Templo de estilo gótico tardío del siglo XVI profundamente reformado que destaca por su estructura de nave única con capillas entre contrafuertes, una portada renacentista de sillería granítica con hornacina superior y un campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17210','palacio','Palacio de los Duques de Almenara Alta (Casa de los Caramany)','Caserón señorial de origen renacentista','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17221','monumento','Núcleos de población de Vilafant','El término municipal incluye los siguientes núcleos de población: Les Forques y Palol d''Alemany.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17221','iglesia','Iglesia de San Cipriano de Vilafant','Templo de origen románico profundamente reformado en las centurias barrocas que conserva de su fábrica del siglo XII el ábside semicircular de sillería caliza regular y una portada meridional bajo una robusta torre-campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17221','monumento','Palol d''Alemany','Conjunto fortificado altomedieval del que subsisten los potentes lienzos de mampostería basta de una torre de vigía y muros de contención integrados en dependencias agrícolas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17223','monumento','Castillo de Quermançó','Ruinas de una mítica e imponente fortaleza medieval del siglo XI emplazada sobre un peñón rocoso aislado que conserva tramos de sus murallas de sillería de pizarra y la base de su torre del homenaje circular que domina el paisaje ampurdanés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17223','monumento','Dolmen de la Vinya de les Erenes','Destacado monumento megalítico del Neolítico final que conserva su cámara funeraria delimitada por grandes losas de piedra local','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17223','monumento','Sinagoga y Cueva de los Judíos','Estructuras rupestres excavadas directamente en la roca viva calcárea asociadas a los rituales y asentamientos históricos de las comunidades hebreas altomedievales en el sector de la Albera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17224','monumento','Núcleos de población de Vilallonga de Ter','El término municipal incluye los siguientes núcleos de población: Tregurà de Dalt, Tregurà de Baix y Abella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17224','iglesia','Iglesia de San Martín de Vilallonga','Templo románico del siglo XII edificado en sillería de alta montaña que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular decorado exteriormente con cornisa de canecillos lisos y una recia torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17224','iglesia','Iglesia de San Julián de Tregurà','Edificio religioso románico situado en un emplazamiento escarpado a más de mil cuatrocientos metros de altitud que presenta muros de mampostería basta adaptados a la climatología pirenaica y una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17225','iglesia','Iglesia de Santa María de Vilamacolum','Templo de origen románico modificado en época gótico-renacentista que mantiene de su fábrica primitiva una nave longitudinal ejecutada en cantería y destaca por su portalada adintelada de piedra moldurada bajo una torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17226','iglesia','Iglesia de San Vicente de Vilamalla','Templo parroquial románico del siglo XII edificado en sillería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular orientado al este sin ornamentación exterior y un campanario de espadaña de dos vanos sobre el hastial de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17227','monumento','El Castillo de Vilamaniscle','Caserón señorial fortificado del siglo XIV de planta rectangular y muros de mampostería basta que conserva saeteras defensivas a diferentes alturas, portales dovelados de arco de medio punto y ventanas conopiales labradas en piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17228','monumento','Núcleos de población de Vilanant','El término municipal incluye los siguientes núcleos de población: Taravaus.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17228','iglesia','Iglesia de Santa María de Vilanant','Monumental templo románico fortificado del siglo XII construido con bloques de granito regular que cuenta con una nave con bóveda de cañón apuntada, un ábside semicircular y un coronamiento superior de muros con aspilleras defensivas y matacanes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17228','ermita','Ermita de San Jaime de Soler','Pequeña capilla románica del siglo XI que presenta un aparejo regular de sillarejo calizo, una nave longitudinal rematada por un ábside semicircular orientado a levante y una espadaña de un solo ojo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17230','iglesia','Castillo-Palacio del Abad de Sant Pere de Rodes (La Abadía)','Palacio fortificado del gótico civil construido en el','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17230','iglesia','Iglesia de San Esteban de Vila-sacra','Templo románico de transición edificado en el siglo XII en cantería regular que presenta una imponente nave única de gran anchura, capillas laterales entre los contrafuertes y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17222','monumento','Recinto Amurallado de Vilaür','Vestigios del sistema defensivo medieval del siglo XIV del que subsisten tramos notables de cortina de sillería basta integrados en las viviendas del casco urbano y un portal de acceso monumental de arco apuntado dovelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17222','iglesia','Iglesia de San Esteban de Vilaür','Edificio religioso de origen medieval profundamente transformado en época barroca que mantiene de su fábrica primitiva una nave longitudinal y destaca por su portalada modificada de cantería moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90611','monumento','Núcleos de población de Agramunt','El término municipal incluye los siguientes núcleos de población: Almenara alta, Mafet, Montclar y Aladrell.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90611','iglesia','Iglesia de Santa María de Agramunt','Monumental templo románico del siglo XII declarado Monumento Nacional que destaca mundialmente por su fastuosa fachada occidental, provista de una portada de ocho arquivoltas en degradación profusamente esculpidas por la escuela de Lleida con motivos geométricos y relieves historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90611','monumento','Torre de Almenara','Imponente torre de vigía medieval de planta circular y sillería perfecta del siglo XI que constituye el único vestigio en pie del desaparecido castillo del núcleo, conservando saeteras defensivas a diferentes alturas y un acceso elevado original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90611','monumento','Castillo de Montclar','Palacio fortificado del siglo XVII levantado sobre una antigua fortaleza medieval que presenta una simétrica fachada de sillería caliza vista, ventanas con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90612','monumento','Núcleos de población de Alàs i Cerc','El término municipal incluye los siguientes núcleos de población: Alàs, Cerc, Torres d''Alàs y Vilanova de Banat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90612','iglesia','Iglesia de San Justo y San Pastor de Alàs','Templo de origen románico profundamente transformado en época barroca que conserva de su fábrica medieval muros perimetrales de mampostería basta y destaca por albergar un interior clasicista bajo un robusto campanario de torre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90612','ermita','Ermita de la Virgen de las Peces','Pequeña capilla románica del siglo XII situada en un emplazamiento escarpado de la comarca de l''Alt Urgell que presenta una sola nave con ábside semicircular liso, muros de sillería rústica y una espadaña de un solo ojo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90613','monumento','Castillo de Albatàrrec (Castell de los Espolles)','Palacio fortificado del gótico civil catalán construido en el siglo XIV y suntuosamente restaurado a principios del siglo XX que destaca por sus potentes murallas de sillería caliza regular, sus almenas perimetrales y sus ventanas de tracería calada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90614','iglesia','Iglesia de la Asunción de Albesa','Monumental edificio religioso construido en el siglo XVIII bajo las directrices del estilo barroco que exhibe una fachada de sillería vista con portalada clasicista flanqueada por columnas y un imponente campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90614','monumento','Villa Romana del Romeral','Yacimiento arqueológico de época imperial que conserva las plantas de piedra de sus estancias residenciales y productivas, donde las excavaciones arqueológicas sacaron a la luz espectaculares pavimentos de mosaico polícromo de opus tessellatum.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90615','iglesia','Iglesia de San Pedro','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una monumental fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90616','monumento','Núcleos de población de Alcarràs','El término municipal incluye los siguientes núcleos de población: Montagut y Palmanova.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90616','iglesia','Iglesia de la Asunción de Alcarràs','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90617','iglesia','Iglesia de Miguel Arcángel','Edificio religioso de época barroca (siglo XVIII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una portada clasicista de cantería moldurada y una esbelta torre-campanario que domina el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90617','monumento','Lleida es una de las ciudades más antiguas de Cataluña y su historia se remonta a más de dos mil años. En época romana f','Lleida es una de las ciudades más antiguas de Cataluña y su historia se remonta a más de dos mil años. En época romana fue conocida como Ilerda, un enclave estratégico junto al río Segre que tuvo importancia militar y comercial, especialmente durante las guerras civiles romanas. Con la llegada de la Edad Media, la ciudad pasó a formar parte de Al-Ándalus, dejando una huella notable en su urbanismo y en su carácter de frontera. En el siglo XII, Lleida fue conquistada por los cristianos y se consolidó como un centro clave en la Corona de Aragón. Uno de sus grandes símbolos es la Seu Vella, la antigua catedral levantada sobre una colina, que dominó la ciudad durante siglos y hoy es su imagen más reconocible. Más tarde, Lleida sufrió el impacto de guerras y conflictos, como la Guerra de Sucesión y la Guerra Civil, pero mantuvo siempre su papel como referencia del interior catalán. Actualmente, Lleida combina ese pasado histórico con una identidad muy ligada a la agricultura, la cultura y la vida universitaria, siendo un punto esencial para entender la historia y el carácter de las tierras de Ponent. 26 ene 2026 — En el siglo XII, Lleida ( LLEIDA LA CIUDAD ) fue conquistada por los cristianos y se consolidó como un centro clave en la Corona d...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46027','monumento','Núcleos de población de Alfarràs','El término municipal incluye los siguientes núcleos de población: Andaní.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46027','iglesia','Iglesia Vieja de San Pedro','Ruinas consolidadas de un templo barroco del siglo XVIII que conserva su monumental fachada de sillería calcárea con hornacina central y la estructura del campanario de torre, destacando en el entorno del núcleo histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46027','monumento','Fábrica de la Colonia Hilaturas Casals','Complejo textil de finales del siglo XIX situado junto al río Noguera Ribagorçana que constituye un testimonio de la arqueología industrial ilerdense al mantener sus naves diáfanas de ladrillo visto y compuertas hidráulicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90618','iglesia','Iglesia de San Pedro de Alfés','Templo de origen románico profundamente reformado en el siglo XVI bajo los cánones del gótico tardío que exhibe una portada meridional de arquivoltas apuntadas de cantería y un robusto campanario de planta rectangular provisto de aspilleras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90618','monumento','Poblado Inédito de La Vansa','Yacimiento arqueológico medieval que conserva los cimientos y plantas de mampostería basta de un núcleo fortificado deshabitado, silos excavados en roca y fragmentos de cerámica gris tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25015','monumento','Núcleos de población de Algerri','El término municipal incluye los siguientes núcleos de población: La Figuera y La Colònia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25015','iglesia','Iglesia de Nuestra Señora de la Purificación','Monumental edificio barroco del siglo XVIII que destaca por su fachada clasicista de sillería caliza vista, una amplia nave con capillas intercomunicadas y un esbelto campanario octogonal que domina la llanura de la comarca de la Noguera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25015','monumento','Castillo de Algerri','Vestigios de una estratégica fortaleza medieval del siglo XI emplazada sobre un cerro de los que subsisten potentes lienzos de muralla de mampostería regular aglutinada con cal y restos de silos de almacenamiento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25017','monumento','Núcleos de población de Alins','El término municipal incluye los siguientes núcleos de población: Àreu, Tor, Norís, Ainet de Besan y Besan.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25017','iglesia','Iglesia de San Martín de Àreu','Excepcional templo románico del siglo XII edificado en sillería de alta montaña que presenta una sola nave, un ábside semicircular decorado exteriormente con arcuaciones de estilo lombardo y un imponente campanario de torre con ventanas geminadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25017','monumento','Fuerza de Tor (La Força)','Conjunto fortificado medieval situado en un emplazamiento fronterizo pirenaico del que subsisten los alzados de piedra basta de una torre vigía cilíndrica y muros perimetrales defensivos integrados sobre un escarpado promontorio rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25017','ermita','Ermita de San Feliu de Sorteny','Pequeño oratorio rural de origen altomedieval que consta de una austera planta de cajón con muros de mampostería basta adaptados a la climatología del Pirineo y una espadaña de un solo ojo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25019','iglesia','Iglesia de la Merced de Almacelles','Templo parroquial de traza neoclásica construido en el siglo XVIII según los planos urbanísticos ilustrados de la villa que exhibe una fachada de sillería con frontón triangular y un robusto campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25019','monumento','Yacimiento Arqueológico de El Vilot','Asentamiento medieval despoblado que conserva las plantas de piedra de las antiguas viviendas, la base de una torre defensiva y silos de cereal excavados en el terreno que atestiguan el poblamiento altomedieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25020','iglesia','Iglesia de San Juan Bautista','Edificio religioso barroco del siglo XVIII construido con aparejo de mampostería regular enlucida que muestra una fachada de líneas neoclásicas con portalada moldurada de piedra local y un esbelto campanario que corona el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25021','iglesia','Iglesia de Santa María de Almenar','Monumental templo edificado en el siglo XIV en estilo gótico que presenta una amplia nave única con capillas laterales entre los contrafuertes robustos, una portada con arquivoltas apuntadas y una imponente torre-campanario octogonal de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25022','monumento','Castillo de Alòs','Monumental fortaleza medieval del siglo X emplazada de forma estratégica sobre un desfiladero del río Segre que conserva su torre del homenaje cilíndrica de sillería basta, potentes lienzos de murallas almenadas y restos de la capilla románica de San Martín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25022','iglesia','Iglesia de San Félix','Templo de base románica profundamente transformado en época barroca que mantiene de su fábrica del siglo XII una notable portada meridional de arquivoltas molduradas en piedra caliza regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25023','iglesia','Iglesia de San Bartolomé','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de paramentos enlucidos con portal de cantería moldurada flanqueada por pilastras, un interior de nave única y una recia torrecampanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25024','monumento','Núcleos de población de Alt Àneu','El término municipal incluye los siguientes núcleos de población: València d''Àneu, Esterri d''Àneu, Alós, Isil, Sorpe y Borén.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25024','iglesia','Iglesia de San Juan de Isil','Joya cumbre del románico pirenaico del siglo XII declarada Monumento Nacional que destaca por su impecable fábrica de sillería de alta montaña asentada junto al río Noguera Pallaresa, su cabecera absidial con motivos lombardos y una portada meridional de múltiples arquivoltas esculpidas con relieves zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25024','monumento','Castillo de Valencia de Àneu','Ruinas consolidadas de una monumental fortaleza medieval del siglo XI que constituyó el último bastión de los condes del Pallars, conservando tramos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25024','iglesia','Iglesia de los Santos Justo y Pastor de Son','Edificio religioso románico del siglo XII que destaca por su esbelto campanario de torre exento de planta cuadrada con ventanas geminadas y por albergar en su interior un valioso retablo gótico de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25027','iglesia','Iglesia de San Martín de Anglesola','Templo parroquial de origen gótico profundamente transformado en el periodo barroco (siglo XVIII) que destaca por conservar en su fachada una monumental portada gótica con relieves de los apóstoles y un imponente campanario de torre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25029','palacio','Castillo-Palacio de los Duques de Cardona','Ruinas consolidadas de una imponente fortaleza medieval reconstruida como palacio renacentista en el siglo XVI de la que subsisten la gran torre del homenaje cuadrangular de sillería, lienzos de muralla provistos de aspilleras y bodegas abovedadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25029','monumento','Yacimiento de la Fortaleza Ibérica de Els Vilars','Espectacular asentamiento fortificado de la Edad del Hierro (siglo VII a.C.) único en la península al conservar una monumental muralla de piedra caliza con doce torreones, un foso perimetral y una barrera defensiva de piedras hincadas (chevaux-de-frise).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25031','monumento','Núcleos de población de Arres','El término municipal incluye los siguientes núcleos de población: Arres de Jos y Arres de Sus.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25031','iglesia','Iglesia de San Juan de Arres','Pequeño templo de arquitectura gótica aranesa construido en sillería de pizarra rústica de los Pirineos que presenta una sola nave con bóveda de cañón, ventanas apuntadas y un campanario de espadaña de dos vanos sobre la fachada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25032','monumento','Conjunto Histórico de Arsèguel','Núcleo rural fortificado de origen medieval que destaca por la conservación de sus masías tradicionales pirenaicas con muros de mampostería basta, voladizos de madera noble de sabina y tejados de losas de pizarra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25032','iglesia','Iglesia de Santa Coloma de Arsèguel','Templo románico del siglo XII edificado en sillería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y un recio campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25033','iglesia','Iglesia de Miguel Arcángel','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25034','monumento','Núcleos de población de Artesa de Segre','El término municipal incluye los siguientes núcleos de población: Baldomar, Montmagastre, Anya, Collfred y Tudela de Segre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25034','iglesia','Castillo y Colegiata de Montmagastre','Ruinas de una estratégica fortaleza defensiva militar y templo del siglo XI emplazadas en la cumbre de un espectacular risco de las que subsisten potentes lienzos de la muralla de sillería basta y la cripta románica de la colegiata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25034','iglesia','Iglesia de San Pedro de Baldomar','Edificio religioso de origen románico profundamente transformado en época barroca que destaca por albergar una notable cabecera de sillería caliza regular y una portada meridional de cantería moldurada flanqueada por una recia torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25036','iglesia','Iglesia de San Julián de Aspa','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran rosetón moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25037','monumento','Núcleos de población de Avellanes i Santa Linya, Les','El término municipal incluye los siguientes núcleos de población: Les Avellanes, Santa Linya, Tartareu y Vilanova de la Sal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25037','iglesia','Monasterio de Santa María de Bellpuig de les Avellanes','Magna abadía medieval de la orden premonstratense fundada en el siglo XII que destaca por su monumental iglesia de transición, un bellísimo claustro románico de sillería perfecta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25037','monumento','Castillo de Tartareu','Ruinas de una estratégica fortificación islámica y condal del siglo XI emplazada sobre una colina de las que subsisten potentes lienzos de muralla de mampostería basta y la base de su gran torre del homenaje circular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90619','monumento','Núcleos de población de Baix Pallars','El término municipal incluye los siguientes núcleos de población: Gerri de la Sal, Peramea, Bretui, Montcortès y Sellui.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90619','iglesia','Monasterio de Santa María de Gerri de la Sal','Magna iglesia abacial románica del siglo XII que destaca por su planta basilical de tres naves, una fastuosa portada occidental de múltiples arquivoltas molduradas sobre columnas y una monumental espadaña de tres pisos que corona el conjunto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90619','monumento','Alfolí de la Sal (Casa de la Sal)','Espectacular y monumental almacén industrial de origen medieval reconstruido en el siglo XVIII para la explotación de las salinas que constituye un exponente de la arquitectura civil al conservar sus grandes salas de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90619','monumento','Conjunto Histórico de Peramea','Núcleo urbano fortificado de origen medieval que conserva de forma impecable su trama urbana amurallada con portales de acceso monumentales de arco apuntado dovelado, masías de cantería regular y la torre vigía de los condes de Pallars.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25040','iglesia','Iglesia de Santa María de Balaguer','Monumental templo gótico del siglo XIV construido en sillería caliza regular que constituye el símbolo de la ciudad al presentar una imponente','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25040','iglesia','Santuario del Santo Cristo (Sant Crist de Balaguer)','Complejo religioso de factura barroca edificado en el siglo XVIII sobre la antigua mezquita mayor del que destaca su fachada monumental de sillería, su amplio interior cupulado y por custodiar la venerada talla del Santo Cristo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25040','monumento','Castillo Formós (Castell Formós)','Ruinas de la fastuosa alcazaba islámica del siglo XI y posterior palacio residencial de los condes de Urgell que conservan lienzos de muralla califal con paramentos de cantería regular y restos de decoración arquitectónica de yeserías estucadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25041','monumento','Castillo de la Encomienda de Barbens','Palacio fortificado del siglo XVI de la Orden de los Caballeros Hospitalarios levantado sobre una estructura medieval anterior que presenta una simétrica fachada de sillería caliza vista, ventanas con molduras clasicistas y portales dovelados de arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25044','monumento','Núcleos de población de Bassella','El término municipal incluye los siguientes núcleos de población: Ogern, Altés, Clua y Aguilar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25044','iglesia','Iglesia de San Pedro de Altés','Templo de origen románico profundamente transformado en el periodo barroco (siglo XVIII) que mantiene su cabecera absidial de sillería caliza regular y presenta una fachada con portada moldurada flanqueada por una recia torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25045','iglesia','Iglesia de San Pedro de Bausen','Templo de factura gótica aranesa construido en sillería de pizarra rústica de los Pirineos que presenta una sola nave con bóveda de cañón apuntada, un ábside poligonal orientado a levante y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25045','monumento','Cementerio de Teresa','Singular recinto funerario civil exento construido en el siglo XX en un prado de alta montaña que constituye un hito de la memoria popular al albergar una única sepultura rodeada por un muro tosco de mampostería seca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25046','palacio','Ayuntamiento de Belianes (Antiguo Palacio de los Navés)','Edificio civil de estilo renacentista construido a principios del siglo XVII que destaca por su simétrica fachada de sillería caliza vista, sus ventanas con molduras clasicistas y un gran portal dovelado de arco de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25170','iglesia','Iglesia de San Antonio Abad','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una monumental fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25047','monumento','Núcleos de población de Bellcaire d''Urgell','El término municipal incluye los siguientes núcleos de población: Pedrís.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25047','iglesia','Iglesia de Santa María de Bellcaire','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90620','iglesia','Iglesia de San Miguel','Edificio religioso de época barroca (siglo XVII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una portada clasicista de cantería moldurada y una esbelta torrecampanario que domina el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25050','monumento','Núcleos de población de Bellpuig','El término municipal incluye los siguientes núcleos de población: Seana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25050','iglesia','Sepulcro de Ramón Folch de Cardona (Iglesia de San Nicolás)','Obra cumbre del Renacimiento escultórico italiano en España tallada en mármol de Carrara por el escultor Giovanni da Nola en 1522, consistente en un monumental mausoleo arquitectónico con relieves alegóricos y figuras exentas de virtuosismo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25050','iglesia','Convento de San Bartolomé','Cenobio franciscano fundado en el siglo XV de estilo gótico tardío y de transición renacentista que destaca por su claustro de dos pisos con galerías de arcos rebajados calados, una espectacular escalera de caracol exenta y la monumental capilla ducal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25051','monumento','Núcleos de población de Bellver de Cerdanya','El término municipal incluye los siguientes núcleos de población: Talló, Baltarga, Olià, Bor y Pi.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25051','catedral','Iglesia de Santa María de Talló (La Catedral de la Cerdanya)','Magna iglesia románica del siglo XII que constituye el templo religioso más grande de la comarca, caracterizada por su imponente nave única con bóveda de cañón apuntada, un ábside semicircular perfecto de sillería regular y su portada meridional con herrajes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25051','monumento','Barrio Viejo y Castillo de Bellver','Núcleo urbano fortificado de origen medieval edificado sobre un promontorio rocoso que conserva lienzos de muralla almenados, portales de acceso de arco apuntado dovelado, masías tradicionales de cantería y la torre vigía cuadrangular de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25055','monumento','Núcleos de población de Biosca','El término municipal incluye los siguientes núcleos de población: Lloberola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25055','monumento','Castillo de Biosca','Ruinas de una estratégica fortaleza medieval del siglo XI emplazada sobre una cresta rocosa de las que subsisten la torre del homenaje de planta circular ejecutada en sillería regular de piedra caliza y la primitiva capilla románica de nave única con ábside semicircular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25055','iglesia','Iglesia de San Miguel de Lloberola','Edificio religioso románico del siglo XII edificado en cantería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25059','iglesia','Iglesia de la Purificación de María (Era Mair de Diu de Mother)','Excepcional joya del románico aranés del siglo XII edificado en sillería regular de granito y pizarra que destaca por su planta basilical de tres naves con bóvedas de arista,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25062','monumento','Núcleos de población de Camarasa','El término municipal incluye los siguientes núcleos de población: Sant Llorenç de de Montgai, Fontllonga, Figuerola de Meià y L''Ametlla de Montsec.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25062','monumento','Castillo de Camarasa','Ruinas de una estratégica alcazaba islámica y posterior fortaleza condal del siglo XI emplazada sobre un acantilado rocoso que conserva tramos de muralla con aparejo regular y saeteras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25062','iglesia','Iglesia de San Miguel de Camarasa','Templo de transición románico-gótico edificado en el siglo XIII en cantería perfecta que presenta una imponente cabecera triabsidial, una portada con arquivoltas molduradas sobre columnas y una robusta torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25071','monumento','Núcleos de población de Cava','El término municipal incluye los siguientes núcleos de población: Anserall y El Querforadat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25071','monumento','Castillo de Querforadat','Ruinas de una antigua casa fuerte señorial del siglo XII de la que subsisten tramos notables de muros de mampostería basta asentados de forma audaz sobre una gran peña rocosa calcárea de los Pirineos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25072','monumento','Universidad de Cervera','Monumental e impresionante complejo académico borbónico proyectado por el arquitecto Francisco de Sabatini en el siglo XVIII en estilo barroco y neoclásico, caracterizado por su colosal fachada de sillería caliza con portada monumental, sus patios interiores porticados y su capilla cupulada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25072','iglesia','Iglesia de Santa María de Cervera','Magna iglesia de traza gótica construida entre los siglos XIII y XIV que presenta una imponente nave única de gran anchura con capillas laterales entre contrafuertes robustos, un soberbio deambulatorio o girola en su cabecera y un campanario octogonal calado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25072','monumento','Paeria de Cervera (Ayuntamiento)','Palacio civil barroco construido en el siglo XVII que destaca por su fachada de sillería caliza vista provista de grandes ventanales con molduras y ménsulas esculpidas con figuras humanas alegóricas de los oficios tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25073','iglesia','Iglesia de San Miguel','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25073','monumento','Anexo','Municipios de la provincia de Lérida Anexo: Municipios de la provincia de Lérida Nombre oficial Nombre en castellano Población (2022) Arbeca Arbeca 2100 Arres Arrés 61...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25074','monumento','Castillo de Ciutadilla','Monumental fortaleza medieval del siglo XI reformada en el siglo XVI como palacio residencial fortificado de estilo renacentista que destaca por su imponente torre del homenaje de planta cuadrangular, sus ventanales de líneas clasicistas y un gran patio de armas central porticado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25074','iglesia','Iglesia de San Miguel','Templo parroquial de origen románico profundamente transformado en el periodo barroco (siglo XVIII) que exhibe una fachada de sillería vista con portada clasicista moldurada, un interior de nave única y un recio campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25075','monumento','Núcleos de población de Clariana de Cardener','El término municipal incluye los siguientes núcleos de población: Hortoneda y Sant Just d''Ardèvol.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25075','iglesia','Iglesia de San Serni de Clariana','Edificio religioso románico del siglo XII edificado en cantería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25075','monumento','Torre de Ardèvol','Antigua torre de vigía y defensa medieval de planta cuadrangular erigida en sillería basta cementada con cal que servía para el control del paso estratégico de la comarca del Solsonès.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25076','monumento','Roca de los Moros (Roca dels Moros)','Excepcional y mundialmente famoso abrigo rupestre declarado Patrimonio de la Humanidad por la UNESCO que conserva un soberbio ciclo de pinturas prehistóricas del arte levantino y esquemático, destacando una famosa escena de danza fálica con figuras femeninas silueteadas en tonos rojizos y negros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25076','iglesia','Iglesia de la Asunción','Templo parroquial de traza barroca rural (siglo XVIII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal con capillas laterales y una espadaña de tres vanos sobre el hastial de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25077','monumento','Núcleos de población de Coll de Nargó','El término municipal incluye los siguientes núcleos de población: Montanissell, Sallent de Nargó y Valldarques.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25077','iglesia','Iglesia de San Clemente de Coll de Nargó','Joya cumbre del románico lombardo del siglo XI que presenta una planta de nave única muy esbelta con bóveda de cañón, un ábside semicircular decorado exteriormente con arcuaciones ciegas y un campanario de torre prerrománico con base en talud único en su tipología.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25077','monumento','Mirador del Cretácico (Yacimiento de Huevos de Dinosaurio)','Espectacular paraje paleontológico musealizado que alberga una de las colecciones de nidadas y restos de cáscaras de huevos de titanosaurios más importantes de Europa, impresas sobre estratos geológicos del final de la era de los reptiles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25077','iglesia','Iglesia de San Román de Valldarques','Templo románico del siglo XII aislado en un promontorio boscoso que destaca por la pureza geométrica de su nave única, su ábside semicircular orientado al este y una robusta torre-campanario exenta ejecutada en sillería caliza regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25161','monumento','Núcleos de población de Conca de Dalt','El término municipal incluye los siguientes núcleos de población: Claverol, Hortoneda, Sossís y Pessonada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25161','iglesia','Iglesia de Santa María de Claverol','Templo de base románica profundamente transformado en época barroca que mantiene de su fábrica medieval muros perimetrales de mampostería basta y destaca por su emplazamiento colgado sobre un desfiladero rocoso que domina el valle del río Noguera Pallaresa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25161','monumento','Torre de Pessonada','Ruinas de una estratégica fortaleza defensiva militar del siglo XI de las que subsiste una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25079','monumento','Núcleos de población de Cubells','El término municipal incluye los siguientes núcleos de población: Torre de Fluvià.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25079','iglesia','Iglesia de Santa María del Castillo de Cubells','Monumental templo de transición románico-gótico edificado en el siglo XIII en cantería perfecta que destaca por su fastuosa portada meridional de seis arquivoltas en degradación profusamente esculpidas por la escuela de Lleida con motivos florales y geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25079','iglesia','Iglesia de San Pedro','Edificio religioso de traza gótica (siglo XIV) que presenta una imponente nave única de gran anchura con capillas laterales entre contrafuertes robustos, una portada con arquivoltas apuntadas y una robusta torrecampanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25082','monumento','Torre de los Moros (Torre dels Moros)','Antigua torre de vigía y defensa medieval de planta circular construida en el siglo XII mediante aparejo de mampostería regular con mortero de cal que domina el acceso al parque nacional, conservando saeteras originales y su vano elevado de entrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25082','iglesia','Iglesia de Santa Llogaia de Espot','Templo de base medieval profundamente transformado en época barroca que exhibe una fachada muy sobria con porche cubierto tradicional, muros exteriores de mampostería basta de alta montaña y una recia torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25088','iglesia','Iglesia de San Vicente de Estamariu','Monumental templo románico del siglo XI de planta basilical que presenta tres naves separadas por pilares cuadrangulares, tres ábsides semicirculares perfectos provistos de decoración exterior de estilo lombardo y un interior con excepcionales restos de pinturas murales al fresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25088','iglesia','Iglesia Parroquial de San Juan','Edificio religioso de época barroca (siglo XVII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una portada clasicista de cantería moldurada y una esbelta torre-campanario que domina el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25085','monumento','Núcleos de población de Estaràs','El término municipal incluye los siguientes núcleos de población: Altariba, Ferran, Gàver y Malacara.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25085','monumento','Castillo de Estaràs','Caserón señorial fortificado del siglo XIV de planta rectangular y muros de mampostería basta que conserva ventanas conopiales talladas en piedra caliza, portales dovelados de arco de medio punto y dependencias auxiliares agrícolas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25085','iglesia','Iglesia de San Julián de Alta-riba','Pequeña capilla románica del siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante sin ornamentación exterior y un campanario de espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27005','monumento','Puente románico de Esterri d''Àneu','Monumental viaducto de origen medieval (siglo XIII) ejecutado en cantería perfecta de piedra pizarra que salva el cauce del río Noguera Pallaresa mediante dos grandes arcadas de medio punto apoyadas sobre tajamares asentados en la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27005','iglesia','Iglesia de San Vicente','Templo parroquial de traza barroca clasicista construido en el siglo XVIII que muestra una planta de nave única con capillas laterales entre contrafuertes robustos, una portada monumental de cantería moldurada flanqueada por pilastras y un esbelto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25087','monumento','Núcleos de población de Esterri de Cardós','El término municipal incluye los siguientes núcleos de población: Arròs de Cardós y Benante.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25087','iglesia','Iglesia de San Pablo de Esterri de Cardós','Templo románico del siglo XII edificado en sillería de alta montaña que destaca por su ábside semicircular orientado a levante y por haber albergado en su interior un soberbio ciclo de pinturas murales al fresco que hoy se custodian en el Museo Nacional de Arte de Catalunya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25089','monumento','Núcleos de población de Farrera','El término municipal incluye los siguientes núcleos de población: Alendo, Burg, Glorieta y Montesclado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25089','iglesia','Iglesia de Santa Eulalia de Alendo','Pequeño santuario románico del siglo XI edificado en piedra pizarra rústica que consta de una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y una espadaña de un solo vano sobre el hastial de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25908','monumento','Núcleos de población de Fígols i Alinyà','El término municipal incluye los siguientes núcleos de población: Fígols, Alinyà, Llobera y Perles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25908','iglesia','Iglesia de San Víctor de Fígols','Templo románico del siglo XII que destaca por su ábside semicircular decorado exteriormente con un friso de arcuaciones lombardas y lesenas de piedra caliza, albergando en su interior una notable portada de cantería moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25908','monumento','Desfiladero de Perles','Entorno natural escarpado provisto de antiguos puentes de mampostería basta, canales de riego tradicionales y azudes que atestiguan el aprovechamiento histórico del agua en la comarca de l''Alt Urgell.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25092','monumento','Castillo de la Floresta','Palacio fortificado del gótico civil y del Renacimiento construido en el siglo XIV que presenta un magnífico patio de armas central con galerías de arcos rebajados, ventanas ajimezadas, estancias nobles y una recia torre del homenaje de planta cuadrada con almenas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25093','iglesia','Iglesia de la Asunción','Templo parroquial de factura barroca rural reedificado en el siglo XVIII que presenta una fachada enlucida con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular ejecutada en piedra caliza local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25094','monumento','Núcleos de población de Foradada','El término municipal incluye los siguientes núcleos de población: Montsonís, Rubió de Baix y Marcovau.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25094','monumento','Castillo de Montsonís','Monumental e imponente fortaleza medieval documentada desde el siglo XI que constituye uno de los conjuntos fortificados habitados mejor conservados de Catalunya, caracterizado por su recinto amurallado de sillería, su torre de defensa con matacanes y amplios salones góticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25094','iglesia','Santuario de la Virgen de Salgar','Complejo religioso edificado en el siglo XVII de forma espectacular bajo una enorme cavidad natural de roca calcárea, integrado por una iglesia románica reformada, los restos de un claustro gótico y dependencias monásticas adaptadas al desfiladero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25096','monumento','Núcleos de población de La Fuliola','El término municipal incluye los siguientes núcleos de población: Boldú.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25096','iglesia','Iglesia de Santa Lucía de la Fuliola','Templo parroquial de traza barroca clasicista edificado en el siglo XVIII que presenta una fachada de sillería caliza vista con portada moldurada flanqueada por pilastras, una nave de gran amplitud y un esbelto campanario octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25096','monumento','Núcleo de la Villa Cerrada (Vila Closa)','Vestigios del trazado urbano amurallado medieval del que subsisten calles estrechas y portales de acceso de arco de medio punto dovelado integrados en las fachadas de piedra tradicionales de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25097','iglesia','Iglesia de Santa María','Templo de traza barroca rural edificado en el siglo XVIII sobre un templo medieval previo del que subsiste una sobria portalada de sillería caliza con arquivoltas molduradas, un interior de nave única y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25097','monumento','La Bassa de la Villa','Antigua estructura hidráulica comunal construida mediante muros circulares de mampostería basta y mortero de cal calavera que servía tradicionalmente para el','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25099','iglesia','Iglesia de San Salvador','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una monumental fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25100','monumento','Núcleos de población de Gósol','El término municipal incluye los siguientes núcleos de población: Sorribes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25100','monumento','Castillo y Núcleo Medieval de Gósol','Ruinas de una monumental fortaleza medieval del siglo XI emplazada sobre una imponente cresta rocosa calcárea a los pies del macizo del Pedraforca de las que subsisten potentes lienzos de la muralla perimetral defensiva, la base de la torre del homenaje y la iglesia románica de Santa María.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25100','iglesia','Iglesia de San Francisco de Sorribes','Pequeña capilla románica del siglo XII que consta de un aparejo tosco de sillarejo calizo, una nave longitudinal rematada por un ábside semicircular orientado al este y una espadaña de dos vanos sobre la fachada de poniente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25101','iglesia','Iglesia de Santa María de la Gracia','Monumental templo barroco del siglo XVIII conocido popularmente como la "Catedral de les Garrigues" debido a sus grandes dimensiones, el cual destaca por su imponente fachada de sillería vista de líneas neoclásicas con portada moldurada flanqueada por columnas y un campanario de torre octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25102','iglesia','Iglesia de San Jaime','Templo parroquial de traza barroca clasicista edificado en el siglo XVIII cerca de la confluencia de los ríos Cinca y Segre que presenta una fachada enlucida con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25102','ermita','Ermita de San Jaime','Pequeño oratorio rural del siglo XVIII edificado en mampostería basta que presenta una planta de cajón muy sobria, un porche delantero techado a dos aguas para refugio de los fieles y una espadaña de un solo vano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25109','monumento','Conjunto Histórico-Artístico de la Villa de Guimerà','Núcleo urbano medieval de primer orden que destaca por la conservación impecable de sus calles laberínticas escalonadas provistas de arcadas, portales de acceso de arco de medio punto dovelado y masías tradicionales edificadas con muros de mampostería basta y ventanas con dinteles y alféizares de piedra arenisca labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25109','monumento','Castillo de Guimerà','Ruinas de una estratégica fortaleza medieval documentada desde el siglo XI de la que subsiste una imponente y esbelta torre de vigía cilíndrica de sillería de piedra caliza regular, la cual corona un promontorio estratégico que domina el valle del río Corb.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25109','iglesia','Iglesia de Santa María','Templo de traza gótica edificado en el siglo XIV que presenta una imponente nave única de gran anchura, capillas laterales entre contrafuertes robustos, una portada con arquivoltas apuntadas molduradas y un extraordinario retablo de alabastro policromado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25109','iglesia','Monasterio de Vallsanta','Ruinas consolidadas de un cenobio femenino de la orden del Císter fundado en el siglo XIII del que destaca una hilera de ventanales apuntados de sillería regular y tracería calada gótica que se integran de forma pintoresca en el paisaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25110','monumento','Núcleos de población de Guissona','El término municipal incluye los siguientes núcleos de población: Guarda-si-vols y Selvanera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25110','monumento','Parque Arqueológico de la Ciudad Romana de Iesso','Monumental y musealizado yacimiento romano que conserva las plantas completas de la muralla de sillería con una torre de defensa, un complejo termal con su hipocausto subterráneo y estancias residenciales con pavimentos de opus signinum.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25110','iglesia','Colegiata de Santa María de Guissona','Monumental basílica reedificada en el siglo XVIII en estilo barroco clasicista que destaca por su imponente fachada de sillería vista con portada monumental flanqueada por pilastras, un amplio interior de tres naves de gran altura y un robusto campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25110','palacio','Palacio de la Obra (Palau de l''Òbra)','Ruinas de una suntuosa residencia fortificada de los obispos de Urgell construida a principios del siglo XVI de la que se conservan los potentes muros perimetrales de mampostería regular, portales dovelados de arco de medio punto y restos de decoración renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25113','monumento','Núcleos de población de Ivars d''Urgell','El término municipal incluye los siguientes núcleos de población: Vallverd.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25113','iglesia','Iglesia de San Andrés','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de paramentos enlucidos con portal de cantería moldurada flanqueada por pilastras, un interior de nave única y una recia torrecampanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25112','iglesia','Iglesia de la Concepción','Edificio religioso de época barroca (siglo XVII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25910','monumento','Núcleos de población de Josa i Tuixén','El término municipal incluye los siguientes núcleos de población: Josa de Cadí y Tuixén.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25910','iglesia','Iglesia de San Esteban de Josa','Templo románico de alta montaña edificado en el siglo XII sobre una base rocosa que consta de una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y un recio campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25910','iglesia','Iglesia de San Esteban de Tuixén','Edificio religioso de origen medieval transformado en el siglo XVII en estilo barroco rural con líneas neoclásicas que presenta una amplia nave única con capillas intercomunicadas, una fachada de paramentos enlucidos con portal de cantería moldurada y un campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25119','iglesia','Iglesia de la Transfiguración','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada monumental de sillería vista con portada clasicista moldurada, un interior de tres naves de gran amplitud y un esbelto campanario octogonal con remate cupulado de azulejería vidriada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25119','monumento','Núcleo de la Villa Cerrada (Vila Closa)','Vestigios del trazado urbano amurallado medieval del que subsisten calles estrechas y portales de acceso de arco de medio punto dovelado integrados en las fachadas de piedra tradicionales de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25121','monumento','Baronía de Les (Castillo de Pijoan)','Ruinas de una estratégica fortaleza medieval aranesa de la que subsiste una imponente torre de vigía de planta cuadrada ejecutada en sillería de piedra pizarra rústica de los Pirineos, saeteras defensivas a diferentes alturas y un acceso elevado original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25121','iglesia','Capilla de San Blas','Pequeño santuario románico del siglo XII edificado en cantería regular que presenta una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante sin ornamentación exterior y una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25122','iglesia','Iglesia de Santa María de Linyola','Monumental templo gótico del siglo XIV edificado en sillería caliza regular que destaca por su imponente fachada principal con un colosal rosetón de tracería calada y una esbelta torre-campanario de planta octogonal que domina la plana del Urgell.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25122','palacio','Palacio de los Condes de Urgell (Ayuntamiento)','Edificio civil de estilo renacentista construido a principios del siglo XVI que presenta una simétrica fachada de sillería vista, sus ventanas con molduras clasicistas y un gran portal dovelado de arco de medio punto en el cuerpo principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25123','monumento','Núcleos de población de Lladorre','El término municipal incluye los siguientes núcleos de población: Boldís d''Avall, Boldís de Dalt, Llavorre, Tavascan y Graus.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25123','monumento','Puente románico de Tavascan','Monumental viaducto de origen medieval (siglo XIII) ejecutado en cantería perfecta de piedra pizarra que salva el cauce del río mediante una sola y gran arcada de medio punto apoyada sobre tajamares asentados en la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25123','iglesia','Iglesia de San Martín de Lladorre','Templo románico de alta montaña edificado en el siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado al este con decoración exterior de estilo lombardo y una robusta torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25123','iglesia','Iglesia de San Pedro de Boldís d''Avall','Pequeña capilla románica del siglo XII que presenta un aparejo regular de sillarejo calizo, una nave longitudinal rematada por un ábside semicircular liso y un campanario de espadaña de dos vanos sobre la fachada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25124','monumento','Núcleos de población de Lladurs','El término municipal incluye los siguientes núcleos de población: Timoneda, Montpol y Llena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25124','monumento','Castillo de Lladurs','Ruinas de una estratégica fortaleza medieval del siglo XI emplazada sobre una cresta rocosa del Solsonès de las que subsisten la torre del homenaje de planta cuadrangular ejecutada en sillería regular de piedra caliza y la primitiva capilla románica de nave única con ábside.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25124','iglesia','Iglesia de San Saturnino de Timoneda','Edificio religioso románico del siglo XII edificado en cantería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25125','iglesia','Iglesia de Santa María de Llardecans','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de sillería caliza vista con portada clasicista moldurada, un interior de tres naves de gran amplitud y un esbelto campanario octogonal con remate cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25125','monumento','Arco de la Villa Cerrada','Vestigio monumental del antiguo recinto fortificado medieval del núcleo consistente en un gran portal de arco de medio punto con grandes dovelas integrado en las estructuras de piedra tradicionales de la calle mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25127','monumento','Núcleos de población de Lles de Cerdanya','El término municipal incluye los siguientes núcleos de población: Arànser, Músser, Lles y Viliella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25127','iglesia','Iglesia de San Fructuoso de Músser','Templo románico del siglo XII edificado en sillería de granito de los Pirineos que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una espléndida portada meridional de tres arquivoltas en degradación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25127','iglesia','Iglesia de San Esteban de Lles','Edificio religioso de origen románico profundamente transformado en época barroca que mantiene de su fábrica del siglo XII la planta de nave única y destaca por su portalada modificada de cantería moldurada flanqueada por una recia torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25127','monumento','Castillo de Lles','Ruinas de una estratégica fortaleza militar del siglo XI emplazada sobre una cresta rocosa de las que subsisten los potentes cimientos de la torre del homenaje de planta cuadrangular y tramos de la muralla defensiva perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25128','iglesia','Iglesia de Santa María de Llimiana','Monumental basílica románica del siglo XI que se alza de forma espectacular sobre un colosal risco que domina la cuenca de Tremp,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25128','ermita','Ermita de San Salvador del Bosch','Excepcional oratorio románico del siglo XII aislado en un promontorio boscoso que destaca por la pureza geométrica de su nave única, su ábside semicircular orientado al este con cornisa de canecillos lisos y muros ejecutados en sillería caliza regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25129','monumento','Núcleos de población de Llobera','El término municipal incluye los siguientes núcleos de población: Peracamps y Torredenegó.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25129','monumento','Castillo de Peracamps','Ruinas de una estratégica fortificación militar del siglo XI de las que subsiste una imponente torre del homenaje de planta cuadrangular ejecutada con aparejo regular de grandes bloques de piedra caliza cementados con mortero de cal, la cual corona un promontorio estratégico que dominó las batallas medievales y carlistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25129','iglesia','Iglesia de San Pedro de Llobera','Edificio religioso románico del siglo XII edificado en cantería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25129','monumento','Dolmen de la Villa de Llobera','Destacado monumento megalítico del Neolítico final emplazado en su término municipal que conserva su cámara funeraria delimitada por grandes losas de piedra local hincadas verticalmente en el terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','catedral','Catedral de la Seo Vieja (Seu Vella)','Magna y monumental catedral románico-gótica construida entre los siglos XII y XIV que constituye la obra cumbre de la arquitectura ilerdense, célebre por su espectacular claustro gótico exento provisto de inmensos ventanales calados con tracerías calizas de gran virtuosismo geométrico, su monumental portada de los Fillols de la escuela de Lleida y una esbelta torre-campanario octogonal de sesenta metros de altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','monumento','Castillo del Rey (La Suda)','Fortaleza e imponente alcazaba islámica reedificada en época condal en el siglo XIII que conserva los potentes lienzos de muralla de sillería de piedra caliza regular de su nave meridional provistos de ventanales góticos apuntados, sirviendo históricamente como residencia real de la Corona de Aragón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','monumento','Castillo de Gardeny','Monumental complejo fortificado medieval edificado por los caballeros templarios en el siglo XII sobre una meseta estratégica que destaca por su iglesia románica de Santa María de Gardeny con bóveda de cañón apuntada y su recia torre del homenaje palaciega de dos pisos ejecutada en cantería perfecta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','palacio','Palacio de la Paeria','Palacio civil del gótico civil catalán construido en el siglo XIII que funciona como sede consistorial, caracterizado por su fachada monumental de sillería vista a la plaza mayor provista de ventanas coronelas geminadas de arcos de medio punto y un patio interior porticado de gran belleza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27008','monumento','Antiguo Hospital de Santa María','Espectacular complejo asistencial del gótico tardío y del Renacimiento edificado en el siglo XV que presenta un magnífico claustro central de arcos rebajados calados sustentados sobre esbeltas columnas y una majestuosa fachada de sillería con un portal de arco apuntado dovelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25130','palacio','Castillo-Palacio de Maldà','Monumental fortaleza medieval del siglo XI transformada en palacio residencial de estilo renacentista y barroco en el siglo XVIII que destaca por su imponente fachada de sillería caliza vista de grandes dimensiones, sus ventanas con molduras clasicistas y las estancias nobles abovedadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25130','iglesia','Iglesia de Santa María de Maldà','Templo parroquial de traza barroca clasicista edificado en el siglo XVIII que presenta una fachada de sillería caliza vista con portada moldurada flanqueada por pilastras, una nave de gran amplitud con capillas intercomunicadas y un esbelto campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25131','iglesia','Iglesia de San Bartolomé','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior cerca de la desembocadura del río Cinca en el Segre que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90621','monumento','Núcleos de población de Massoteres','El término municipal incluye los siguientes núcleos de población: Palouet y Talteüll.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90621','iglesia','Iglesia de San Pedro de Talteüll','Templo románico del siglo XII edificado en sillería regular que presenta una planta de nave única con bóveda de cañón apuntada, un ábside semicircular orientado al este con decoración exterior de estilo lombardo de dobles arquillos ciegos y una recia torrecampanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90621','iglesia','Iglesia de San Jaime de Palouet','Edificio religioso románico del siglo XII modificado en época barroca que presenta un ábside semicircular liso orientado a levante, una portada meridional de arco de medio punto y un campanario de espadaña de dos vanos ejecutado con aparejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25134','iglesia','Iglesia de San Vicente de Menàrguens','Templo de base gótica del siglo XIV profundamente transformado en época barroca que presenta capillas laterales entre contrafuertes robustos, una portada meridional de arquivoltas apuntadas molduradas de cantería y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25134','monumento','Fábrica de Azúcar de Menàrguens','Antiguo complejo industrial modernista de principios del siglo XX que constituye un exponente de la arqueología industrial al conservar sus grandes naves de ladrillo visto, almacenes de techumbres aligeradas y una esbelta chimenea industrial troncocónica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25135','iglesia','Iglesia de San Miguel','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada que corona el perfil urbano de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27009','iglesia','Capilla de San Isidro','Pequeño edificio religioso barroco del siglo XVIII edificado con aparejo de mampostería regular enlucida que muestra una fachada de líneas neoclásicas con portalada moldurada de piedra local y una espadaña de dos vanos que remata el hastial occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27009','monumento','Casa Canal','Monumental sede de la administración del Canal de Urgell construida en el siglo XIX en un estilo ecléctico e industrial que destaca por sus fachadas simétricas de sillería combinadas con ladrillo visto y por albergar el centro de interpretación del agua de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25139','monumento','Núcleos de población de Montellà i Martinet','El término municipal incluye los siguientes núcleos de población: Montellà, Martinet y Villec.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25139','iglesia','Santuario de Santa María de Villec','Edificio religioso románico del siglo XII edificado en sillería de alta montaña que destaca por su ábside semicircular orientado a levante y por haber albergado en su interior una notable portalada meridional de múltiples arquivoltas en degradación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25139','monumento','Parque de los Búnkeres de Martorell (Línea P)','Complejo militar musealizado de la posguerra (década de 1940) que conserva una red de fortificaciones defensivas pasivas con nidos de ametralladoras de hormigón armado, galerías subterráneas y trincheras excavadas en la roca viva pirenaica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25138','monumento','Núcleos de población de Montgai','El término municipal incluye los siguientes núcleos de población: Butsènit.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25138','iglesia','Iglesia de la Asunción de Montgai','Monumental templo parroquial de traza barroca clasicista edificado en el siglo XVIII que presenta una fachada de sillería caliza vista con portada moldurada flanqueada por pilastras, una nave de gran amplitud y un esbelto campanario octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25138','iglesia','Iglesia de Santa María de Butsènit','Edificio religioso de origen medieval transformado en el barroco rural que presenta una planta de nave única, una portalada con dovelas de piedra arenisca y un campanario de torre de planta cuadrangular que corona el término.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25145','iglesia','Iglesia de San Jaime de Nalec','Templo parroquial levantado en el siglo XVIII bajo las directrices del barroco clasicista que muestra una fachada de sillería caliza con portalada moldurada entre pilastras, una amplia nave con capillas intercomunicadas y un esbelto campanario de torre octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25145','monumento','El Azud de Nalec (L''Assut)','Antigua e imponente infraestructura hidráulica de origen medieval construida en el cauce del río Corb mediante grandes bloques de sillería de piedra caliza regular escalonada para desviar las aguas hacia los molinos harineros de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','monumento','Núcleos de población de Naut Aran','El término municipal incluye los siguientes núcleos de población: Arties, Salardú, Gessa, Unha, Tredòs, Bagergue y Montgarri.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','iglesia','Iglesia de San Andrés de Salardú','Magna joya del románico tardío y gótico aranés de los siglos XII y XIII que destaca por su monumental planta basilical, su imponente torrecampanario octogonal provista de aspilleras de defensa y por custodiar el Santo Cristo de Salardú, una talla románica en madera policromada de valor universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','iglesia','Iglesia de Santa María de Arties','Excepcional templo románico del siglo XII que presenta una planta de tres naves rematadas por sendos ábsides semicirculares perfectos con decoración exterior lombarda de arquillos ciegos y lesenas, albergando en su interior un fastuoso ciclo de pinturas murales renacentistas al fresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','iglesia','Santuario de Nuestra Señora de Montgarri','Monumental complejo religioso y hospital de peregrinos fundado en el siglo XII a orillas del río Noguera Pallaresa que presenta una fábrica del siglo XVI adaptada a la alta montaña con muros de mampostería basta de pizarra y una esbelta torre-campanario con aguja piramidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','iglesia','Iglesia de Santa Eulalia de Unha','Templo románico del siglo XII edificado en sillería regular de granito que conserva fragmentos de pinturas murales medievales en su ábside central y muestra un singular campanario barroco del siglo XVIII rematado por una vistosa cubierta cupulada bulbosa única en el valle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90622','monumento','Casa de los Portolá (Arties)','Casa fuerte señorial y fortificada construida en el siglo XVI con bloques de cantería regular que exhibe una esbelta torre de defensa cilíndrica integrada, ventanas de dintel gótico conopial labradas y escudos heráldicos de la familia del descubridor de California. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25148','monumento','Núcleos de población de Odèn','El término municipal incluye los siguientes núcleos de población: Cambrils, Canalda y Llinars.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25148','monumento','Castillo de Cambrils','Fortaleza medieval del siglo XI emplazada estratégicamente sobre un risco rocoso del Solsonès que conserva gran parte de su recinto amurallado de sillería caliza regular, portales dovelados de arco de medio punto y restos de estancias de almacenamiento abovedadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25148','iglesia','Iglesia de San Julián de Canalda','Templo de origen románico modificado en época barroca que conserva de su fábrica del siglo XII una notable portada meridional con arquivoltas molduradas sobre columnas y un ábside semicircular de cantería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25148','monumento','Salinas de Cambrils','Complejo preindustrial e hidráulico de origen medieval restaurado para la obtención de sal de montaña que constituye un exponente de la arqueología industrial al conservar las eras de evaporación de madera, canalizaciones de piedra y balsas de decantación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25149','monumento','Núcleos de población de Oliana','El término municipal incluye los siguientes núcleos de población: Les Anoves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25149','iglesia','Iglesia de San Andrés del Castillo de Oliana','Monumental templo románico del siglo XI consagrado por el obispo San Ermengol que destaca por su impecable conservación de sillería caliza, su ábside semicircular decorado exteriormente con un friso de arcuaciones lombardas y una robusta torrecampanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25149','iglesia','Iglesia Parroquial de los Santos Justo y Pastor (Núcleo Urbano)','Edificio religioso de época barroca (siglo XVII) edificado con aparejo de mampostería regular que muestra una amplia nave longitudinal, una portada de líneas clásicas molduradas flanqueada por pilastras y un campanario cuadrangular que domina la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25150','monumento','Núcleos de población de Oliola','El término municipal incluye los siguientes núcleos de población: Coscó, Plandogau y Renant.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25150','iglesia','Iglesia de Santa María de Oliola','Templo de base románica del siglo XII que presenta una sola nave cubierta por bóveda de cañón apuntada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una espléndida portada meridional de tres arquivoltas en degradación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25150','iglesia','Iglesia de San Sadurní de Coscó','Pequeña capilla románica del siglo XII que consta de una sola nave con bóveda de cañón, un ábside semicircular orientado a levante sin ornamentación exterior y un campanario de espadaña de dos vanos ejecutado en sillarejo tosco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25151','monumento','Núcleos de población de Olius','El término municipal incluye los siguientes núcleos de población: Brics y El Pi de Sant Just.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25151','iglesia','Iglesia de San Esteban de Olius','Joya cumbre del románico lombardo catalán del siglo XI construida con sillería caliza perfecta que destaca por albergar una de las criptas subterráneas más espectaculares de la península, constituida por tres naves divididas por columnas monolíticas con capiteles toscos que sostienen bóvedas de arista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25151','monumento','Cementerio Modernista de Olius','Obra maestra del modernismo catalán proyectada por el arquitecto Bernardí Martorell en 1916 que destaca mundialmente por su diseño orgánico integrado de forma absoluta en un paisaje de rocas calcáreas caladas y encinas, donde las tumbas y los panteones se hallan excavados directamente en las cavidades naturales del terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25151','iglesia','Los 10 pueblos medievales de Lleida con más encanto 5 oct 2021 — La Iglesia de Santa María, por ejemplo','Los 10 pueblos medievales de Lleida con más encanto 5 oct 2021 — La Iglesia de Santa María, por ejemplo, es del siglo XI. La Iglesia de Sant Climent, por su parte, es del siglo XII, se la conoce ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25155','iglesia','Colegiata de Santa María de Organyà','Monumental templo románico del siglo X y reestructurado en el XII que destaca por su planta basilical de sillería caliza regular y por ser el centro histórico donde se descubrieron las Homilías de Organyà, uno de los documentos literarios más antiguos escritos en lengua catalana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25155','iglesia','Barrio Viejo y Plaza de la Iglesia','Núcleo medieval porticado que conserva de forma óptima su trazado urbano de callejuelas estrechas, arcadas de piedra basta de luces desiguales y masías de cantería de los siglos XV y XVI.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25156','monumento','Núcleos de población de Os de Balaguer','El término municipal incluye los siguientes núcleos de población: Alberola, Gerb y Tragó de Noguera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25156','monumento','Castillo de Os de Balaguer (Castell de Os)','Monumental e imponente fortaleza medieval documentada desde el siglo IX','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25156','monumento','Cueva de los Vilars (Balma dels Vilars)','Excepcional abrigo rupestre que conserva un soberbio ciclo de pinturas prehistóricas del arte levantino y esquemático, declaradas Patrimonio de la Humanidad por la UNESCO gracias a sus figuras antropomorfas y zoomorfas polícrómas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25156','iglesia','Monasterio de Santa María de Bellpuig de les Avellanes','Magna abadía medieval premonstratense emplazada en su término geográfico que destaca por su iglesia gótica de líneas austeras, un bellísimo claustro románico de sillería perfecta con capiteles historiados y el refectorio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25157','monumento','Núcleos de población de Ossó de Sió','El término municipal incluye los siguientes núcleos de población: Bellver de Sió, Castellnou d''Ossó y Montfalcó d''Agramunt.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25157','iglesia','Iglesia de San Pedro de Castellnou d''Ossó','Templo románico del siglo XII edificado en cantería regular que presenta una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado al este con decoración de estilo lombardo y una robusta torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25157','monumento','Torre de Castellnou d''Ossó','Antigua torre de vigía y defensa medieval de planta circular construida con aparejo regular de bloques de piedra caliza cementados con mortero de cal que domina estratégicamente el valle del río Sió.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25164','monumento','Núcleos de población de Penelles','El término municipal incluye los siguientes núcleos de población: Almassor y Boldú.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25164','iglesia','Iglesia de San Juan Bautista','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada monumental de sillería caliza vista con portada clasicista moldurada, un interior de tres naves de gran amplitud y un esbelto campanario octogonal con remate cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25164','iglesia','Iglesia Vieja de San Juan','Ruinas consolidadas de un pequeño santuario medieval de origen románico que conserva de su estructura primitiva muros de mampostería basta y la base del ábside semicircular liso integrado en el paisaje urbano de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25165','monumento','Núcleos de población de Peramola','El término municipal incluye los siguientes núcleos de población: Castell-llebre, Nuncarga y Tragó de Segre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25165','iglesia','Iglesia de la Virgen de Castell-llebre','Excepcional oratorio románico del siglo XI colgado de forma vertiginosa sobre un acantilado que domina el cauce del río Segre, caracterizado por su pureza geométrica de nave única, su ábside semicircular orientado al este y una robusta torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25165','monumento','Roca de los Moros de Peramola','Destacado abrigo de arte rupestre prehistórico que conserva trazos esquemáticos e inscripciones de gran valor arqueológico, protegido dentro de la declaración de la UNESCO para el arte rupestre del arco mediterráneo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25166','monumento','Núcleos de población de Pinell de Solsonès','El término municipal incluye los siguientes núcleos de población: Madrona, Sallent de Solsonès y Sant Climenç.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25166','monumento','Castillo y San Pedro de Madrona','Ruinas de una monumental e histórica fortaleza medieval del siglo XI emplazada sobre un espectacular risco rocoso del Solsonès de las que subsisten lienzos de la muralla perimetral de sillería y la gran iglesia románica con ábside.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25166','iglesia','Iglesia de San Climaco de Sant Climenç','Edificio religioso románico del siglo XII edificado en cantería regular que presenta una sola nave con bóveda de cañón, un ábside semicircular orientado al este con cornisa de canecillos lisos y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25167','monumento','Núcleos de población de Pinós','El término municipal incluye los siguientes núcleos de población: Ardèvol, Matamargó, Sant Just d''Ardèvol y Vallmanya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25167','iglesia','Santuario de Nuestra Señora de Pinós','Monumental complejo religioso del siglo XIV emplazado en el centro geográfico exacto de Catalunya que destaca por su iglesia gótica de líneas austeras, muros de piedra caliza adaptados a la montaña, una hospedería anexa y una cruz monumental de piedra tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25167','monumento','Torre de Ardèvol','Imponente torre de vigía medieval de planta cuadrangular y sillería perfecta del siglo XI que constituye el único vestigio en pie del desaparecido castillo del núcleo, conservando saeteras defensivas a diferentes alturas y un acceso elevado original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25168','iglesia','Iglesia de San Juan Bautista','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de paramentos enlucidos con portal de cantería moldurada flanqueada por pilastras, un interior de nave única y una recia torrecampanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25168','monumento','Cal Formiguera','Casa solariega de origen dieciochesco construida en mampostería regular enlucida que destaca por su simetría de vanos adintelados, balconadas de forja tradicional y un gran dintel pétreo con inscripciones heráldicas en su acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25169','iglesia','Iglesia de la Virgen de la Llosa','Templo parroquial levantado en el siglo XVIII bajo las directrices del estilo barroco clasicista que muestra una fachada de sillería caliza con portalada moldurada entre pilastras, una amplia nave con capillas intercomunicadas y un esbelto campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25169','iglesia','Ruinas del Convento de Santa María de las Garrigues','Vestigios consolidados de un antiguo oratorio altomedieval del que subsisten los cimientos y arranques de muros de mampostería basta, integrados en un entorno de bancales de piedra tradicional destinados al cultivo de olivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25171','monumento','Núcleos de población de La Pobla de Segur','El término municipal incluye los siguientes núcleos de población: Sant Joan de Vinyafrescal y Puimanyons.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25171','monumento','Torre Mauri y Conjunto Modernista','Suntuoso complejo residencial municipal proyectado a principios del siglo XX por el arquitecto Joaquim Codina que destaca por su Palacio Consistorial de estética neorrománica, sus fachadas con profusa azulejería de mosaico cerámico polícromo, vitrales florales y una esbelta torre de vigía cilíndrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25171','ermita','Ermita de San Miguel del Pui','Excepcional templo románico del siglo XII aislado en un promontorio que destaca por la pureza geométrica de su nave única, su ábside semicircular orientado al este con cornisa de canecillos lisos y muros ejecutados en sillería de piedra arenisca regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25171','iglesia','Iglesia de San Cristóbal de Puimanyons','Pequeño santuario románico del siglo XI edificado en sillería regular caliza que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante con decoración exterior de estilo lombardo de dobles arquillos ciegos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25030','monumento','Núcleos de población de El Pont de Bar','El término municipal incluye los siguientes núcleos de población: Aristot, Toloriu y Bar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25030','monumento','Castillo y Núcleo Medieval de Aristot','Ruinas de una estratégica fortaleza defensiva militar del siglo XI de las que subsisten potentes lienzos de muralla de mampostería basta y saeteras originales que se adaptan a la orografía del cerro que domina el cauce alto del río Segre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25030','iglesia','Iglesia de San Andrés de Aristot','Templo románico de alta montaña edificado en el siglo XII que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado al este con decoración exterior lombarda y una robusta torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25030','monumento','Castillo de Toloriu','Ruinas de una antigua casa fuerte señorial de origen medieval asociada a las leyendas del tesoro de Moctezuma de las que perviven los cimientos de la torre del homenaje y tramos dispersos de la muralla perimetral de mampostería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25173','iglesia','Iglesia Nueva de la Asunción','Magna obra de la arquitectura contemporánea racionalista proyectada en 1955 por el ingeniero Eduardo Torroja Miret que destaca mundialmente por su audaz estructura abovedada lobulada ejecutada en hormigón armado aligerado, paramentos acristalados que optimizan la iluminación cenital y campanario exento de líneas puras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25173','iglesia','Iglesia de San Román de Casós','Pequeño templo románico de finales del siglo XII edificado en sillería de alta montaña que presenta una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado a levante con cornisa de canecillos lisos y una portada meridional de múltiples arquivoltas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25173','iglesia','Iglesia de Santa María de Viu de Llevata','Excepcional templo románico del siglo XII edificado en cantería de pizarra rústica regular que consta de una sola nave con bóveda de cañón, un ábside semicircular perfecto decorado exteriormente con un friso de dientes de sierra y una majestuosa portada meridional esculpida con relieves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25173','monumento','Colección de Arte Sacro de la Alta Ribagorça','Museo ubicado en el casco antiguo de la villa que custodia un valioso catálogo de tallas religiosas románicas y góticas de madera policromada, cruces procesionales de plata repujada e instrumental litúrgico rescatado de los templos aislados de los valles. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25173','monumento','Lérida Consultado el 1 de enero de 2016. ↑ «Miquel Pueyo ha estat investit alcalde d''ERC a Lleida','Lérida Consultado el 1 de enero de 2016. ↑ «Miquel Pueyo ha estat investit alcalde d''ERC a Lleida ( Lleida (Lérida ) i posa fi a 40 anys ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25172','monumento','Núcleos de población de Ponts','El término municipal incluye los siguientes núcleos de población: Torreblanca, El Tossal, Gualter y Rialb.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25172','iglesia','Colegiata de San Pedro de Ponts','Monumental templo románico del siglo XI de grandes dimensiones que destaca','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25172','iglesia','Iglesia de Santa María de Gualter','Ruinas consolidadas de un antiguo cenobio benedictino del siglo XII del que subsisten los potentes muros de la nave mayor, arcos fajones apuntados y tramos de un claustro de sillería caliza que se integran en el paisaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90623','monumento','Núcleos de población de Prats i Sansor','El término municipal incluye los siguientes núcleos de población: Prats y Sansor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90623','iglesia','Iglesia de San Salvador de Predanies','Joya del románico temprano del siglo XI edificada con aparejo tosco de piedra caliza que presenta una sola nave, un ábside semicircular orientado a levante y un campanario de espadaña de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25176','iglesia','Iglesia de Santa María de Preixana','Templo de estilo gótico tardío del siglo XV profundamente reformado que destaca por su imponente fachada de sillería vista, sus robustos contrafuertes exteriores y una torre-campanario cuadrangular rematada por gárgolas esculpidas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25177','monumento','Núcleos de población de Preixens','El término municipal incluye los siguientes núcleos de población: Pradell y Ventoses.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25177','monumento','Castillo de Preixens','Palacio fortificado del siglo XVI de estilo renacentista levantado sobre una antigua fortaleza medieval','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25183','monumento','Núcleos de población de Rialp','El término municipal incluye los siguientes núcleos de población: Roní, Beraní y Caregue.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25183','monumento','Castillo de Rialp','Ruinas de una estratégica fortaleza medieval del siglo XI emplazada sobre una cresta rocosa de las que subsisten potentes lienzos de la muralla de sillería de pizarra rústica y los cimientos de la gran torre del homenaje cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25183','iglesia','Iglesia de la Virgen de la Montaña de Caregue','Templo mariano situado en un prado de alta montaña del Pirineo que presenta una arquitectura barroca de carácter popular con muros de mampostería basta adaptados a la climatología y una espadaña de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25185','monumento','Núcleos de población de Ribera d''Urgellet','El término municipal incluye los siguientes núcleos de población: El Pla de Sant Tirs, Adrall, Arfa y Castellanou de Tost.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25185','iglesia','Iglesia de San Saturnino de Arfa','Edificio religioso de origen medieval transformado en el barroco rural que presenta una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25186','monumento','Núcleos de población de Riner','El término municipal incluye los siguientes núcleos de población: El Miracle, Su y Freixinet.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25186','iglesia','Santuario del Miracle (El Miracle)','Monumental conjunto barroco del siglo XVIII que destaca por albergar en su iglesia un fastuoso retablo mayor de madera tallada y dorada, obra cumbre del barroco catalán esculpida por Carles Morató, flanqueado por un gran monasterio benedictino y una gran hospedería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25189','iglesia','Iglesia de San Pedro','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25190','monumento','Núcleos de población de Salàs de Pallars','El término municipal incluye los siguientes núcleos de población: Sensui.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25190','monumento','Conjunto Histórico de la Villa Cerrada de Salàs','Núcleo urbano medieval fortificado que conserva de forma impecable su recinto amurallado con torreones de planta cuadrangular, portales de acceso monumentales de arco apuntado dovelado, calles porticadas y plazas donde se celebraba la histórica feria de ganado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25192','monumento','Núcleos de población de Sant Guim de Freixenet','El término municipal incluye los siguientes núcleos de población: Amorós, Freixenet y Altadill.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25192','monumento','Sindicato Agrícola de Sant Guim de Freixenet','Joya de la arquitectura agraria modernista proyectada por el arquitecto Cèsar Martinell en 1920 que destaca por su fachada de ladrillo visto combinada con mampostería, sus arcos parabólicos interiores que optimizan el espacio diáfano y sus grandes naves industriales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25193','iglesia','Iglesia del Monasterio de San Lorenzo','Magna iglesia románica del siglo XI de planta basilical de tres naves que destaca por albergar en su interior la Capilla de la Virgen de los Colls, una de las muestras más exuberantes del barroco catalán gracias a su profuso retablo de madera tallada y dorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25193','monumento','Recinto Amurallado de la Villa','Vestigios del sistema defensivo medieval del siglo XIV del que subsisten tramos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25191','monumento','Castillo de Sanaüja','Ruinas de una estratégica fortaleza medieval documentada desde el siglo XI de la que subsiste una imponente pared calada de sillería regular que formaba parte del palacio episcopal fortificado tardomedieval, rematada por un curioso campanario de espadaña posterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25191','monumento','Puente de Sanaüja (Pont Vell)','Infraestructura civil de origen gótico construida en el siglo XIV sobre el río Riera de Sanaüja mediante dos arcadas de medio punto ejecutadas en cantería de piedra caliza con tajamares apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25201','iglesia','Iglesia de Santa María de Sarroca','Templo parroquial de origen gótico profundamente transformado en el periodo barroco que destaca por conservar de su fábrica primitiva una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25204','iglesia','Monasterio de Nuestra Señora de los Ángeles de Avinganya','Antiguo cenobio trinitario fundado en el siglo XIII que destaca por conservar los restos de una monumental iglesia gótica de nave única con bóvedas de crucería calada, las estructuras de su claustro gótico de sillería y dependencias arqueológicas musealizadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90624','iglesia','Iglesia de San Bartolomé','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25207','catedral','Catedral de Santa María de Solsona','Magna basílica que fusiona de forma única la arquitectura románica de sus tres ábsides originales del siglo XII con una imponente nave gótica del XIV, célebre por albergar en su interior la venerada imagen de la Virgen del Claustro, una joya cumbre de la escultura románica universal tallada en piedra por el maestro Gilabertus.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25207','palacio','Palacio Episcopal y Museo Diocesano','Palacio civil barroco construido en el siglo XVIII por el arquitecto Francesc Pons que presenta una monumental fachada neoclásica de sillería caliza vista y alberga una de las colecciones de arte sacro medieval (románico y gótico) más importantes de Catalunya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25207','monumento','Plaza Mayor (Plaça Major)','Histórico espacio público porticado de traza gótica configurado por edificios de fachadas clasicistas y barrocas con grandes viguerías de madera tallada que sostienen los voladizos señoriales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25208','monumento','Núcleos de población de Soriguera','El término municipal incluye los siguientes núcleos de población: Vilamur, Llagunes, Embonui y Malmercat.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25208','monumento','Yacimiento Arqueológico del Despoblado de Santa Cruz (Santa Creu de Llagunes)','Asentamiento medieval de alta montaña musealizado que conserva las plantas de piedra de sus viviendas fortificadas, calles pavimentadas y tramos de muros de mampostería seca que atestiguan el hábitat ganadero pirenaico del siglo XII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25209','monumento','Castillo de los Condes de Pallars','Ruinas consolidadas de una monumental fortaleza medieval del siglo XI de la que subsiste una imponente pared de sillería caliza regular provista de ventanales de traza gótica y saeteras defensivas que ejercía funciones de palacio residencial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25209','iglesia','Iglesia de San Pedro de Llessui','Edificio religioso románico del siglo XII edificado en sillería de pizarra de alta montaña que destaca por su esbelto campanario de torre exento de planta cuadrada con ventanas geminadas de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25210','iglesia','Iglesia de San Lorenzo de Soses','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada monumental de sillería caliza vista con portada clasicista moldurada, un interior de tres naves de gran amplitud y un esbelto campanario octogonal con remate cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25211','iglesia','Iglesia de San Pedro','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25212','iglesia','Iglesia de la Natividad de la Virgen (o de San Salvador)','Templo románico de transición edificado en el siglo XIII en cantería perfecta que destaca por su ábside semicircular liso,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27013','iglesia','Iglesia de Santa María de la Alba','Monumental basílica reedificada en el siglo XVII en estilo barroco clasicista según los planos de los arquitectos de la saga Morató, caracterizada por su imponente fachada de sillería vista con portada monumental flanqueada por pilastras, su amplio interior de tres naves con frescos y un robusto campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27013','palacio','Palacio de los Marqueses de la Floresta','Edificio residencial del gótico civil catalán del siglo XIV que presenta una fachada monumental de sillería vista provista de ventanas coronelas geminadas de arcos apuntados calados de gran virtuosismo geométrico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25219','iglesia','Iglesia de San Salvador de Tarroja','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de sillería caliza vista con portada clasicista moldurada, un interior de tres naves de gran amplitud y un esbelto campanario octogonal con remate cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25221','iglesia','Iglesia de la Virgen de la Piedad','Templo de base medieval profundamente transformado tras su destrucción en las guerras carlistas y civiles que presenta muros de mampostería basta de alta montaña, una fachada con portalada neoclásica moldurada de cantería local y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25223','monumento','Núcleos de población de Torà','El término municipal incluye los siguientes núcleos de población: Llanera, Cellers y Claret.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25223','monumento','Torre de Vallferosa','Impresionante e imponente torre de defensa románica del siglo X que constituye una de las obras cumbres de la arquitectura militar altomedieval europea al alzarse de forma exenta hasta treinta metros de altura con muros de sillería perfecta de piedra caliza y una estructura de talud defensivo única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25223','iglesia','Iglesia de San Pedro de Llanera','Monumental iglesia de estilo gótico tardío del siglo XVI profundamente vinculada a las ruinas del antiguo castillo de Llanera de la que se conservan los muros de sillería de su nave mayor y capillas laterales cubiertas con bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25226','iglesia','Iglesia de San Salvador de Torrebesses','Monumental templo románico de transición edificado en el siglo XII que destaca por su ábside de sillería caliza regular y una portada meridional de múltiples arquivoltas en degradación esculpidas por la escuela de Lleida, además de un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25226','monumento','Construcción de Piedra Seca del Centro de Interpretación','Conjunto de cabañas tradicionales de pastor exentas construidas mediante la técnica de la mampostería seca y falsas cúpulas por aproximación de hiladas de losas de piedra que constituyen un hito etnográfico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25228','monumento','Núcleos de población de Torrefarrera','El término municipal incluye los siguientes núcleos de población: Malpartit.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25228','iglesia','Iglesia de la Santa Cruz','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90625','monumento','Núcleos de población de Torrefeta i Florejacs','El término municipal incluye los siguientes núcleos de población: Torrefeta, Florejacs, Palou, Sedó y Les Cases de la Serra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90625','monumento','Castillo de Florejacs','Monumental e imponente fortaleza medieval documentada desde el siglo XI y transformada en palacio residencial en las centurias góticas y renacentistas que destaca por su recinto amurallado de sillería, su esbelta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90625','monumento','Castillo de las Pallargues','Palacio fortificado gótico construido en el siglo XIV que presenta una monumental fachada de sillería caliza calada por un colosal arco de descarga ojival único en su tipología, un patio de armas interior con majestuosas escalinatas y salones nobles abovedados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25230','iglesia','Iglesia de la Asunción de Torregrossa','Templo parroquial de traza barroca del siglo XVIII que presenta una fachada enlucida con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular ejecutada en piedra caliza local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25231','iglesia','Iglesia de la Asunción','Edificio religioso de época barroca (siglo XVII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una portada clasicista de cantería moldurada y una esbelta torrecampanario que domina el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25232','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo de factura barroca del siglo XVIII de gran envergadura que destaca por su fachada monumental de sillería vista con una portalada clasicista flanqueada por columnas y hornacinas, un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25234','iglesia','Basílica de Santa María de Valldeflors','Monumental templo gótico del siglo XIV edificado sobre una base románica anterior que presenta una imponente nave única de gran anchura, capillas laterales entre contrafuertes robustos, una portada con arquivoltas apuntadas molduradas y un extraordinario interior litúrgico barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25234','monumento','Recinto Amurallado y Torres de Tremp','Vestigios del sistema defensivo medieval del siglo XIV del que subsisten tres imponente torreones de planta circular (como la Torre de las Monjas) ejecutados con aparejo regular de sillería basta y cortinas defensivas integradas en el núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25234','iglesia','Iglesia de Santa María de Vilamitjana','Edificio religioso románico del siglo XII profundamente modificado en época barroca que destaca por albergar una notable cabecera de sillería caliza regular y una portada meridional de cantería moldurada flanqueada por una recia torre-campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','monumento','Núcleos de población de La Vall de Boí','El término municipal incluye los siguientes núcleos de población: Erill la Vall, Boí, Taüll, Barruera, Durro, Cardet y Cóll.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','iglesia','Iglesia de San Clemente de Taüll (Sant Climent de Taüll)','Magna obra maestra de la historia del arte universal declarada Patrimonio de la Humanidad por la UNESCO que destaca por su pureza arquitectónica románica lombarda del siglo XII, su esbelto y célebre campanario de torre exento de seis pisos con ventanas geminadas caladas y por albergar el ábside donde se pintó el Pantocrátor al fresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','iglesia','Iglesia de Santa María de Taüll','Templo románico de planta basilical de tres naves consagrado en el año 1123 que presenta una estructura de sillería regular caliza con decoración de arquillos ciegos y lesenas de estilo lombardo, decorado interiormente con una réplica exacta del ciclo de pinturas murales medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','iglesia','Iglesia de Santa Eulalia de Erill la Vall','Monumento románico lombardo del siglo XII célebre por su esbelto y monumental campanario de torre exento de planta cuadrada que se alinea estratégicamente con los del valle y por haber albergado el grupo escultórico del Descendimiento en madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','iglesia','Iglesia de San Juan de Boí','Edificio de base prerrománica y románica del siglo XI que presenta una planta de tres naves separadas por pilares cuadrangulares con cubiertas de madera a dos aguas, muros de sillería basta y un campanario de torre profundamente transformado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','iglesia','Iglesia de la Natividad de Durro','Monumental templo románico del siglo XII edificado con aparejo de sillería caliza regular de grandes dimensiones que cuenta con una amplia nave única con capillas laterales, una monumental portada meridional bajo porche y un campanario de gran envergadura. [1, 2]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25901','monumento','Núcleos de población de Vall de Cardós','El término municipal incluye los siguientes núcleos de población: Ribera de Cardós, Ainet de Cardós, Cassibrós y Estaon.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25901','iglesia','Iglesia de Santa María de Ribera de Cardós','Monumental templo de origen románico profundamente transformado en el barroco rural que conserva de su fábrica primitiva una notable portada meridional de arquivoltas molduradas sobre columnas y destaca por su recia torre-campanario que domina la cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25901','iglesia','Iglesia de San Jaime de Estaon','Pequeño santuario románico del siglo XII edificado en sillería de alta montaña que destaca por haber albergado en su interior un valioso ciclo de pinturas murales al fresco del románico pirenaico que hoy se custodian en el Museo Nacional de Arte de Catalunya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25240','monumento','Núcleos de población de Vallfogona de Balaguer','El término municipal incluye los siguientes núcleos de población: l''Alcoletge de Balaguer y la Ràpita.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25240','iglesia','Iglesia de la Sagrada Familia','Templo parroquial de factura contemporánea levantado en el siglo XX de líneas funcionales que incorpora un campanario de hormigón aligerado y una portada enlucida integrada en el entorno urbano de la vega del río Segre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25242','monumento','Castillo de Verdú','Monumental e imponente fortaleza medieval documentada desde el siglo XI que constituye la gran seña de identidad de la villa al conservar una espectacular torre del homenaje cilíndrica de veinticinco','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25242','iglesia','Iglesia de Santa María de Verdú','Magna iglesia de traza gótica construida en el siglo XIV que presenta una imponente nave única de gran anchura, capillas laterales entre contrafuertes robustos, una portada con arquivoltas apuntadas molduradas de cantería y un soberbio rosetón de tracería calada geométrico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27014','iglesia','Iglesia de San Miguel de Vielha','Monumental templo de transición románico-gótico edificado en el siglo XII en sillería regular que destaca por su fastuosa portada occidental de múltiples arquivoltas en degradación esculpidas con figuras, un imponente campanario de torre cuadrangular fortificado y por custodiar el Cristo de Mijaran, una obra cumbre de la talla medieval en madera policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27014','iglesia','Iglesia de San Esteban de Betren','Joya de la arquitectura gótica aranesa del siglo XIV que presenta una planta de nave única con ábside poligonal decorado con tracerías caladas de gran virtuosismo, una portada meridional moldurada y un campanario de espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27014','iglesia','Iglesia de San Pedro de Escunhau','Edificio religioso románico del siglo XII edificado en cantería perfecta de granito que destaca por albergar una bellísima portada meridional de tres arquivoltas en degradación soportadas por columnas con capiteles esculpidos con figuras humanas y de animales fantásticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27014','monumento','Fábrica de Lana de Vielha (Era Fabrica de Lana)','Antiguo complejo industrial textil decimonónico que constituye un exponente de la arqueología industrial pirenaica al conservar','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25245','monumento','Núcleos de población de Vilaller','El término municipal incluye los siguientes núcleos de población: Senet.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25245','monumento','Recinto Amurallado de la Villa de Vilaller','Vestigios del sistema defensivo medieval del siglo XIV del que subsisten tramos notables de cortina de mampostería basta integrados en las viviendas del núcleo histórico y portales de acceso monumentales de arco apuntado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25245','iglesia','Iglesia de San Clemente de Senet','Pequeño templo románico de alta montaña edificado en el siglo XII en sillería regular que consta de una sola nave con bóveda de cañón apuntada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una espadaña de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25247','iglesia','Iglesia de Santa María de Vilamòs','Templo de factura románica aranesa edificado en el siglo XII en piedra pizarra regular que destaca por albergar empotrados en sus muros exteriores de mampostería tres estelas funerarias romanas de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25249','monumento','Núcleos de población de Vilanova de l''Aguda','El término municipal incluye los siguientes núcleos de población: Ribelles y Valldàries.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25249','iglesia','Castillo e Iglesia de San Salvador de Ribelles','Conjunto fortificado medieval del siglo XI emplazado de forma escarpada en la cumbre del cerro que conserva lienzos de muralla, los cimientos de la gran torre del homenaje de planta circular de mampostería basta y la capilla románica de sillería caliza regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25250','monumento','Núcleos de población de Vilanova de Meià','El término municipal incluye los siguientes núcleos de población: Santa Maria de Meià, Lluçars y Boada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25250','iglesia','Iglesia de San Salvador de Vilanova de Meià','Joya del gótico temprano edificado en el siglo XIII en cantería perfecta que destaca por su fastuosa portada meridional de seis arquivoltas en degradación profusamente esculpidas por la escuela de Lleida con motivos florales y geométricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25251','iglesia','Iglesia de San Sebastián','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25252','iglesia','Capilla de la Virgen de la Cabeza','Pequeño edificio religioso barroco del siglo XVIII edificado con aparejo de mampostería regular enlucida que muestra una fachada de líneas neoclásicas con portalada moldurada de piedra local y una espadaña de un vano que remata el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25255','iglesia','Iglesia de San Juan Bautista de Vinaixa','Monumental templo románico de transición edificado en el siglo XII que destaca por su ábside de sillería caliza regular y una portada meridional de múltiples arquivoltas en degradación esculpidas por la escuela de Lleida con motivos geométricos, protegida por un robusto porche.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25255','monumento','GC71V9Q 03-PE- Provincias españolas','LLEIDA (Traditional Cache) in Comunitat Valenciana, Spain created by kuskuteam 3 sept 2017 — 3. - SAN CLEMENTE DE TAULL San Clemente de Taüll pertenece al conjunto de iglesias románicas de La Vall de Boí, declarado Patrimon...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90626','iglesia','Iglesia de Nuestra Señora de la Concepción','Templo de factura decimonónica que destaca por su fachada ecléctica de cantería roja y gris local con un gran frontón clásico, dos esbeltos campanarios y una imponente cúpula que domina el casco histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90626','monumento','Yacimiento Arqueológico del Maipés de Agaete','Monumental necrópolis prehispánica de los antiguos canarios que conserva centenares de túmulos funerarios de piedra volcánica construidos sobre una colosal colada de lava, catalogada como uno de los centros arqueológicos exentos más relevantes del archipiélago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90626','ermita','Ermita de Nuestra Señora de las Nieves','Pequeño oratorio mudéjar edificado en el siglo XVI junto al puerto que destaca por albergar en su interior el Tríptico de las Nieves, una obra cumbre de la pintura flamenca atribuida al maestro Joos van Cleve.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90627','iglesia','Templo Parroquial de San Sebastián','Monumental edificio de estilo neoclásico catalogado como Monumento HistóricoArtístico Nacional que presenta una fastuosa fachada de cantería gris de las canteras locales con pilastras corintias y tres imponentes naves de gran altura bajo una cúpula linterna de influencia renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90627','monumento','Yacimiento Arqueológico de Guayadeque','Espectacular desfiladero kárstico que alberga uno de los conjuntos de asentamientos trogloditas prehispánicos más densos de las islas, constituido por cuevas naturales y artificiales destinadas a viviendas, silos colectivos y enterramientos de los antiguos canarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25001','iglesia','Iglesia de Nuestra Señora de la Antigua','Templo de arquitectura tradicional canaria levantado en el siglo XVIII que exhibe muros encalados combinados con cantería basta en los ángulos, un sencillo portal adintelado mudéjar y un campanario de torre de planta cuadrangular de gran pureza formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25001','monumento','Molino de Antigua (Centro de Interpretación)','Complejo etnográfico preindustrial restaurado que constituye un testimonio del aprovechamiento del viento en la isla al conservar la estructura de madera, las muelas de piedra y el velamen original destinados al molido de gofio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90628','monumento','Castillo de San Gabriel','Fortaleza militar costera construida en el siglo XVI para la defensa de la isla frente a los corsarios berberiscos que destaca por sus recios muros de sillería de basalto negro y por estar unida a la costa mediante el monumental Puente de las Bolas con sus característicos remates pétreos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90628','monumento','Castillo de San José','Fortaleza borbónica del siglo XVIII levantada sobre un promontorio estratégico que presenta una planta semicircular de cantería regular, reconvertida por el artista César Manrique en el Museo Internacional de Arte Contemporáneo respetando la fisonomía militar original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90628','iglesia','Iglesia de San Ginés','Templo parroquial de traza mudéjar profundamente reformado en el siglo XIX que destaca por su esbelto campanario exento de sillería vista que domina el frente marítimo del charco, sus artesonados de madera y su cubierta a tres aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25002','monumento','Complejo Arqueológico de Acusa','Monumental asentamiento troglodita prehispánico emplazado en una meseta fortificada que conserva impresionantes cuevas fortificadas artificiales destinadas a graneros colectivos, estancias residenciales con pinturas rupestres geométricas en sus paredes y necrópolis de cista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25002','ermita','Ermita de la Virgen de la Cuevita','Singular santuario excavado íntegramente en la roca viva de una ladera montañosa que constituye un ejemplo único de arquitectura troglodítica sacra canaria, albergando un altar, un confesionario y un coro tallados en la propia piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25003','catedral','Iglesia de San Juan Bautista (Catedral de Arucas)','Monumental templo neogótico proyectado a principios del siglo XX por el arquitecto Manuel Vega March que destaca mundialmente por estar tallado íntegramente en sillería de piedra azul de Arucas por los maestros canteros locales, exhibiendo fachadas con pináculos calados, un colosal rosetón y tres esbeltas agujas piramidales de gran envergadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25003','monumento','Heredad de Aguas de Arucas y Firgas','Palacio de estética ecléctica construido en el siglo XIX que presenta una simétrica fachada de cantería azul vista de gran vistosidad decorativa flanqueada por pilastras molduradas y un remate superior con reloj público barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25003','monumento','Fábrica de Ron Arehucas','Complejo industrial decimonónico que constituye un exponente de la arqueología industrial azucarera y licorera al conservar sus naves de piedra regular,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25005','monumento','Museo y Parque Arqueológico Cueva Pintada','Monumental y musealizado yacimiento prehispánico que constituye la capital espiritual de los antiguos canarios, célebre por albergar una gran cueva excavada en la toba volcánica decorada con excepcionales pinturas rupestres polícrómas geométricas en rojo, negro y blanco asociadas a un gran poblado prehispánico de casas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25005','iglesia','Templo Matriz de Santiago de los Caballeros','Monumental iglesia neoclásica construida entre los siglos XVIII y XIX que destaca por su imponente fachada de cantería gris flanqueada por dos robustas torres-campanario de planta cuadrangular, tres amplias naves cupuladas y un rico tesoro de orfebrería gótica y barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25005','monumento','Yacimiento de la Guancha','Complejo funerario y habitacional prehispánico situado en el litoral que conserva un espectacular túmulo circular exento edificado con grandes bloques de piedra volcánica superpuestos y plantas de viviendas de la antigua población aborigen.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90629','monumento','Jameos del Agua y Cueva de los Verdes','Espectacular tramo de un tubo volcánico prehistórico intervenido de forma genial por el artista César Manrique para fusionar la geología lávica con la arquitectura orgánica contemporánea, creando un colosal auditorio natural bajo bóvedas de basalto negro, piscinas integradas y jardines de vegetación tropical.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90629','monumento','Casa-Museo de César Manrique','Residencia tradicional de arquitectura canaria restaurada por el propio artista en medio de un palmeral tradicional que muestra muros encalados, estancias excavadas en burbujas volcánicas naturales y salones nobles donde se exponen sus herramientas y obras de arte universales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35011','monumento','Heredad de Acequias de Ingenio','Edificio civil de líneas clasicistas construido a finales del siglo XIX que presenta una fachada encalada con portadas de cantería gris labrada flanqueada por pilastras y un reloj público barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35011','monumento','Casa del Reloj','Antigua estructura hidráulica y administrativa comunal que conserva sus muros de mampostería regular y las canalizaciones de piedra basta destinadas al reparto tradicional de las aguas en la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35011','monumento','Mapas de la editorial IGN 1.104 Telde Compartir en','Esta hoja incluye los términos municipales de: Las Palmas ( provincia de Las Palmas de Gran Canaria ) Is...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35011','monumento','Mapas de la editorial IGN Esta hoja incluye los términos municipales de','Las Palmas ( provincia de Las Palmas de Gran Canaria ) , La Oliva, Yaiza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35012','iglesia','Iglesia de San Antonio de Padua','Templo parroquial inaugurado a principios del siglo XIX que presenta una arquitectura tradicional de muros encalados con cantería marrón en los ángulos, un portal adintelado mudéjar y un bello artesonado interior de madera de pino tea labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35012','monumento','Yacimiento Arqueológico de Las Crucecitas','Asentamiento prehispánico de los antiguos canarios situado en las laderas del valle que conserva estructuras habitacionales de planta cruciforme y muros de piedra seca superpuesta que atestiguan el hábitat aborigen.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35013','iglesia','Iglesia de Nuestra Señora de la Candelaria','Monumental e imponente edificio de estilo neoclásico edificado a mediados del siglo XX que se alza de forma espectacular sobre el borde del barranco de Moya, caracterizado por sus dos esbeltas torres-campanario de cantería azul y un gran rosetón central.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35013','monumento','Casa-Museo Tomás Morales','Residencia natal del célebre poeta modernista que constituye una muestra óptima de la arquitectura doméstica canaria del siglo XIX con sus balconadas interiores de madera noble, muros de cantería vista y salones decorados con mobiliario de época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35014','monumento','Casa de los Coroneles','Monumental palacio señorial del siglo XVIII que constituye el edificio de arquitectura civil más señero e importante de Fuerteventura, caracterizado por su colosal fachada encalada provista de largas balconadas de madera de pino tea rústica y sus dos recias torres almenadas angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35014','iglesia','Iglesia de Nuestra Señora de la Candelaria','Templo parroquial de traza mudéjar que destaca por su robusta torrecampanario exenta de sillería de piedra volcánica oscura de gran vistosidad volumétrica, sus cubiertas de madera artesonada y un valioso retablo barroco pictórico de Juan de Miranda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35015','iglesia','Iglesia de Nuestra Señora de la Regla','Joya de la arquitectura sacra majorera del siglo XVII que destaca internacionalmente por su fastuosa portada de cantería de influencia azteca o plateresca, profusamente esculpida con motivos de serpientes místicas, jaguares, soles y plumas exóticas que combinan la iconografía americana con el barroco rural canario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35015','ermita','Ermita de la Virgen de la Peña (Vega de Río Palmas)','Pequeño santuario mariano situado en un valle desértico que presenta una fisonomía mudéjar de gran sencillez con un dintel de cantería gris y que custodia la venerada imagen tallada en alabastro del siglo XV traída por los conquistadores normandos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','catedral','Catedral de Santa Ana','Magna y monumental catedral iniciada a finales del siglo XV que fusiona de forma única su interior de naves góticas de sillería con esbeltas columnas que imitan palmeras con una imponente y colosal fachada neoclásica exenta construida en piedra gris con dos robustas torres-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','monumento','Casa de Colón','Espectacular palacio señorial del gótico civil y del Renacimiento que sirvió como residencia de los antiguos gobernadores de la isla, caracterizado por sus portadas monumentales de sillería calada, hermosos patios de armas de madera noble con fuentes y salas abovedadas mudéjares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','monumento','Castillo de la Luz','Fortaleza militar costera de planta cuadrangular levantada en el siglo XV tras la conquista','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','monumento','Casco Histórico de Vegueta y Triana','Núcleo urbano tradicional que destaca por la conservación impecable de sus calles adoquinadas jalonadas de palacetes de los siglos XVI al XIX, caracterizados por sus portadas heráldicas de sillería y tradicionales balconadas de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35017','iglesia','Iglesia de Nuestra Señora del Rosario','Templo parroquial de traza neoclásica edificado en el siglo XIX que presenta una fachada monumental de líneas severas con portal de cantería moldurada flanqueada por pilastras, un interior de nave única cubierto con bóvedas de lunetos y una esbelta torrecampanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35017','monumento','Casa-Museo de Unamuno','Antigua vivienda decimonónica y fonda donde residió exiliado el célebre filósofo Miguel de Unamuno en 1924, restaurada rigurosamente para conservar el mobiliario de madera, la mesa de trabajo tradicional y la atmósfera intelectual de la época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35018','monumento','Casa Mayor Guerra','Palacio rural de arquitectura tradicional canaria edificado en el siglo XVIII que destaca por su simétrica fachada encalada con portada de sillería basáltica gris, un gran patio de armas interior porticado de madera noble y dependencias destinadas al cultivo vitivinícola de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35018','monumento','Monumento al Campesino (Casa-Museo del Campesino)','Complejo arquitectónico y paisajístico diseñado por César Manrique para rendir tributo al esfuerzo agrícola insular, el cual combina edificaciones tradicionales de muros encalados con una colosal escultura de vanguardia de quince metros erigida sobre rocas volcánicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35019','iglesia','Iglesia de San Bartolomé de Tunte','Templo parroquial de traza barroca y ecléctica edificado a finales del siglo XVIII que presenta una amplia nave con capillas laterales, muros encalados con contrafuertes de cantería marrón y un rico artesonado mudéjar polícromo de tradición canaria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35019','monumento','Yacimiento Arqueológico de la Fortaleza de Ansite','Monumental e imponente estructura geológica volcánica calada por cuevas naturales donde se refugiaron los últimos aborígenes canarios frente a las tropas castellanas en 1483, conservando silos excavados y grabados rupestres.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35021','iglesia','Iglesia de Santa Brígida','Templo reedificado a principios del siglo XX en un estilo historicista de inspiración neogótica que incorpora elementos de la antigua fábrica barroca como la cimentación de la torre, destacando su fachada de sillería vista de granito y un interior de tres naves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35021','monumento','Yacimiento Troglodita de La Atalaya','Singular poblado tradicional constituido por cuevas habitacionales excavadas en laderas de toba volcánica que conserva viva desde la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35023','iglesia','Cenobio de Valerón','Espectacular y colosal granero colectivo prehispánico excavado por los antiguos canarios bajo una enorme cueva natural de roca volcánica, constituido por más de trescientos silos intercomunicados en varios niveles destinados al almacenamiento de cereal que representan una cumbre de la ingeniería aborigen.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35023','iglesia','Iglesia de Santa María de Guía','Monumental templo barroco y neoclásico del siglo XVIII que exhibe una fachada monumental de sillería caliza vista con portada flanqueada por pilastras y dos esbeltas torres-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35024','monumento','Castillo de Santa Bárbara (Guanapay)','Monumental e imponente fortaleza militar del siglo XVI emplazada en la cumbre de un cráter volcánico que conserva sus potentes murallas de sillería de basalto negro, puentes levadizos de madera y fosos defensivos destinados a la protección de la antigua capital frente a los piratas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35024','monumento','Conjunto Histórico de la Villa de Teguise','Núcleo urbano tradicional que destaca por la conservación impecable de su trazado medieval y barroco con calles empedradas jalonadas de conventos del siglo XVII (como San Francisco), palacetes de portadas de cantería roja y tradicionales fachadas encaladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35024','monumento','Santa Cruz de Tenerife','Santa Cruz de Tenerife (Ciudad) • Mapy.com 15 may 2025 — Ciudad Santa Cruz de Tenerife, capital de la provincia y de las Islas Canarias, es una vibrante ciudad costera unida a San Cristób...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35024','monumento','San Cristóbal de La Laguna-Tenerife 11 ago 2025 — 🌎 Modelo para América','Su trazado urbano en cuadrícula fue pionero en España y sirvió de inspiración para ciudades coloniales en ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35024','monumento','14 mil resultados de imágenes, fotos de stock e ilustraciones libres de regalías para Santa cruz tenerife La Orotava, Sa','14 mil resultados de imágenes, fotos de stock e ilustraciones libres de regalías para Santa cruz tenerife La Orotava, Santa Cruz de Tenerife ( provincia de Santa Cruz de Tenerife ) , Islas Canarias, España-14 de julio de 2025. Edificio ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35025','monumento','Risco Caído y Montañas Sagradas de Gran Canaria','Paisaje cultural y arqueológico excepcional declarado Patrimonio de la Humanidad por la UNESCO que destaca por sus cuevas trogloditas prehispánicas usadas como templos astronómicos calados por cúpulas artificiales con canales que proyectaban la luz solar y lunar sobre inscripciones sagradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35025','iglesia','Iglesia de Nuestra Señora del Socorro','Templo edificado a principios del siglo XX que presenta una arquitectura tradicional canaria de paramentos encalados combinados con cantería gris basáltica regular en los ángulos y un interior cubierto por armaduras de madera mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35026','iglesia','Basílica de San Juan Bautista','Monumental templo gótico y mudéjar iniciado en el siglo XV que destaca por su fastuosa portada de sillería caliza vista de la escuela sevillana y por albergar en su altar mayor el Cristo de Telde, una excepcional escultura del siglo XVI confeccionada por indígenas mexicanos mediante una pasta de médula de caña de maíz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35026','monumento','Yacimiento Arqueológico de Cuatro Puertas','Espectacular complejo arqueológico prehispánico excavado en una montaña volcánica que constituía un santuario de los antiguos canarios, caracterizado por una gran cueva con cuatro monumentales aberturas talladas en la roca viva orientadas astronómicamente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35026','monumento','Barrio Histórico de San Francisco','Núcleo tradicional amurallado que conserva de forma óptima su trama urbana de callejuelas estrechas empedradas, casas solariegas encaladas del siglo XVII con portadas de cantería de basalto y tradicionales balconadas de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35027','iglesia','Basílica de Nuestra Señora del Pino','Monumental basílica neoclásica edificada en el siglo XVIII por el arquitecto Antonio de la Rocha que destaca por su fachada de sillería de cantería gris profusamente esculpida flanqueada por una recia torrecampanario de piedra de planta octogonal y por custodiar la venerada imagen barroca de la patrona insular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35027','monumento','Conjunto Histórico de la Plaza del Pino','Histórico espacio público porticado configurado por edificios señoriales del siglo XVIII de fachadas polícrómas encaladas provistas de las balconadas de madera de pino tea labrada más espectaculares y representativas del archipiélago canario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35028','iglesia','Iglesia de Nuestra Señora de la Candelaria','Templo parroquial de origen barroco rural (siglo XVII) profundamente transformado que muestra una fachada de paramentos enlucidos con un portal moldurado de cantería volcánica, un interior de nave única y un robusto campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35028','monumento','A Casa de José Saramago','Residencia tradicional de muros encalados donde habitó y redactó sus últimas obras el célebre premio nobel de literatura portugués, restaurada rigurosamente para conservar su inmensa biblioteca personal de madera, su escritorio tradicional y el jardín de olivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35029','iglesia','Santuario de la Virgen de los Dolores (Mancha Blanca)','Centro de peregrinación edificado a finales del siglo XVIII en estilo barroco canario sobre coladas de lava prehistóricas, caracterizado por su sobria fachada encalada con portal moldurado de sillería basáltica y una torre-campanario que corona el paisaje volcánico del entorno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35030','iglesia','Iglesia de San Miguel de Tuineje','Templo parroquial de traza mudéjar edificado en el siglo XVIII con aparejo de mampostería regular enlucida que destaca por albergar en su portada de sillería inscripciones y grabados que conmemoran las históricas batallas carlistas y de piratería británica de Tamasite.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35031','iglesia','Iglesia de San Miguel','Templo parroquial de factura neoclásica del siglo XVIII construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de paramentos enlucidos con portalada de piedra caliza moldurada y un robusto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35032','iglesia','Iglesia de San Vicente Ferrer','Templo parroquial levantado a finales del siglo XIX en estilo ecléctico que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista de cantería gris basáltica calada con un gran óculo central moldurado y un recio campanario de torre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35033','iglesia','Iglesia de San Mateo','Edificio religioso de época barroca y ecléctica (siglo XVIII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una portada de cantería moldurada con hornacina superior y un esbelto campanario de torre de planta octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','iglesia','Iglesia de Nuestra Señora de los Remedios','Monumental templo barroco edificado en el siglo XVIII que destaca por haber sobrevivido de forma milagrosa a las destructivas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','monumento','Yacimiento Arqueológico de Rubicón (San Marcial de Rubicón)','Restos históricos del primer asentamiento y obispado fundado por los conquistadores normandos en 1402 en la costa meridional de la isla, del que se conservan pozos de piedra basáltica, cimientos de la primitiva torre fortificada y necrópolis.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','monumento','Me indiques qué provincia activa abriremos de forma inmediata cuando des la señal de "ok"','Me indiques qué provincia activa abriremos de forma inmediata cuando des la señal de "ok"','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','monumento','Provincia de Santa Cruz de Tenerife','Que engloba las islas occidentales de Tenerife, La Palma, La Gomera y El Hierro. [1, 2, 3, 4]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','monumento','¿Cuántas islas tiene Canarias y cuáles son? 2 feb 2024 — Las Palmas','¿Cuántas islas tiene Canarias y cuáles son? 2 feb 2024 — Las Palmas ( provincia de Las Palmas ) , al este, que engloba Gran Canaria, Fuerteventura, Lanzarote y La Graciosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','monumento','¿Qué islas forman Canarias y cuántas son? Ocho cosas que no sabías del archipiélago canario 12 mar 2019 — Políticamente, Canarias ( comunidad autónoma de Canarias ) se divide en dos provincias','Santa Cruz de Tenerife, que comprende las ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','monumento','¿Cuántas islas tiene Canarias y cuáles son? 2 feb 2024 — La Graciosa Santa Cruz de Tenerife','¿Cuántas islas tiene Canarias y cuáles son? 2 feb 2024 — La Graciosa Santa Cruz de Tenerife ( provincia de Santa Cruz de Tenerife ) , al oeste, que engloba las islas de Tenerife, El Hierr...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38001','monumento','Casa Fuerte de Adeje','Ruinas consolidadas de un imponente complejo fortificado y residencial del siglo XVI que constituía el centro del poder señorial de los Ponte, caracterizado por sus muros de mampostería basáltica, su torre de defensa cuadrangular con aspilleras y sus almacenes destinados al azúcar. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38001','iglesia','Iglesia Matriz de Santa Úrsula','Templo de arquitectura tradicional canaria levantado entre los siglos XVI y XVII que destaca por su fachada encalada con portal de piedra moldurada, sus dos naves cubiertas por artesonados mudéjares de madera de pino tea y un valioso conjunto de retablos barrocos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38001','monumento','Zona Arqueológica de Morro de la Geita','Yacimiento prehispánico de los guanches que conserva estaciones de grabados rupestres con motivos canales y cazoletas tallados en bloques de roca volcánica asociados a estructuras habitacionales de piedra seca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90630','iglesia','Iglesia de San Marcos Evangelista','Templo parroquial reedificado a principios del siglo XX en un llamativo estilo neogótico de influencia mudéjar, caracterizado por sus','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90630','monumento','Conjunto Histórico del Casco Urbano','Núcleo tradicional que destaca por la conservación impecable de su trama urbana de callejuelas empedradas jalonadas de casas solariegas de los siglos XVIII y XIX con muros de piedra y techumbres de teja árabe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90631','iglesia','Iglesia de Nuestra Señora del Rosario','Templo parroquial de traza mudéjar edificado en el siglo XVI que exhibe una fachada encalada muy sobria con portalada de cantería gris, un interior de nave única con artesonados de madera noble labrada y una valiosa talla flamenca de la virgen.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90631','monumento','Faro de Punta Cumplida','Monumental infraestructura civil e industrial construida en el siglo XIX mediante una esbelta torre cilíndrica de sillería de basalto negro regular que constituye uno de los faros más antiguos y señeros del archipiélago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90632','iglesia','Iglesia de San Pedro Apóstol','Edificio religioso de época barroca (siglo XVII) edificado con muros portantes de mampostería encalada que muestra una amplia nave longitudinal, una portada clasicista de cantería moldurada y un rico artesonado mudéjar polícromo de tradición canaria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90632','monumento','Los Gemelos (Dragos de Breña Alta)','Monumento natural y etnográfico constituido por dos ejemplares centenarios de drago (Dracaena draco) entrelazados que forman una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38027','ermita','Ermita de Nuestra Señora de la Bonanza','Pequeño santuario de traza mudéjar del siglo XVIII edificado en mampostería basta que presenta una planta de cajón muy sobria, un porche delantero techado a dos aguas para refugio de los fieles y un rico artesonado interior de viguería de tea labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38027','monumento','Estación de Grabados Rupestres de El Julan (o de La Fajana)','Excepcional y musealizado conjunto de petroglifos prehispánicos tallados por los benahoaritas sobre coladas de lava volcánica lisa, constituyendo una cumbre de los grabados rupestres con motivos geométricos y espirales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38027','monumento','Fábrica-Museo de la Seda de El Paso','Complejo artesanal e industrial decimonónico que constituye un hito etnográfico mundial al conservar intactos los telares de madera manuales, los tornos de hilado y las herramientas tradicionales destinadas a la producción de seda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90633','ermita','Ermita de la Virgen de los Dolores (Ruinas de Fasnia Alta)','Vestigios consolidados de un templo barroco rural del siglo XVII que conserva su portada de sillería marrón y lienzos de mampostería basta, integrados de forma pintoresca en un paisaje rural de bancales de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16085','iglesia','Campanario de la Iglesia de Nuestra Señora de la Candelaria','Singular y monumental campanario de torre exento construido en el siglo XIX sobre la cumbre de una aguja volcánica roja (Joapira) separada del templo parroquial, ejecutado en sillería basta de basalto que domina todo el valle del Golfo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16085','iglesia','Santuario de Nuestra Señora de los Reyes','Complejo religioso de traza barroca rural emplazado en un árido paraje desértico del extremo occidental de la isla que cuenta con una iglesia de nave única con paramentos enlucidos blancos y una hospedería anexa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16085','monumento','Poblado de Guinea (Centro de Interpretación)','Espectacular asentamiento etnográfico y arqueológico musealizado que conserva las plantas completas de viviendas de piedra seca superpuesta construidas sobre un tubo volcánico, ilustrando el hábitat tradicional herreño desde la época bimbache.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90634','monumento','Conjunto de los Faros de Fuencaliente','Complejo civil e industrial constituido por el antiguo faro decimonónico de sillería de basalto negro regular y la moderna torre cilíndrica de hormigón aligerado con paramentos pintados que se alzan de forma espectacular sobre coladas de lava frente al océano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90634','monumento','Yacimiento de Grabados Rupestres de El Tendal','Monumental complejo arqueológico que conserva cuevas habitacionales prehispánicas y espectaculares estaciones de petroglifos tallados en roca volcánica con formas geométricas por los aborígenes benahoaritas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90634','monumento','Anexo','Bienes de interés cultural de la provincia de Santa Cruz de Tenerife Adeje ( Isla de Tenerife) Nombre Tipo Ubicación Casa Fuerte Monumento Arquitectura defensiva Época: Siglo XVI Adeje Calle Concepci...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90634','monumento','Provincia de SANTA CRUZ DE TENERIFE ISLA DE PALMA','Provincia de SANTA CRUZ DE TENERIFE ISLA DE PALMA (LA) . —1''nmprcnde lo, Ayuntandentos de Barlovento, Breim Alta, Breña Baja, Fuencaliente de la Palma, Garafía, Llano...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','monumento','Castillo de San Miguel','Fortaleza militar costera de planta cuadrada construida en 1575 que destaca por ser el único edificio que sobrevivió milagrosamente a la destructiva erupción volcánica de 1706, exhibiendo recios muros de sillería de basalto negro con saeteras y garitones angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','iglesia','Convento de San Francisco de Asís','Monumental complejo cenobítico fundado en el siglo XVI que presenta una fachada encalada de gran pureza formal y destaca por sus dos majestuosos claustros interiores porticados de madera noble de pino tea con tallas de filigrana mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','iglesia','Iglesia Matriz de Santa Ana','Templo reedificado en el siglo XVIII sobre los cimientos barrocos sepultados por la lava que exhibe una imponente fachada neoclásica de cantería gris labrada, tres naves longitudinales de gran amplitud con artesonados mudéjares y un rico tesoro de orfebrería de plata repujada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','palacio','Palacio de los Condes de La Gomera (Casa de Piedra)','Suntuosa residencia señorial del siglo XVII que constituye una cumbre de la arquitectura civil canaria al presentar una fastuosa fachada exenta tallada íntegramente en cantería de basalto gris con columnas corintias y portadas barrocas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38016','monumento','Estación Arqueológica de La Zarza y La Zarcita','Monumental complejo de petroglifos prehispánicos que constituye el yacimiento de arte rupestre más importante y espectacular de los aborígenes benahoaritas, célebre por sus colosales paneles de roca volcánica grabados con complejos motivos geométricos, meandros y espirales místicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38016','iglesia','Iglesia de Nuestra Señora de la Luz','Templo parroquial de traza mudéjar edificado en el siglo XVI que exhibe una sobria fachada encalada con un dintel de cantería gris moldurada, un interior de dos naves con magníficas techumbres de viguería de tea y un valioso retablo barroco de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38017','iglesia','Iglesia de San Antonio de Padua','Templo edificado en el siglo XVIII de líneas clasicistas muy sobrias que presenta una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38017','monumento','Yacimiento de la Zona Arqueológica de Tagoror de El Julan','Vestigios prehispánicos de los guanches constituidos por una estructura circular exenta de mampostería seca destinada tradicionalmente a los consejos de ancianos o asambleas de la antigua jefatura aborigen de Abona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38019','iglesia','Iglesia de Nuestra Señora de la Luz','Templo parroquial levantado a principios del siglo XIX sobre un oratorio barroco anterior que presenta una fachada monumental flanqueada por pilastras, tres naves longitudinales de gran amplitud con techumbres mudéjares y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38019','monumento','Conjunto de Lavaderos Tradicionales','Infraestructura hidráulica comunal del siglo XIX ejecutada en piedra basta volcánica con canales labrados que constituye un testimonio del aprovechamiento tradicional del agua en el sector meridional de la isla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38024','iglesia','Iglesia de Nuestra Señora de los Remedios','Templo parroquial originario del siglo XVI que presenta una hermosa fachada encalada con portadas labradas en cantería gris, un amplio interior de tres naves con artesonados mudéjares de madera de pino tea y una célebre imagen mariana de factura flamenca del siglo XVI.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38024','monumento','Plaza de España y Casas Consistoriales','Histórico espacio público que destaca por la conservación de suntuosas casonas solariegas de arquitectura tradicional canaria de los siglos XVII y XVIII, caracterizadas por sus balconadas exentas de madera noble y rodeadas por laureles de Indias centenarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38025','iglesia','Iglesia del Salvador','Templo parroquial edificado en el siglo XVIII sobre un oratorio primitivo del siglo XVI que exhibe una fachada de paramentos blancos con portada mudéjar de cantería gris, cubiertas de armadura de madera noble y valiosas pinturas sacras barrocas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38025','ermita','Ermita de San Antonio de Padua','Pequeño santuario rural erigido originalmente a finales del siglo XV que constituye uno de los templos católicos más antiguos de la isla, mostrando una sencilla tipología de planta de cajón con muros de mampostería basta enfoscada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','iglesia','Iglesia de la Concepción (Santuario Matriz)','Magna basílica del siglo XVIII declarada Monumento Histórico-Artístico Nacional que constituye una obra cumbre del barroco clasicista canario, célebre por su fastuosa fachada monumental de cantería gris profusamente esculpida por el maestro Patricio García, sus dos esbeltas torres-campanario y una colosal cúpula de influencia renacentista italiana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','monumento','Casa de los Balcones (Casa Méndez-Fonseca)','Suntuoso palacio residencial del siglo XVII que representa el máximo exponente de la arquitectura civil e historicista insular gracias a su monumental fachada con una impresionante y larga balconada exenta de madera de pino tea, profusamente labrada con motivos calados mudéjares, y un patio de armas interior de tres pisos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','palacio','Liceo de Taoro (Palacete de la Finca El Majuelo)','Palacio de estética ecléctica construido a principios del siglo XX sobre un promontorio que domina el valle de la Orotava, caracterizado por sus simétricas fachadas de aire clasicista, grandes escalinatas imperiales de piedra azul y frondosos jardines de diseño romántico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','monumento','Hijuela del Botánico','Espectacular y recóndito jardín exótico de aclimatación fundado a finales del siglo XVIII que alberga centenares de especies vegetales de los cinco continentes y un espectacular dintel de entrada forjado con motivos de filigrana orgánica contemporánea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','iglesia','Antiguo Convento de San Agustín (Actual Casa de la Cultura)','Complejo cenobítico fundado en el siglo XVII que destaca por su iglesia gótica tardía de líneas severas, un bellísimo claustro interior porticado de madera noble con capiteles jónicos y portadas de sillería basáltica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38011','monumento','Castillo de San Felipe','Fortaleza militar costera de planta pentagonal construida en el siglo XVII para repeler los ataques de la piratería internacional que destaca por sus potentes murallas de sillería de basalto negro, sus casamatas abovedadas y sus fosos defensivos totalmente consolidados como espacio cultural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38011','iglesia','Iglesia de Nuestra Señora de la Peña de Francia','Monumental templo edificado entre los siglos XVII y XVIII que presenta una imponente fachada de paramentos enlucidos flanqueada por una recia torre-campanario de cantería gris de planta cuadrada, tres amplias naves cupuladas y un rico artesonado mudéjar de tradición canaria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38011','monumento','Casa de la Aduana','Palacio civil e industrial del siglo XVII que constituye el edificio de arquitectura tradicional canaria más antiguo y representativo del muelle portuario, caracterizado por sus muros de mampostería regular, su portal heráldico de cantería y su mirador de viguería de tea rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38011','monumento','Complejo de Costa Martiánez','Espectacular parque marítimo y lago artificial de vanguardia proyectado por el genial artista César Manrique a finales del siglo XX que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38030','iglesia','Iglesia de San Juan Bautista','Edificio religioso románico del siglo XVI profundamente transformado en época barroca que destaca por albergar una notable cabecera de sillería caliza regular y una portada meridional de cantería moldurada flanqueada por una recia torre-campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38010','iglesia','Iglesia Matriz de Santiago Apóstol','Excepcional joya de la arquitectura sacra del siglo XV declarada Monumento Histórico-Artístico Nacional al constituir el primer templo cristiano de la isla de Tenerife tras la conquista castellana, la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38010','monumento','Hacienda de los Príncipes','Gran complejo agropecuario e industrial del siglo XVI fundado por el conquistador Alonso Fernández de Lugo que conserva sus portales de arco de medio punto con grandes dovelas en piedra local, las estancias residenciales y restos del primer ingenio azucarero de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38032','ermita','Ermita de Nuestra Señora de la Esperanza','Templo parroquial de traza barroca rural edificado en el siglo XVIII sobre un oratorio anterior que presenta una fachada enlucida con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular ejecutada en piedra caliza local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38033','iglesia','Iglesia de San Andrés Apóstol','Monumental templo gótico tardío del siglo XVI que presenta una amplia nave con bóveda de crucería calada, una fachada sobria con portalada renacentista de sillería caliza gálica y una robusta torrecampanario cuadrangular de vigía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38033','monumento','Puente de Los Tilos','Viaducto de ingeniería civil contemporánea inaugurado a principios del siglo XXI que constituye un hito de la arquitectura del hormigón aligerado al salvar el espectacular desfiladero de Los Tilos mediante un audaz y gigantesco arco de un solo ojo sin pilares intermedios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38034','iglesia','Iglesia de San Juan Bautista','Templo de traza barroca clasicista edificado en el siglo XVIII que presenta una fachada monumental de sillería vista con portada moldurada flanqueada por pilastras, una nave de gran amplitud con capillas intercomunicadas y un esbelto campanario octogonal con remate cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38036','monumento','Torre del Conde','Monumental e imponente torre del homenaje medieval del siglo XV que constituye la fortificación militar más antigua de las islas Canarias, caracterizada por su planta prismática cuadrangular ejecutada con sillería de basalto rojo regular combinada con encalado blanco y saeteras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38036','iglesia','Iglesia de Nuestra Señora de la Asunción','Magna basílica del gótico civil y del barroco clasicista que presenta una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38036','monumento','Casa de la Aguada (Pozo de Colón)','Antigua residencia de los antiguos gobernadores señoriales de la isla del siglo XV que conserva en su patio de armas central el histórico pozo de mampostería regular de donde Cristóbal Colón tomó el agua para el descubrimiento del nuevo mundo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38037','monumento','Casco Histórico y Balcones de la Avenida Marítima','Núcleo urbano tradicional de traza renacentista y barroca pacífica que destaca por la conservación impecable de sus calles adoquinadas jalonadas de palacetes de los siglos XVI al XIX, célebre por albergar la corona de balcones dobles de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38037','iglesia','Iglesia Matriz de El Salvador','Magna colegiata de traza gótica construida entre los siglos XIII y XIV que presenta una imponente nave única de gran anchura con capillas laterales entre contrafuertes robustos, una monumental fachada de cantería y un campanario octogonal calado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38037','monumento','Casas Consistoriales (Ayuntamiento)','Palacio civil renacentista construido en el siglo XVI que destaca por su fachada monumental de sillería vista provista de una monumental arcada porticada de arcos de medio punto sobre columnas corintias con relieves.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38012','iglesia','Iglesia de Nuestra Señora de la Concepción','Monumental basílica reedificada en el siglo XVIII en estilo barroco clasicista que destaca por su esbelto campanario de torre exento de planta cuadrada con ventanas geminadas caladas de gran virtuosismo geométrico, considerada la iglesia matriz de la capital.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38012','palacio','Palacio de la Capitanía General de Canarias','Palacio civil barroco construido en el siglo XVII por el arquitecto Francesc Pons que presenta una monumental fachada neoclásica de sillería caliza vista, sus patios interiores porticados y su capilla cupulada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38012','monumento','Castillo de San Juan Bautista (Castillo Negro)','Fortaleza militar costera de planta circular levantada en el siglo XVII para repeler los ataques de la piratería internacional, la cual conserva sus potentes baluartes de cantería basáltica y casamatas interiores totalmente rehabilitadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38012','monumento','Auditorio de Tenerife "Adán Martín"','Magna obra de la arquitectura contemporánea racionalista proyectada en 2003 por el arquitecto Santiago Calatrava que destaca mundialmente por su audaz estructura de hormigón aligerado calada por una gigantesca sobrecubierta que simula un ala de mariposa. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38039','iglesia','Iglesia de Santa Úrsula','Templo de traza barroca rural edificado en el siglo XVIII sobre un oratorio medieval previo del que subsiste una sobria portalada de sillería caliza con arquivoltas molduradas, un interior de nave única y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38013','iglesia','Iglesia de San Fernando Rey','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de paramentos enlucidos con portal de cantería moldurada flanqueada por pilastras, un interior de nave única con artesonados mudéjares de madera de pino tea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38043','iglesia','Santuario del Santísimo Cristo de Tacoronte','Monumental templo edificado en el siglo XVII por la orden agustina que destaca por albergar en su altar mayor la venerada talla barroca del Cristo de Tacoronte colocada sobre un espectacular sagrario de plata repujada, flanqueada por una fachada de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38044','iglesia','Iglesia de San Antonio de Padua','Templo parroquial levantado a finales del siglo XIX en estilo ecléctico que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista de cantería gris basáltica calada con un gran óculo central moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38045','iglesia','Iglesia de San Miguel Arcángel','Templo parroquial de origen románico profundamente transformado en época barroca que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38047','iglesia','Iglesia de Nuestra Señora de Candelaria','Templo de base medieval profundamente transformado en el barroco rural que presenta una planta de nave única, una portalada con dovelas de piedra arenisca y un campanario de torre de planta cuadrangular que corona el perfil urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38050','iglesia','Iglesia de San Juan Bautista','Templo parroquial de traza neoclásica edificado en el siglo XIX que presenta una fachada monumental de líneas severas con portal de cantería moldurada flanqueada por pilastras, un interior de nave única cubierto con bóvedas de lunetos y una esbelta torrecampanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38051','iglesia','Iglesia de Nuestra Señora de la Victoria','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de sillería caliza vista con portada clasicista moldurada, un interior de tres naves de gran amplitud y un esbelto campanario octogonal con remate cupulado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','iglesia','Iglesia de San Pedro Apóstol','Monumental e imponente templo barroco del siglo XVII que constituye el gran símbolo de la villa al presentar una espectacular fachada de cantería regular gris de las canteras locales flanqueada por pilastras y un artesonado mudéjar de madera de pino tea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','iglesia','Santuario del Santo Hermano Pedro','Complejo religioso de factura contemporánea edificado sobre la vivienda natal del primer santo canario que conserva las estructuras de piedra','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','monumento','Abrir la Provincia de Las Palmas','Abrir la Provincia de Las Palmas (revisando si queda algún remanente)','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','monumento','Proponer otra provincia activa que desees catalogar de inmediato','Proponer otra provincia activa que desees catalogar de inmediato','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','monumento','El nacimiento de una ciudad','Santa Cruz de Tenerife 7 nov 2016 — El nacimiento de una ciudad: Santa Cruz de Tenerife El castillo de San Cristóbal fue el principal de la ciudad. El castillo de San...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','monumento','Provincia de SANTA CRUZ DE TENERIFE ISLA DE PALMA','Provincia de SANTA CRUZ DE TENERIFE ISLA DE PALMA (LA) . —1''nmprcnde lo, Ayuntandentos de Barlovento, Breim Alta, Breña Baja, Fuencaliente de la Palma, Garafía, Llano...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90027','monumento','Núcleos de población de Alfoz de Lloredo','El término municipal incluye los siguientes núcleos de población: Novales, Cóbreces, Cigüenza y Oreña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90027','iglesia','Iglesia de San Martín de Cigüenza','Monumental templo barroco del siglo XVIII que destaca por sus dos esbeltas torres cilíndricas rematadas en cúpula y linterna, configurando una de las muestras más singulares de la arquitectura barroca indiana en la cornisa cantábrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90027','iglesia','Abadía de Santa María de Viaceli (Cóbreces)','Monasterio trapense edificado a principios del siglo XX en un purísimo estilo neogótico que constituye un hito constructivo al ser el primer complejo monumental de España ejecutado íntegramente en hormigón armado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90027','monumento','Cueva de Cualventi','Yacimiento arqueológico del Paleolítico superior que conserva una valiosa estación de arte rupestre con grabados y pinturas parietales en tonos rojizos ejecutadas por los grupos de cazadores-recolectores del magdaleniense.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90635','iglesia','Iglesia de San Salvador','Templo parroquial de factura barroca rural reedificado en el siglo XVII que presenta una planta de nave única con capillas laterales, una fachada sencilla enlucida con portal de cantería moldurada y una recia torre-campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90635','monumento','Molino de Jado','Antiguo molino de mareas situado en las marismas de Santoña que constituye un notable testimonio de la arqueología industrial preindustrial al conservar sus muros de mampostería basta y las canalizaciones de piedra destinadas a la molienda tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','monumento','Núcleos de población de Arnuero','El término municipal incluye los siguientes núcleos de población: Isla, Castillo Siete Villas y Soano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','monumento','Casco Histórico de Isla','Conjunto fortificado señorial de origen medieval que conserva una corona de torres de defensa de planta cuadrangular de los siglos XIV al XVI (como','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','palacio','Palacio de los Condes de Isla','Palacio civil barroco edificado en el siglo XVII por orden del arzobispo de Burgos que destaca por su simétrica fachada de sillería vista flanqueada por cubos defensivos angulares y portadas heráldicas con los escudos familiares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','iglesia','Iglesia de San Julián y Santa Basilisa (Isla)','Monumental templo de traza gótica transicionada al Renacimiento que presenta una planta de tres naves de gran amplitud cubierta por complejas bóvedas de crucería y un fastuoso retablo mayor de estilo churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','iglesia','Iglesia de San Pedro (Castillo Siete Villas)','Edificio religioso que destaca por su imponente torre-campanario del siglo XVI de planta cuadrangular, provista de contrafuertes robustos y rematada por un antepecho balaustrado y gárgolas esculpidas en piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90636','monumento','Núcleos de población de Arredondo','El término municipal incluye los siguientes núcleos de población: Asón, Bustablado y Val de Asón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90636','iglesia','Iglesia de San Pelayo','Monumental templo edificado en el siglo XIX de estilo neoclásico indiano que presenta una imponente rotonda columnada y una colosal torre-campanario exenta de planta circular, proyectada a imitación de los faros marinos por su mecenas retornado de América.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90636','iglesia','Iglesia Rupestre de San Juan (Socueva)','Excepcional y recóndito eremitorio rupestre de origen altomedieval (siglo IX) excavado directamente bajo una enorme balma o oquedad natural de roca caliza, conservando un rústico altar de piedra y un muro exterior de mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','monumento','Núcleos de población de Aller','El término municipal incluye los siguientes núcleos de población: Cabañaquinta, Moreda, Serrapio y Pelúgano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','iglesia','Iglesia de San Vicente de Serrapio','Excepcional joya del románico rural asturiano del siglo XII edificada con aparejo regular de cantería que destaca por su cabecera triabsidial con ventanas de medio punto caladas y por albergar en su interior un valioso ciclo de capiteles historiados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','monumento','Torre de Soto','Ruinas consolidadas de una estratégica torre de defensa bajomedieval del siglo XIV de planta cuadrangular ejecutada en mampostería basta y sillería en los ángulos que servía para el control del paso fluvial de la comarca del caudal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','monumento','Pozo San Jorge (Moreda)','Monumental instalación minera de la arqueología industrial del carbón de principios del siglo XX que destaca por mantener intacto su castillete metálico de celosía remachada, las salas de máquinas de vapor y los cargaderos de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05001','monumento','Núcleos de población de Amieva','El término municipal incluye los siguientes núcleos de población: Sames, San Román y Precendi.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05001','monumento','Mansión de Peruyera (Sames)','Casa solariega señorial de estilo barroco tradicional del siglo XVIII que presenta una simétrica fachada de mampostería regular enlucida con un gran blasón heráldico finamente tallado en piedra caliza, ventanas conopiales y balconadas de forja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05001','monumento','Puente Romano de Dobra','Viaducto de origen medieval (siglo XIV) ejecutada con un único y colosal arco apuntado de gran luz que salva de forma vertiginosa el curso del río Dobra, asentado directamente sobre los contrafuertes naturales de roca caliza viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','monumento','Núcleos de población de Avilés','El término municipal incluye los siguientes núcleos de población: Miranda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','iglesia','Iglesia de Santo Tomás de Canterbury (Sabugo)','Monumental templo gótico del siglo XIII conocido como la "Iglesia de los Marineros" que destaca por su imponente portalada meridional de arquivoltas ojivales molduradas sobre columnas, su ábside poligonal y por albergar las lápidas heráldicas de la nobleza avilesina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','palacio','Palacio de Camposagrado','Palacio civil del barroco pleno edificado en el siglo XVII que presenta una fastuosa fachada norte exenta de tres pisos provista de una monumental arcada porticada, columnas entorchadas de gran virtuosismo escultórico y blasones de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','monumento','Plaza de España y Calles de Galiana y Rivero','Histórico espacio público urbano medieval y barroco que destaca por la conservación impecable de sus suntuosas calles porticadas provistas de un colosal enlosado de piedra caliza calavera y arcadas que sostienen las solanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','monumento','Centro Niemeyer','Vanguardista complejo arquitectónico de la arquitectura contemporánea diseñado por el arquitecto brasileño Oscar Niemeyer e inaugurado en 2011, caracterizado por sus puras formas geométricas curvas de hormigón aligerado blanco y una colosal marquesina helicoidal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05003','monumento','Núcleos de población de Belmonte de Miranda','El término municipal incluye los siguientes núcleos de población: San Martín de Lodón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05003','iglesia','Monasterio de Santa María de Larna','Ruinas consolidadas de un imponente cenobio benedictino del siglo XII que conserva los alzados de sillería de su templo de transición, arcos fajones apuntados y tramos de muros perimetrales integrados en un agreste paisaje boscoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05003','monumento','Yacimiento de las Minas de Oro de las Cruces','Complejo minero de época imperial romana (siglo I d.C.) que constituye una muestra primordial de la ingeniería de la ruina montium, conservando los canales de piedra tallados en la montaña y las balsas de decantación de lodos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90638','monumento','Núcleos de población de Bimenes','El término municipal incluye los siguientes núcleos de población: Martimporra y San Julián.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90638','palacio','Palacio de Martimporra','Palacio señorial de traza barroca clasicista construido a finales del siglo XVII para la familia Estrada que destaca por su simétrica planta cuadrangular flanqueada por dos robustas torres de sillería vista, portales de medio punto y capilla adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90639','monumento','Núcleos de población de Boal','El término municipal incluye los siguientes núcleos de población: Serandinas y Doiras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90639','monumento','Casas de Indianos de Boal (Villa Anita)','Suntuoso conjunto residencial de arquitectura ecléctica y modernista edificado a principios del siglo XX por emigrantes retornados de Cuba que exhibe una fachada de gran vistosidad decorativa con profusa azulejería vidriada polícroma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','monumento','Núcleos de población de Cabrales','El término municipal incluye los siguientes núcleos de población: Carreña, Arenas, Sotres y Bulnes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','palacio','Palacio de Mestas y Cossío (Arenas)','Residencia señorial barroca del siglo XVIII que presenta una imponente fachada de cantería regular con portalada clásica moldurada flanqueada por pilastras jónicas, grandes ventanas de repisa labrada y un dintel con escudos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','iglesia','Iglesia de Santa María de Llas','Templo de base románica del siglo XII profundamente transformado en época barroca que mantiene su cabecera absidial y una portada meridional de arquivoltas molduradas en piedra caliza regular, cobijando un interior cubierto con bóvedas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','monumento','Núcleos de población de Cabranes','El término municipal incluye los siguientes núcleos de población: Santa Eulalia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','iglesia','Iglesia de San Julián de Viñón','Pequeño templo románico de finales del siglo XII edificado con aparejo rústico que presenta una planta de nave única con bóveda de cañón, un ábside semicircular liso orientado a levante y una espadaña de dos ojos sobre el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90640','monumento','Núcleos de población de Candamo','El término municipal incluye los siguientes núcleos de población: Grullos, San Román y Murias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90640','monumento','Cueva de la Peña de Candamo','Excepcional cavidad kárstica declarada Patrimonio de la Humanidad por la UNESCO que conserva un soberbio ciclo de arte rupestre paleolítico (del periodo Solutrense y Magdaleniense) con espectaculares grabados y pinturas parietales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90640','palacio','Palacio de Valdés Bazán (San Román)','Caserón señorial de estilo renacentista del siglo XVI reconstruido en el XVII que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','monumento','Núcleos de población de Cangas del Narcea','El término municipal incluye los siguientes núcleos de población: Corias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','iglesia','Monasterio de San Juan Bautista de Corias (El Escorial Asturiano)','Monumental e impresionante complejo conventual benedictino reconstruido en el siglo XVIII por el arquitecto Ventura Rodríguez en un severo estilo neoclásico, destacando su fachada de sillería caliza y su claustro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','palacio','Palacio de Omaña','Palacio civil del siglo XVI con fachada modificada en el barroco que presenta un monumental patio','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90011','monumento','Núcleos de población de Carreño','El término municipal incluye los siguientes núcleos de población: Candás.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90011','iglesia','Iglesia de San Félix de Candás','Templo de factura barroca del siglo XVIII profundamente reformado que destaca por albergar el camarín de la venerada e histórica imagen del Cristo de Candás, presentando una fachada monumental con portada moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90641','monumento','Núcleos de población de Caso','El término municipal incluye los siguientes núcleos de población: Campo de Caso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90641','iglesia','Colegiata de Santa María de Tanes','Monumental templo barroco del siglo XVI y reconstruido en el XVIII que destaca por sus grandes dimensiones enclavadas en el parque natural de Redes, caracterizado por su sillería de piedra arenisca local y un esbelto campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90012','monumento','Núcleos de población de Castrillón','El término municipal incluye los siguientes núcleos de población: Piedras Blancas y Salinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90012','monumento','Yacimiento del Castillo de Gauzón (Peñón de Raíces)','Restos históricos consolidados de una fortaleza altomedieval donde se forjó la Cruz de la Victoria en el año 908, conservando muros de mampostería basta, cimientos de torres defensivas y talleres metalúrgicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90013','monumento','Núcleos de población de Castropol','El término municipal incluye los siguientes núcleos de población: Figueras y Barres.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90013','palacio','Palacio de Valledor','Caserón señorial de traza barroca edificado en el siglo XVIII de planta cuadrangular estructurada en torno a un patio de armas central con muros de sillería de pizarra, grandes ventanas con molduras clasicistas y portales de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90014','monumento','Castro de Coaña (Castelón)','Espectacular y musealizado asentamiento fortificado de la cultura castreña del siglo IV a.C. que constituye un referente arqueológico nacional al conservar las plantas circulares de mampostería seca de ochenta viviendas, sus recintos termales y calles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90015','monumento','Núcleos de población de Colunga','El término municipal incluye los siguientes núcleos de población: Lastres y Gobiendes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90015','iglesia','Iglesia de Santiago de Gobiendes','Excepcional joya de la arquitectura prerrománica asturiana del siglo IX (periodo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90015','monumento','Conjunto Histórico del Puerto de Lastres','Espectacular y único ejemplo de población marinera que se conserva escalonada de forma vertiginosa sobre un acantilado rocoso calado por calles adoquinadas jalonadas de masías tradicionales de cantería y casas con porches.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90642','monumento','Núcleos de población de Corvera de Asturias','El término municipal incluye los siguientes núcleos de población: Nubledo y Trasona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90642','palacio','Palacio de Rodríguez de León (Trasona)','Gran residencia señorial fortificada originaria del siglo XV reformada en el barroco que cuenta con una fachada de líneas clasicistas de sillería caliza vista, sus patios porticados y salas nobles decoradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','monumento','Núcleos de población de Cudillero','El término municipal incluye los siguientes núcleos de población: El Pito y Oviñana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','monumento','Quinta de Selgas (El Pito)','Monumental e impresionante complejo palaciego y museístico del siglo XIX conocido como el "Versalles Asturiano" debido a sus dimensiones, el cual destaca por su fastuoso palacio de arquitectura francesa con salones nobles y un gran jardín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','monumento','Conjunto Histórico Anfiteatro de Cudillero','Núcleo urbano tradicional marinero que destaca por la conservación de sus casas tradicionales pintadas de vivos colores dispuestas de forma escalonada en un semicírculo rocoso natural que domina el muelle portuario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33022','iglesia','Iglesia de Santiago de Degaña','Templo parroquial de traza barroca rural edificado en el siglo XVIII que presenta muros exteriores de mampostería basta de piedra de alta montaña, una fachada con porche cubierto tradicional y una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33023','monumento','Núcleos de población de El Franco','El término municipal incluye los siguientes núcleos de población: La Caridad y Viavélez.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33023','palacio','Palacio de Miudes (Casa de la Torre)','Casa solariega de origen bajomedieval de planta cuadrangular y muros de mampostería de pizarra con sillares de cantería en los ángulos, un gran portal dovelado de arco de medio punto y ventanas conopiales talladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25004','ermita','Ermita de San Diego de Alcalá','Pequeño santuario mudéjar edificado en el siglo XVII junto a las ruinas del convento franciscano que presenta muros encalados con portal de cantería moldurada y que cobija una cueva natural sagrada de oración abovedada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25004','monumento','Museo Arqueológico de Fuerteventura','Caserón tradicional majorero que custodia una exhaustiva colección de ídolos de piedra basta, fragmentos de cerámica aborigen y herramientas que ilustran la cultura de los antiguos majos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35022','ermita','Ermita de San Nicolás de Bari (Sardina)','Pequeño oratorio mudéjar del siglo XVIII que presenta muros encalados con sillares basálticos en los ángulos, un sencillo portal adintelado de piedra y un rico artesonado interior de madera de pino tea rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35022','monumento','Yacimiento Arqueológico de La Sorrueda','Asentamiento prehispánico fortificado situado en el barranco de Tirajana que conserva cuevas habitacionales artificiales excavadas en la toba, silos de almacenamiento y estructuras de mampostería seca aborígenes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90643','monumento','Paseo de Gran Canaria y Paseo de Canarias','Espacio urbano y paisajístico único escalonado en pendiente que cuenta con una colosal cascada artificial de 30 metros ejecutada en piedra basta, jalonada por mosaicos cerámicos polícromos que representan los escudos heráldicos de todos los municipios de la isla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90643','iglesia','Iglesia de San Roque','Templo parroquial de factura ecléctica levantado sobre una antigua ermita del siglo XVI que presenta muros encalados con portadas de cantería gris labrada, un interior de nave única con artesonados mudéjares y un gran reloj de sol.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90643','monumento','Acequia Real de Firgas','Antigua infraestructura hidráulica preindustrial que conserva sus tramos de mampostería regular y los lavaderos públicos tradicionales de piedra volcánica donde se realizaba el reparto histórico de las aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90644','iglesia','Iglesia de San Juan Degollado','Templo parroquial levantado en el siglo XVIII de líneas clasicistas muy sobrias que presenta una amplia nave con capillas laterales, una fachada de paramentos blancos con portada mudéjar de cantería y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90644','monumento','Molino de de Viento de Arafo','Estructura hidráulica y etnográfica preindustrial que conserva sus muros de mampostería basta y las canalizaciones de piedra basta destinadas a la molienda tradicional del grano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90645','iglesia','Iglesia de San Juan Bautista (Arico el Nuevo)','Monumental templo del siglo XVIII declarado Monumento Histórico-Artístico','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90645','monumento','Conjunto Histórico de Arico el Nuevo','Núcleo tradicional que destaca por la conservación impecable de su trama urbana de casonas solariegas de los siglos XVII y XVIII con fachadas encaladas y portadas de sillería basáltica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38003','iglesia','Iglesia de Nuestra Señora de los Remedios','Templo parroquial de traza mudéjar y renacentista iniciado en el siglo XVI que presenta una imponente fachada encalada con portadas labradas en cantería gris, un amplio interior de tres naves con techumbres de madera noble de tea labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38003','monumento','Casco Histórico de Buenavista','Núcleo tradicional que conserva de forma óptima su trazado urbano de calles adoquinadas jalonadas de casonas de arquitectura tradicional canaria de los siglos XVII y XVIII con balconadas de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38041','iglesia','Iglesia de San Pedro Apóstol','Edificio religioso románico de transición y mudéjar edificado en el siglo XVI que presenta una sola nave cubierta por bóveda de madera labrada, un ábside semicircular orientado al este con cornisa de canecillos lisos y una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38901','iglesia','Iglesia de San Antonio de Padua','Pequeño templo de arquitectura tradicional herreña levantado en el siglo XVIII con muros de mampostería basta blanca, un sencillo portal adintelado mudéjar y un campanario de espadaña de un solo vano sobre el hastial principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38035','monumento','Casa de El Capitán','Caserón señorial de arquitectura tradicional canaria del siglo XVIII que destaca por su portada monumental de cantería gris labrada, sus balconadas interiores de madera noble y un patio de armas con pavimento de losas que funciona como museo etnográfico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38046','monumento','Conjunto Histórico de la Plaza de San Marcos','Espacio urbano tradicional que destaca por la conservación de suntuosas casonas solariegas de arquitectura tradicional canaria de los siglos XVII y XVIII, caracterizadas por sus fachadas de cantería vista con grandes portaladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90016','monumento','Poblado Talayótico de Torralba d''en Salort','Espectacular asentamiento prehistórico de la Edad del Bronce que conserva una de las taulas más grandes y perfectas de Menorca, consistente en un monumental monumento megalítico exento','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90016','iglesia','Iglesia de Santa Eulalia','Templo parroquial de traza barroca edificado en el siglo XVII sobre una estructura medieval anterior que domina el perfil escalonado de la villa, caracterizado por su imponente fachada de sillería de piedra arenisca local (marès) y una bóveda de crucería de gran luz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90016','monumento','Yacimiento de Roques Llisses','Monumental sepulcro megalítico de tipología dolménica del bronce inicial que conserva su cámara funeraria delimitada por losas calizas hincadas en el terreno y restos del túmulo perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90646','monumento','Castillo de Alaró (Castell d''Alaró)','Ruinas de una mítica e imponente fortaleza militar medieval de origen islámico y cristiano emplazada de forma vertiginosa sobre la cumbre de un espectacular risco de la sierra de Tramuntana, de la que subsisten potentes lienzos de murallas almenadas y la torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90646','iglesia','Iglesia de San Bartolomé','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de sillería vista de líneas clásicas muy sobrias con portada moldurada flanqueada por pilastras y un robusto campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90017','monumento','Castillo de Son Mas','Palacio señorial fortificado de origen medieval profundamente reformado en el siglo XIX bajo una estética historicista que funciona como sede consistorial, caracterizado por su recia torre de defensa cuadrangular con matacanes y sus grandes ventanales góticos calados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90017','iglesia','Iglesia de Santa María de Andratx','Templo parroquial de traza gótica tardía y barroca (siglo XVII) edificado en el núcleo histórico que presenta una amplia nave con capillas laterales entre contrafuertes robustos, muros exteriores de cantería y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90017','monumento','Torre de Cala en Basset','Torre de vigía y defensa costera contra la piratería berberisca erigida en el siglo XVI de planta circular y sillería perfecta de piedra local que conserva saeteras originales y se alza de forma espectacular sobre un acantilado frente a la isla de Sa Dragonera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07003','iglesia','Iglesia de Nuestra Señora de Atocha','Templo parroquial de factura barroca rural profundamente modificado que presenta una fachada de paramentos enlucidos blancos con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07003','monumento','Casal de Son Gual','Antigua casa solariega tradicional estructurada a partir del siglo XVII mediante aparejo de mampostería regular enlucida que destaca por su simetría de vanos adintelados y balconadas de forja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07004','iglesia','Santuario de San Salvador (Sant Salvador d''Artà)','Monumental e imponente complejo religioso fortificado emplazado en la cumbre del cerro que domina la villa, constituido por un recinto amurallado medieval de sillería caliza del siglo XIV con torreones de defensa y una fastuosa iglesia barroca renacentista con cúpula.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07004','monumento','Poblado Talayótico de Ses Païsses','Excepcional y musealizado asentamiento fortificado de la cultura talayótica que conserva una monumental muralla ciclópea de piedra caliza con un gran portal adintelado de acceso, un gran talayot central de planta circular y estructuras habitacionales exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07004','iglesia','Iglesia de la Transfiguración del Señor','Magna iglesia de traza gótica tardía construida entre los siglos XVI y XVII que presenta una imponente nave única de gran anchura, capillas laterales entre contrafuertes robustos provistas de ventanales calados con vitrales y un campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90647','monumento','Torre del Verger (Torre de Ses Ánimes)','Icónica torre de vigía y defensa costera contra los piratas berberiscos erigida en el siglo XVI de planta circular construida con aparejo de mampostería regular y mortero de cal calavera, colgada de forma vertiginosa sobre un espectacular acantilado marino de la sierra de Tramuntana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90647','monumento','Conjunto de Bancales e Hidráulica de Ses Mosqueres','Monumental obra de ingeniería agrícola preindustrial e islámica que configura el paisaje escalonado de la villa mediante bancales de piedra seca superpuesta (pedra en sec) provistos de aljibes, canales de piedra y acequias tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90648','iglesia','Iglesia de Santa María de Robines','Monumental templo barroco del siglo XVIII construido con sillería de piedra caliza de las reputadas canteras locales de Binissalem que destaca por su fastuosa fachada exenta provista de un portal neoclásico moldurado flanqueado por pilastras y un campanario octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90648','monumento','Casal de Ca los de Sa Nostra','Palacio señorial de arquitectura tradicional mallorquina del siglo XVIII que presenta una fachada monumental de sillería vista provista de grandes ventanales y un patio de armas interior porticado de gran belleza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90649','iglesia','Iglesia de San Pedro','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de paramentos enlucidos con portal de cantería moldurada flanqueada por pilastras, un interior de nave única y una recia torrecampanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90649','monumento','Molinos de de Viento de Búger','Conjunto etnográfico preindustrial constituido por las estructuras cilíndricas exentas de mampostería de antiguos molinos destinados tradicionalmente a la molienda del grano y extracción de agua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90650','monumento','Jardines de Alfabia','Espectacular y monumental complejo palaciego y paisajístico de origen islámico profundamente reformado en el siglo XVIII que destaca por fusionar de forma óptima un palacio señorial barroco provisto de artesonados mudéjares con un gran jardín romántico con fuentes monumentales, estanques y pérgolas integradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90650','iglesia','Iglesia de San Mateo de Bunyola','Templo parroquial levantado en el siglo XVIII en estilo barroco clasicista que cuenta con una amplia nave longitudinal, una fachada principal de sillería vista con un gran óculo central moldurado y un recio campanario de torre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90018','iglesia','Iglesia de San Juan Bautista de Calvià','Templo parroquial reedificado en el siglo XIX sobre una estructura medieval anterior en un estilo historicista que combina elementos neoclásicos y neorrománicos, destacando sus dos esbeltas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90018','monumento','Parque Arqueológico del Puig de sa Morisca (Santa Ponça)','Destacado asentamiento fortificado de la cultura talayótica que conserva las plantas completas de piedra de sus viviendas, murallas defensivas de mampostería seca y silos para cereal excavados en el terreno. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90651','iglesia','Iglesia de San Miguel de Campanet','Excepcional joya del gótico primitivo rural mallorquín construida a principios del siglo XIV en cantería perfecta, caracterizada por su austera planta de nave única con arcos diafragmáticos apuntados que sostienen la cubierta de madera y una espadaña de dos vanos sobre el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07005','iglesia','Iglesia de San Julián de Campos','Templo parroquial de factura neoclásica del siglo XIX construido sobre un oratorio medieval anterior que presenta una amplia nave con capillas laterales, una fachada de sillería con portalada de piedra moldurada y un robusto campanario de planta cuadrangular que alberga una valiosa pintura del artista barroco Bartolomé Esteban Murillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90019','monumento','Castillo de Capdepera','Monumental e imponente complejo militar e histórico fortificado iniciado en el siglo XIV por orden del rey Jaime II que destaca por su recinto amurallado de sillería caliza regular, sus almenas perimetrales, sus torres de vigía cilíndricas exentas y la iglesia de Nuestra Señora de la Esperanza con muros defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90019','monumento','Torre de Canyamel','Esbelta e imponente torre de defensa de planta cuadrangular erigida en sillería de piedra arenisca local del siglo XIII de origen islámico que constituía el elemento de vigía y defensa señorial más importante de la comarca, conservando sus matacanes y saeteras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07006','catedral','Catedral de Santa María de Ciutadella','Magna y monumental basílica gótica construida entre los siglos XIII y XIV por orden del rey Alfonso III que constituye el edificio histórico más señero de la isla, caracterizada por su imponente nave única de gran anchura con bóvedas de crucería calada, portadas ojivales molduradas y un robusto campanario de torre de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07006','palacio','Palacio de Torre-Saura (Plaza del Born)','Suntuosa residencia palaciega del neoclásico civil construida en el siglo XIX que presenta una fastuosa fachada de sillería de piedra de marès vista combinada con una monumental columnata jónica, ventanas con molduras clasicistas y un patio de armas interior de gran belleza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07006','monumento','Naveta de Tudons (Naveta d''es Tudons)','Monumento arqueológico excepcional de la cultura talayótica único en Europa, consistente en una estructura funeraria colectiva exenta de la Edad del Bronce construida con grandes bloques de piedra caliza aparejada en seco con forma de casco de nave invertido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07006','palacio','Palacio Vivó y Red de Palacetes Señoriales','Conjunto de suntuosas casonas residenciales de los siglos XVII al XIX que exhiben fachadas historicistas y eclécticas con barandillas de hierro forjado ondulantes, esgrafiados florales y tradicionales portadas heráldicas de sillería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90652','iglesia','Iglesia de Nuestra Señora de la Visitación','Templo parroquial de factura barroca y ecléctica levantado en el siglo XIX que presenta una amplia nave con capillas laterales, una fachada de sillería caliza vista con portal moldurado flanqueada por pilastras y un campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07007','iglesia','Santuario Talayótico de Son Corró','Yacimiento arqueológico excepcional de la cultura talayótica que conserva un santuario exento de sillería caliza regular donde se descubrieron los célebres "Toros de Costitx", tres colosales cabezas de buey talladas en bronce del siglo V a.C. que hoy constituyen joyas cumbres de la metalurgia prehistórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90020','monumento','Conjunto Histórico-Artístico de la Villa de Deià','Núcleo urbano tradicional que destaca por la conservación impecable de su trazado escalonado en una ladera de la sierra de Tramuntana con calles empedradas jalonadas de masías de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90020','iglesia','Iglesia de San Juan Bautista','Templo parroquial de origen medieval profundamente reformado en época barroca que se alza en la cumbre del cerro que corona la villa, caracterizado por su robusta torre-campanario cuadrangular que ejercía funciones de vigía costera contra la piratería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90653','monumento','Recinto Amurallado de Dalt Vila','Espectacular y monumental recinto fortificado de época renacentista (siglo XVI) declarado Patrimonio de la Humanidad por la UNESCO al constituir el ejemplo más completo y mejor conservado de fortificación abaluartada del Mediterráneo, jalonado de potentes baluartes de sillería de piedra caliza, fosos defensivos y portales monumentales de acceso como el Portal de Ses Taules.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90653','catedral','Catedral de la Virgen de las Nieves (Catedral de Santa María)','Magna basílica gótica del siglo XIV profundamente transformada en época barroca que se alza en la cumbre del cerro de Dalt Vila, caracterizada por su planta de nave única, una imponente torre-campanario de planta cuadrangular provista de ventanales calados y muros defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90653','monumento','Necrópolis Púnica de Puig des Molins','Monumental y musealizado yacimiento arqueológico fenicio y púnico que constituye la necrópolis más grande y mejor conservada de la antigüedad mediterránea, al albergar miles de tumbas subterráneas (hipogeos) excavadas directamente en la roca caliza viva de la ladera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90654','iglesia','Santuario de Santa María de Lluc','Monumental e impresionante complejo conventual de la orden de los Misioneros de los Sagrados Corazones edificado a partir del siglo XVII que constituye el centro espiritual de Mallorca, el cual destaca por su fastuosa iglesia barroca con una fachada retablo de sillería de piedra caliza de líneas clásicas y por custodiar la venerada imagen mariana de la virgen.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90654','monumento','Cómo llegar a las Illes Balears por mar','Cómo llegar a las Illes Balears por mar (Mallorca, Menorca, Ibiza, Formentera) Por mar Los principales puertos de las Illes Balears son los de Palma de Mallorca, Alcúdia (Mallorca), Maó (Menorca), Ciutadella d...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90654','monumento','Mallorca con niños | Blog EntreOlas Si los pequeños disfrutan de la historia, tampoco pueden dejar de visitar la ciudad','Mallorca con niños | Blog EntreOlas Si los pequeños disfrutan de la historia, tampoco pueden dejar de visitar la ciudad amurallada de Alcúdia, un núcleo ahora turísti...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90654','monumento','Fiestas, Ferias, Romerías... de las Illes Balears ARTÀ','Fiestas, Ferias, Romerías... de las Illes Balears ARTÀ es un municipio de la comunidad autónoma de las Illes Balears. Situado en la isla de Mallorca y perteneciente a la comarca de...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90655','monumento','La Granja de Esporles','Monumental palacio señorial e historicista levantado sobre una antigua alquería islámica y posterior cenobio cisterciense del siglo XII que destaca por su fastuoso patio central con surtidores, galerías porticadas de madera noble, amplios salones nobles y un frondoso jardín romántico integrado en un desfiladero natural de la sierra de Tramuntana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90655','iglesia','Iglesia de San Pedro','Templo parroquial levantado a finales del siglo XIX en un riguroso estilo neogótico que cuenta con una amplia nave longitudinal con bóvedas de crucería calada, una fachada de sillería vista de piedra caliza (marès) y un esbelto campanario calado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90656','monumento','Torre de Tem Alemany','Antigua e imponente torre de defensa urbana del siglo XVI de planta cuadrangular ejecutada en mampostería regular con mortero de cal que conserva sus saeteras y se halla integrada en la estructura residencial de la villa para la protección contra los corsarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90656','iglesia','Iglesia de San Juan Bautista','Templo de base medieval profundamente transformado en el barroco rural que presenta una fachada enlucida con portal de cantería moldurada, un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90657','monumento','Poblado Talayótico de Son Mercer de Baix','Espectacular asentamiento prehistórico de la Edad del Bronce que conserva un conjunto de navetas de habitación exentas de gran valor arqueológico, destacando la denominada "Cueva del Moro", una estructura construida con grandes bloques de piedra caliza aparejada en seco con columnas exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90657','monumento','Castillo de Santa Águeda (Castell de Santa Àgueda)','Ruinas de una estratégica fortificación militar islámica (siglo XIII) emplazada en la cumbre de una colina de las que subsisten potentes lienzos de muralla de mampostería basta y saeteras que controlaban el paso septentrional de la isla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07009','iglesia','Iglesia de San Francisco Javier','Templo fortificado de traza barroca rural construido a principios del siglo XVIII mediante muros ciegos de sillería caliza de gran grosor concebidos para resistir los bombardeos de la piratería berberisca, caracterizado por su austera fachada encalada y portal adintelado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07009','monumento','Torre de sa Punta Prima','Esbelta torre de vigía y defensa costera erigida en el siglo XVIII de planta circular y sillería perfecta de piedra local que conserva saeteras originales y se alza de forma espectacular sobre un acantilado de la costa meridional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07009','monumento','Sepulcro Megalítico de Ca na Costa','Monumento arqueológico de la Edad del Bronce inicial (año 2000 a.C.) que constituye la estructura dolménica más importante de las islas Pitiusas al conservar su cámara funeraria delimitada por grandes losas calizas dispuestas de forma radial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90658','monumento','Conjunto Histórico de la Villa de Fornalutx','Núcleo urbano tradicional galardonado por su impecable conservación de la arquitectura tradicional mallorquina en plena sierra de Tramuntana, jalonado de calles empedradas escalonadas con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90658','iglesia','Iglesia de la Natividad de la Virgen','Templo parroquial de origen románico profundamente reformado en época barroca que presenta una fachada de sillería vista con portal clasicista moldurada flanqueada por pilastras y un campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07027','iglesia','Iglesia de Santa María la Mayor','Monumental basílica de traza barroca clasicista edificada en el siglo XVIII que presenta una fachada de sillería caliza vista con portada monumental flanqueada por pilastras, un amplio interior de nave única de gran anchura y un robusto campanario cuadrangular rematado por balaustrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07027','monumento','Claustro de San Francisco (Sant Francesc)','Cenobio franciscano fundado en el siglo XIV que conserva un claustro renacentista de líneas clasicistas muy sobrias ejecutado en cantería perfecta del que destaca un ala completa con arcadas de medio punto soportadas por columnas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07027','monumento','Los "Cellers" Tradicionales (Celler Cooperatiu)','Conjunto de antiguas bodegas e infraestructuras agrarias de los siglos XVIII y XIX reconvertidas que destacan por albergar grandes espacios diáfanos estructurados mediante monumentales arcos diafragmáticos de piedra y colosales toneles de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07011','iglesia','Convento de la Virgen de Loreto','Complejo cenobítico edificado en el siglo XVIII en estilo barroco rural que presenta una fachada enlucida muy sobria con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07029','palacio','Palacio de Aiamans (Palau d''Aiamans)','Suntuosa mansión señorial de arquitectura ecléctica e historicista reconstruida a principios del siglo XX sobre las bases de una antigua casa fuerte medieval, caracterizada por sus fachadas clasicistas de sillería, grandes balconadas y un frondoso jardín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07030','iglesia','Iglesia de San Feliu','Templo parroquial de traza barroca rural (siglo XVIII) edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una portada clasicista de cantería moldurada flanqueada por pilastras y un recio campanario de torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07031','iglesia','Iglesia de San Miguel','Monumental basílica reedificada en el siglo XIX en estilo neoclásico por el arquitecto Isidro González Velázquez que destaca por su imponente fachada de sillería caliza vista de grandes dimensiones flanqueada por pilastras, un amplio interior de tres naves y un robuso campanario octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07031','monumento','Torre de Cala Pi','Torre de vigía y defensa costera contra la piratería berberisca erigida en el siglo XVI de planta circular y sillería basáltica regular que conserva saeteras y las ménsulas del desaparecido matacán superior, emplazada sobre un acantilado de la costa meridional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07031','monumento','Poblado Talayótico de Capocorb Vell','Espectacular y musealizado asentamiento de la cultura talayótica que constituye uno de los complejos prehistóricos más extensos al conservar las plantas completas de piedra de cinco grandes talayots (tres circulares y dos cuadrados) y viviendas colectivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07012','iglesia','Iglesia de Nuestra Señora de los Dolores','Monumental templo parroquial levantado a finales del siglo XIX en estilo historicista neogótico por el arquitecto José Fabregas que destaca por su esbelto campanario exento de aguja piramidal de ochenta metros de altura, su fachada con un gran rosetón y ventanales apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07012','palacio','Torre del Palacio (Torre del Palau)','Único vestigio en pie del desaparecido castillo palacio residencial de los reyes de Mallorca de la villa, consistente en una robusta e imponente torre de vigía del siglo XIV de planta cuadrangular ejecutada con aparejo regular de sillería calcárea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07012','iglesia','Yacimiento de la Basílica Paleocristiana de Son Peretó','Complejo arqueológico del siglo V d.C. que conserva las plantas completas de piedra de un templo litúrgico paleocristiano, salas de baptisterio con espectaculares pavimentos de mosaico polícromo de opus tessellatum y necrópolis exentas de cista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07034','iglesia','Iglesia de San Juan Bautista','Pequeño templo de traza barroca rural edificado en el siglo XVIII que presenta una fachada de sillería vista con portalada clasicista moldurada, un interior de nave única cubierto con bóvedas de lunetos y un campanario de torre cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90021','monumento','Fortaleza de la Mola (Isabel II)','Monumental e imponente complejo militar de época borbónica (siglo XIX) construido a la entrada del puerto que constituye una de las fortificaciones abaluartadas más grandes de Europa al conservar sus kilómetros de fosos defensivos de sillería caliza, casamatas y polvorines abovedados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90021','iglesia','Iglesia de Santa María y su Órgano Monumental','Templo de traza barroca y neoclásica edificado en el siglo XVIII que destaca por albergar en su interior un colosal órgano monumental de madera tallada construido en 1810 por el maestro suizo Johann Kyburz, hito de la organería mundial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90021','monumento','San Roque (Portal de Sant Roc)','Único vestigio monumental de las antiguas murallas medievales de la capital del siglo XIV, consistente en una imponente puerta fortificada flanqueada por dos robustas torres cilíndricas de sillería de piedra de marès con arcos apuntados dovelados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90021','monumento','Lazareto de Mahón','Espectacular complejo sanitario e industrial exento construido a finales del siglo XVIII en una isla del puerto que constituye una joya de la arquitectura civil ilustrada al conservar sus inmensos muros de sillería de aislamiento y pabellones de cuarentena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90659','iglesia','Iglesia de San Marcial','Templo parroquial de factura barroca del siglo XVIII que exhibe una fachada de sillería caliza vista con portada clasicista moldurada, un interior de tres naves de gran amplitud y dos esbeltas torres-campanario de planta cuadrangular asimétricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90659','monumento','Centro de Interpretación de la Alfarería Tradicional','Caserón tradicional que funciona como espacio etnográfico para salvaguardar la larga tradición cerámica de la villa al conservar intactos los antiguos hornos de cocción manual de arcilla y barro de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07037','iglesia','Santuario de la Virgen del Toro','Monumental complejo religioso del siglo XVII emplazado en la cumbre del Monte Toro (punto más alto de la isla) que cuenta con una iglesia de nave única con fachada enlucida muy sobria, un gran patio porticado de piedra, una torre de vigía medieval y una hospedería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07037','monumento','Castillo de San Antonio (Fornells)','Ruinas consolidadas de una fortaleza militar costera del siglo XVII construida por ingenieros de la corona borbónica de la que subsisten lienzos de la muralla de sillería basáltica regular y fosos defensivos destinados a la protección de la bahía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07037','monumento','Torre de Fornells','Esbelta torre de vigía de planta circular erigida en sillería de piedra caliza durante el periodo de dominación británica (siglo XIX), caracterizada por sus potentes muros reforzados concebidos para resistir los bombardeos de artillería naval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07902','monumento','Poblado Talayótico de San Agustín (Sant Agustí)','Espectacular asentamiento prehistórico de la cultura talayótica que destaca por conservar un colosal talayot central de planta circular y sillería ciclópea que mantiene intacta su viguería interior de vigas de madera de acebuche originales de la Edad del Bronce.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07014','monumento','Yacimiento de es Velar (Poblado de Son Fornés)','Monumental asentamiento fortificado de la cultura talayótica que conserva dos colosales talayots de planta circular construidos con aparejo ciclópeo de mampostería seca, viviendas colectivas intercomunicadas y silos excavados en el terreno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07039','iglesia','Iglesia de San Juan Bautista','Monumental templo de estilo gótico tardío y renacentista construido en el siglo XVI que presenta una imponente fachada de sillería vista con portada clasicista flanqueada por pilastras molduradas y una robusta torre-campanario de planta cuadrada calada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07039','monumento','Museo Etnológico de Muro (Casa de Alomar)','Palacio señorial del siglo XVII que constituye una muestra óptima de la arquitectura doméstica tradicional mallorquina al conservar','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07016','iglesia','Convento de San Bernardino y Casa Natal de Fray Junípero Serra','Complejo religioso franciscano del siglo XVII de estilo barroco rural profundamente vinculado a la memoria del célebre misionero fundador de las misiones de California, conservando la casa solariega de muros de mampostería basta y viguería noble tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07016','iglesia','Iglesia de San Pedro de Petra','Monumental templo gótico tardío construido en sillería caliza regular en el siglo XVI que presenta una imponente nave única de gran anchura, capillas laterales entre contrafuertes robustos provistas de ventanales y un robusto campanario de planta octogonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90660','iglesia','Iglesia de San Juan Bautista','Templo parroquial levantado en el siglo XVIII bajo las directrices del estilo barroco clasicista que muestra una fachada de sillería caliza vista con portada moldurada entre pilastras, una amplia nave con capillas intercomunicadas y un esbelto campanario octogonal con remate balaustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07017','monumento','El Calvario de Pollença (El Calvari) y su Escalinata','Monumental vía sacra que consta de una impresionante escalinata barroca exenta de 365 peldaños tallados en piedra de sillería flanqueada por cipreses centenarios, la cual asciende desde el casco urbano hasta un oratorio del siglo XVIII que corona la colina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07017','monumento','Puente Romano de Pollença (Pont Romà)','Infraestructura civil de origen romano reconstruida en época medieval que salva el cauce del torrente de Sant Jordi mediante dos grandes arcadas de medio punto decrecientes ejecutadas en sillería de piedra caliza regular con tajamares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07017','iglesia','Convento de Santo Domingo (Sant Domingo)','Complejo cenobítico edificado en el siglo XVII que destaca por su bellísimo claustro barroco de líneas clásicas muy sobrias ejecutado en cantería perfecta, caracterizado por sus cuatro alas de galerías porticadas de arcos de medio punto sobre esbeltas columnas con capiteles jónicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07018','iglesia','Iglesia de Nuestra Señora de la Consolación','Templo parroquial de factura barroca del siglo XVIII conocido popularmente como la "Catedral del Pla" debido a sus dimensiones monumentales, el cual destaca por su imponente fachada de sillería vista con portada clasicista flanqueada por columnas y un recio campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07045','monumento','Casal de Son領at','Suntuoso palacio residencial de arquitectura tradicional mallorquina estructurado a partir del siglo XVII mediante aparejo de mampostería regular enlucida que destaca por su patio de armas central porticado de madera noble de pino tea y amplios salones señoriales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90661','monumento','Salinas de s''Avall','Complejo preindustrial e hidráulico de origen medieval y romano destinado a la extracción de sal marina que constituye uno de los monumentos salineros más antiguos del Mediterráneo al conservar sus canalizaciones de piedra basta y bancales de decantación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90662','iglesia','Iglesia de San Antonio de Portmany','Templo fortificado de traza barroca rural (siglo XVII) edificado mediante muros ciegos de sillería caliza de gran grosor concebidos para resistir los ataques piratas, caracterizado por su austera fachada encalada de líneas simétricas y un artesonado interior mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90022','iglesia','Iglesia de San Juan Bautista','Pequeño santuario de traza barroca rural emplazado en un entorno montañoso de la isla que presenta una fisonomía encalada tradicional de gran sencillez con un porche delantero techado a dos aguas para refugio de los fieles y una espadaña de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07019','iglesia','Santuario de Nuestra Señora de la Consolación','Edificio religioso de época barroca edificado con aparejo de mampostería regular enlucida que muestra una amplia nave longitudinal, una portada de cantería moldurada con hornacina superior y un esbelto campanario que domina la llanura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90023','monumento','Torre d''en Rovira','Torre de vigía y defensa costera contra la piratería berberisca erigida en el siglo XVI de planta circular y sillería basáltica regular que conserva saeteras y las ménsulas del desaparecido matacán superior, emplazada sobre un acantilado de la costa occidental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90023','monumento','Yacimiento Arqueológico del Poblado Fenicio de Sa Caleta','Vestigios históricos del primer asentamiento y factoría pesquera fundada por los colonos fenicios en el siglo VIII a.C. en la costa meridional de la isla, del que se conservan las plantas completas de piedra de sus viviendas colectivas de mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90663','monumento','Núcleos de población de Sant Llorenç des Cardassar','El término municipal incluye los siguientes núcleos de población: Sa Coma y S''Illot.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90663','monumento','Yacimiento de s''Illot (Poblado Talayótico)','Monumental asentamiento fortificado de la cultura talayótica que conserva un colosal talayot de planta circular construido con aparejo ciclópeo de mampostería seca y viviendas colectivas intercomunicadas de gran valor arqueológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07052','monumento','Molino de de Viento de Dalt (Molí de Dalt)','Estructura etnográfica preindustrial e industrial de origen francés levantada en el siglo XVIII mediante una esbelta torre cilíndrica de sillería de piedra de marès blanca regular que conserva sus engranajes de madera tradicionales y el velamen original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07054','monumento','Conjunto Histórico del Puig de Missa','Espectacular núcleo fortificado sacra emplazado en la cumbre de un cerro rocoso, constituido por una monumental iglesia fortificada de traza barroca rural del siglo XVI con potentes muros encalados ciegos, un gran porche columnado y torreones de defensa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07053','iglesia','Iglesia de Santa Eugenia','Templo parroquial de factura barroca rural reedificado en el siglo XVIII que presenta una fachada enlucida con portal de cantería moldurada, una nave','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07020','iglesia','Iglesia de San Andrés de Santanyí','Monumental templo barroco clasicista construido en el siglo XVIII con sillería de la célebre piedra caliza dorada de Santanyí que destaca por su imponente fachada exenta provista de un portal neoclásica moldurada flanqueada por columnas y un campanario cuadrangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07020','monumento','Fortín de Cala d''Or (Es Fortí)','Fortaleza militar costera de planta cuadrangular levantada en el siglo XVIII por ingenieros de la corona borbónica para la defensa de la costa oriental frente a los ataques piratas, la cual conserva sus potentes baluartes de cantería y casamatas interiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07058','iglesia','Iglesia de San Lorenzo de Selva','Templo parroquial de origen románico profundamente transformado en época gótica tardía y barroca que destaca por su fastuosa portada de múltiples arquivoltas molduradas sobre columnas con capiteles historiados de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07047','monumento','Yacimiento Talayótico de Son Fred','Destacado asentamiento fortificado de la cultura talayótica que conserva un colosal talayot de planta circular y sillería ciclópea de mampostería seca, además de estructuras habitacionales e industriales colectivas asociadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07022','iglesia','Palacio de los Reyes de Mallorca (Convento de San José)','Palacio residencial fortificado de estilo gótico civil mallorquín construido en el siglo XIV por orden del rey Jaime II que funciona como cenobio, caracterizado por su fachada de sillería de cantería regular y su patio de armas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07022','iglesia','Iglesia de Santa María de Sineu','Monumental templo gótico del siglo XIV profundamente reconstruido tras un incendio que presenta una imponente nave única de gran anchura, capillas laterales entre contrafuertes robustos provistas de ventanales y un recio campanario exento de torre cuadrangular de siete pisos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07023','iglesia','Iglesia de San Bartolomé de Sóller','Monumental basílica de origen medieval cuya fastuosa fachada modernista neogótica diseñada por el arquitecto Joan Rubió i Bellver a principios del siglo XX constituye un hito mundial al estar tallada en sillería caliza gris con pináculos calados orgánicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07023','monumento','Banco de Sóller','Obra cumbre del modernismo catalán proyectada por Joan Rubió en 1912 que destaca por su fachada ricamente ornamentada con voladizos de piedra caliza calada de inspiración orgánica contemporánea, grandes tribunas simétricas y barandillas de hierro forjado artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07023','monumento','Torre de Picada','Esbelta e imponente torre de vigía y defensa costera erigida en el siglo XVII de planta circular construida con aparejo de mampostería regular, colgada sobre un espectacular acantilado marino que domina estratégicamente el muelle portuario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07062','iglesia','Iglesia Nueva de Son Servera (Església Nova)','Monumental e imponente templo historicista neogótico proyectado a principios del siglo XX por el arquitecto Joan Rubió i Bellver que constituye un espacio cultural único en el archipiélago al haber quedado inacabado y exento, conservando sus monumentales arcos apuntados calados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07063','iglesia','Real Cartuja de Valldemossa (Cartoixa de Valldemossa)','Monumental e impresionante complejo palaciego y cenobítico de la orden de los cartujos fundado en el siglo XIV sobre un antiguo palacio del rey Sancho de Mallorca, célebre por su fastuosa iglesia barroca neoclásica provista de una esbelta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07063','palacio','Palacio del Rey Sancho','Palacio señorial del gótico civil mallorquín que conserva sus murallas de sillería caliza regular de su torre cuadrangular, tramos de arcos apuntados de gran pureza formal, hermosos patios de armas de madera noble y salas nobles abovedadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07024','iglesia','Iglesia de Santa Bárbara','Templo parroquial de factura barroca rural reedificado en el siglo XVIII que presenta una fachada enlucida con portal de cantería moldurada, una nave diáfana con capillas laterales y una robusta torre-campanario de planta cuadrangular.','inventario_monumentos_pdf');
